window.RECIPES = [{"slug": "asparagus-risotto", "name": "Asparagus Risotto", "title": "asparagus risotto", "tags": ["recipe", "vegetarian", "rice", "dinner"], "terms": ["asparagus", "butter", "garlic", "onion", "parmesan", "rice", "stock", "white wine"], "image": true, "serves": "", "time": "", "items": [{"t": "12 asparagus spears, with only the tough ends discarded", "k": "asparagus"}, {"t": "1.25L chicken stock, preferably homemade", "k": "stock"}, {"t": "1 medium onion, finely chopped", "k": "onion"}, {"t": "1 garlic clove, finely chopped", "k": "garlic"}, {"t": "500g Carnaroli risotto rice", "k": "rice"}, {"t": "250ml white wine", "k": "white wine"}, {"t": "150-175g Parmesan, grated", "k": "parmesan"}, {"t": "50g butter", "k": "butter"}], "html": "<header><h1>Asparagus Risotto<\/h1><p class=\"tags\"><span class=\"tag\">vegetarian<\/span><span class=\"tag\">rice<\/span><span class=\"tag\">dinner<\/span><\/p><\/header>\n<img class=\"hero\" src=\"img/asparagus-risotto-1600.jpg\" srcset=\"img/asparagus-risotto-800.jpg 800w, img/asparagus-risotto-1600.jpg 1600w\" sizes=\"(max-width: 500px) calc(100vw - 40px), (max-width: 940px) 92vw, (max-width: 1200px) calc(940px - 8vw), 844px\" decoding=\"async\" alt=\"Asparagus Risotto\">\n\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>12 asparagus spears, with only the tough ends discarded<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1.25L chicken stock, preferably homemade<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tbsp olive oil<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 medium onion, finely chopped<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 garlic clove, finely chopped<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>500g Carnaroli risotto rice<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>250ml white wine<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>150-175g Parmesan, grated<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>50g butter<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Cracked pepper &amp; sea salt, to taste<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><ol class=\"method\" start=\"1\"><li>Bring a large saucepan of water to a boil. Blanch the <strong>12 asparagus spears<\/strong> by placing them in the boiling water for 1-2 minutes until bright green (1 minute for a crunchier texture). Immediately transfer the stalks to a bowl of ice water to stop the cooking. Once cool, chop off the top third of the stalks and set them aside.<\/li><li>To the same saucepan, add the remaining ends of the <strong>asparagus<\/strong> to the <strong>1.25L chicken stock<\/strong> and simmer for 20 minutes to infuse the flavour. Discard the ends and keep the stock warm.<\/li><li>Heat the <strong>1 tbsp olive oil<\/strong> in a sauté pan or cocotte. Add the <strong>1 medium onion<\/strong> and fry over low heat for 4-5 minutes, stirring continuously, until translucent. Add the <strong>1 garlic clove<\/strong> and fry for another minute. Season with a generous pinch of <strong>sea salt<\/strong>.<\/li><li>Add the <strong>500g Carnaroli risotto rice<\/strong> and cook, stirring, for 2 minutes until the grains are glossy and fully covered in the oil. Add more <strong>oil<\/strong> if needed.<\/li><li>Increase the temperature to medium and add the <strong>250ml white wine<\/strong>. Once the wine is absorbed, add a ladle of <strong>chicken stock<\/strong>. Continue to stir and simmer gently until the liquid has been absorbed. Repeat this process, adding a ladle of <strong>stock<\/strong> at a time, until the <strong>rice<\/strong> is tender (about 15 minutes).<\/li><li>Finally, stir in the reserved <strong>asparagus tops<\/strong> and the <strong>150-175g Parmesan<\/strong>. Add the <strong>Parmesan<\/strong> in batches until the desired consistency is reached. Season to taste with <strong>sea salt and cracked pepper<\/strong>, then stir through the <strong>50g butter<\/strong>. Serve immediately.<\/li><\/ol><\/section>\n<\/div>\n\n<p class=\"source\">Source: <a href=\"https://www.boroughkitchen.com/blogs/news/justins-english-asparagus-risotto\" rel=\"noreferrer\">https://www.boroughkitchen.com/blogs/news/justins-english-asparagus-risotto<\/a><\/p><p class=\"source\"><a href=\"asparagus-risotto.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "aubergine-bulgar-roast", "name": "Aubergine Bulgar Roast", "title": "aubergine bulgar roast", "tags": ["recipe", "vegetarian", "bulgur", "lunch"], "terms": ["aubergine", "bulgur wheat", "cinnamon", "feta", "lemon", "nutmeg", "olives", "onion", "parsley", "pomegranate", "rocket", "stock"], "image": true, "serves": "3", "time": "25m", "items": [{"t": "200g bulgur wheat, rinsed", "k": "bulgur wheat"}, {"t": "400ml vegetable stock", "k": "stock"}, {"t": "100g green pitted olives", "k": "olives"}, {"t": "1 large aubergine, sliced into ½cm half moons", "k": "aubergine"}, {"t": "1 red onion, thickly sliced", "k": "onion"}, {"t": "1 scant tsp ground cinnamon", "k": "cinnamon"}, {"t": "½ a nutmeg, grated", "k": "nutmeg"}, {"t": "25g flat-leaf parsley leaves, finely chopped", "k": "parsley"}, {"t": "100g rocket, finely chopped", "k": "rocket"}, {"t": "1 lemon, juice only, plus more if needed", "k": "lemon"}, {"t": "200g feta cheese, crumbled", "k": "feta"}, {"t": "1 pomegranate, seeds only", "k": "pomegranate"}], "html": "<header><h1>Aubergine Bulgar Roast<\/h1><p class=\"meta\">Serves 3 · 10m prep · 25m cook<\/p><p class=\"tags\"><span class=\"tag\">vegetarian<\/span><span class=\"tag\">bulgur<\/span><span class=\"tag\">lunch<\/span><\/p><p class=\"lede\">Cinnamon-spiced aubergines with feta cheese, olives and herbed bulgur wheat.<\/p><\/header>\n<img class=\"hero\" src=\"img/aubergine-bulgar-roast-1600.jpg\" srcset=\"img/aubergine-bulgar-roast-800.jpg 800w, img/aubergine-bulgar-roast-1600.jpg 1600w\" sizes=\"(max-width: 500px) calc(100vw - 40px), (max-width: 940px) 92vw, (max-width: 1200px) calc(940px - 8vw), 844px\" decoding=\"async\" alt=\"Aubergine Bulgar Roast\">\n<p class=\"before\"><strong>Before you start<\/strong> heat the oven to 220°C/fan 200°C/gas 7.<\/p>\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>200g bulgur wheat, rinsed<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>400ml vegetable stock<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>100g green pitted olives<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 large aubergine, sliced into ½cm half moons<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 red onion, thickly sliced<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 scant tsp ground cinnamon<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>½ a nutmeg, grated<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tsp sea salt flakes<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 tbsp olive oil<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>25g flat-leaf parsley leaves, finely chopped<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>100g rocket, finely chopped<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 lemon, juice only, plus more if needed<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tbsp extra virgin olive oil<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>200g feta cheese, crumbled<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 pomegranate, seeds only<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><ol class=\"method\" start=\"1\"><li>Preheat the oven to 220°C/fan 200°C/gas 7. You will need two roasting tins for this dish — doing it all in one tin does not work, as the aubergines do not crisp.<\/li><li>Tip the <strong>200g bulgur wheat<\/strong>, <strong>400ml vegetable stock<\/strong> and <strong>100g green olives<\/strong> into a smaller roasting tin while you get on with slicing the aubergine and onion.<\/li><li>Mix the <strong>1 large aubergine<\/strong> and <strong>1 red onion<\/strong> with the <strong>1 scant tsp ground cinnamon<\/strong>, <strong>½ grated nutmeg<\/strong>, <strong>1 tsp sea salt flakes<\/strong> and <strong>2 tbsp olive oil<\/strong> in a second roasting tin, large enough to hold everything in a single layer.<\/li><li>Transfer both roasting tins to the oven for 25 minutes, until the aubergines are crisp and cooked through and the bulgur wheat is fluffy, with all the stock absorbed.<\/li><li>Stir the <strong>25g parsley<\/strong>, <strong>100g rocket<\/strong>, <strong>juice of 1 lemon<\/strong> and <strong>1 tbsp extra virgin olive oil<\/strong> through the bulgur wheat, then taste and adjust the salt and lemon juice as needed.<\/li><li>Let everything cool down, then transfer the bulgur wheat into lunchboxes, top with the roasted aubergines and scatter the <strong>200g feta cheese<\/strong> and <strong>pomegranate seeds<\/strong> over the top. Refrigerate until needed.<\/li><\/ol><\/section>\n<\/div>\n<section class=\"notes\"><h2>Notes<\/h2><p>Makes 3 lunchboxes. Lovely at room temperature, or warmed through.<\/p><p>Make it vegan: leave out the feta cheese at the end and add a tin of drained, rinsed chickpeas with the aubergines at step 3 for some added protein.<\/p><p>Transcribed from a photographed cookbook page (p.78).<\/p><\/section>\n<p class=\"source\"><a href=\"aubergine-bulgar-roast.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "black-bean-birria", "name": "Black Bean Birria", "title": "black bean birria", "tags": ["recipe", "vegetarian", "beans", "one-pot", "dinner"], "terms": ["avocado", "black beans", "celery", "chilli", "chilli flakes", "cinnamon", "coriander", "cumin", "feta", "garlic", "jalapeño", "lime", "naan", "onion", "rice", "stock", "sweetcorn", "tomato purée", "tortillas", "yoghurt"], "image": true, "serves": "3", "time": "45m", "items": [{"t": "1 dried ancho chilli (or 2 tsp smoked paprika + ¼ tsp chilli powder)", "k": "chilli"}, {"t": "1 onion, finely chopped", "k": "onion"}, {"t": "1 celery stick, finely chopped", "k": "celery"}, {"t": "4 fat garlic cloves, finely grated or chopped", "k": "garlic"}, {"t": "½ red chilli, seeds removed and finely sliced", "k": "chilli"}, {"t": "1 tsp cumin seeds or 2 tsp ground cumin", "k": "cumin"}, {"t": "2 tbsp tomato purée", "k": "tomato purée"}, {"t": "½ tsp cinnamon", "k": "cinnamon"}, {"t": "1 x 700g jar of Queen Black Beans, with their bean stock", "k": "black beans"}, {"t": "200ml vegetable stock", "k": "stock"}, {"t": "1 lime", "k": "lime"}, {"t": "A handful of coriander leaves", "k": "coriander"}, {"t": "Rotis, flatbreads or soft tortillas", "k": "tortillas"}, {"t": "200g feta cheese, crumbled (or plant-based alternative)", "k": "feta"}, {"t": "2 avocados, sliced", "k": "avocado"}, {"t": "A pinch of chilli flakes", "k": "chilli flakes"}, {"t": "Diced raw or pickled red onion", "k": "onion"}, {"t": "Pickled jalapeños", "k": "jalapeño"}, {"t": "Greek or natural yoghurt (or plant-based alternative)", "k": "yoghurt"}, {"t": "Sweetcorn", "k": "sweetcorn"}, {"t": "Rice", "k": "rice"}], "html": "<header><h1>Black Bean Birria<\/h1><p class=\"meta\">Serves 3 · 45m<\/p><p class=\"tags\"><span class=\"tag\">vegetarian<\/span><span class=\"tag\">beans<\/span><span class=\"tag\">one-pot<\/span><span class=\"tag\">dinner<\/span><\/p><p class=\"lede\">A meat-free version of the Mexican stew, with black beans slowly simmered in ancho chilli, cumin and cinnamon.<\/p><\/header>\n<img class=\"hero\" src=\"img/black-bean-birria-1600.jpg\" srcset=\"img/black-bean-birria-800.jpg 800w, img/black-bean-birria-1600.jpg 1600w\" sizes=\"(max-width: 500px) calc(100vw - 40px), (max-width: 940px) 92vw, (max-width: 1200px) calc(940px - 8vw), 844px\" decoding=\"async\" alt=\"Black Bean Birria\">\n\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>1 dried ancho chilli (or 2 tsp smoked paprika + ¼ tsp chilli powder)<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 tbsp neutral oil, such as vegetable or sunflower<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 onion, finely chopped<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 celery stick, finely chopped<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>4 fat garlic cloves, finely grated or chopped<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>½ red chilli, seeds removed and finely sliced<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tsp cumin seeds or 2 tsp ground cumin<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 tbsp tomato purée<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>½ tsp cinnamon<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 x 700g jar of Queen Black Beans, with their bean stock<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>200ml vegetable stock<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 lime<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>A handful of coriander leaves<\/span><\/label><\/li><\/ul><h3>To serve<\/h3><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>Rotis, flatbreads or soft tortillas<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>200g feta cheese, crumbled (or plant-based alternative)<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 avocados, sliced<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>A pinch of chilli flakes<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Diced raw or pickled red onion<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Pickled jalapeños<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Greek or natural yoghurt (or plant-based alternative)<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Sweetcorn<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Rice<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><ol class=\"method\" start=\"1\"><li>Soak the <strong>1 dried ancho chilli<\/strong> in hot water to soften.<\/li><li>Heat the <strong>2 tbsp neutral oil<\/strong> in a large pan over a medium heat.<\/li><li>Add the <strong>1 onion<\/strong> and <strong>1 celery stick<\/strong> and cook for 8-10 minutes, until softened.<\/li><li>Stir in the <strong>4 garlic cloves<\/strong>, the <strong>½ red chilli<\/strong> and the <strong>1 tsp cumin seeds or 2 tsp ground cumin<\/strong>, along with the <strong>2 tsp smoked paprika and ¼ tsp chilli powder<\/strong> if you are not using the ancho chilli.<\/li><li>Cook for 2 minutes, until fragrant.<\/li><li>If you are serving with <strong>rice<\/strong>, get it on to cook now.<\/li><li>Lift the <strong>ancho chilli<\/strong> out of the water, roughly chop it and add it to the pan with the <strong>2 tbsp tomato purée<\/strong> and <strong>½ tsp cinnamon<\/strong>.<\/li><li>Cook for 2-3 minutes, stirring frequently, until the purée darkens. Add a splash of water if it starts to stick.<\/li><li>Pour in the <strong>700g jar of black beans<\/strong> with their bean stock and the <strong>200ml vegetable stock<\/strong>.<\/li><li>Bring to a simmer, cover and cook for 15-20 minutes, stirring occasionally, until the stew is chocolate brown and about the consistency of a thick soup.<\/li><li>Warm the <strong>rotis, flatbreads or tortillas<\/strong> in the microwave or in a dry pan, just until lightly browned.<\/li><li>Check the stew for seasoning and add the juice of <strong>½ a lime<\/strong> for freshness.<\/li><li>Cut the remaining <strong>lime<\/strong> into wedges.<\/li><li>Ladle the stew into bowls and top with the <strong>2 sliced avocados<\/strong>, the <strong>200g crumbled feta<\/strong>, the <strong>coriander leaves<\/strong> and a <strong>pinch of chilli flakes<\/strong>.<\/li><li>Serve with the lime wedges and the warm bread or rice, plus any other toppings you fancy.<\/li><\/ol><\/section>\n<\/div>\n<section class=\"notes\"><h2>Notes<\/h2><p>The ancho chilli is optional, but worth seeking out — it gives a real depth of smoky heat. Without it, use the smoked paprika and chilli powder.<\/p><p>Hearty enough as a stew on its own; rice, crunchy tacos or soft tortillas make it more filling.<\/p><\/section>\n<p class=\"source\">Source: <a href=\"https://boldbeanco.com/blogs/beanspo-recipes/black-bean-birria\" rel=\"noreferrer\">https://boldbeanco.com/blogs/beanspo-recipes/black-bean-birria<\/a><\/p><p class=\"source\"><a href=\"black-bean-birria.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "black-chickpea-paneer-curry", "name": "Black Chickpea + Paneer Curry", "title": "black chickpea + paneer curry", "tags": ["recipe", "vegetarian", "chickpeas", "one-pot", "dinner"], "terms": ["black chickpeas", "chilli", "coriander", "cumin", "garam masala", "garlic", "ginger", "ground coriander", "mango chutney", "naan", "onion", "paneer", "rice", "spinach", "stock", "tomato", "tomato purée", "turmeric", "yoghurt"], "image": true, "serves": "4", "time": "30m", "items": [{"t": "1 x 226g block of paneer, cut into 2cm cubes", "k": "paneer"}, {"t": "1 onion, roughly chopped", "k": "onion"}, {"t": "3 garlic cloves, finely grated or minced", "k": "garlic"}, {"t": "1 tbsp fresh ginger, finely grated or minced", "k": "ginger"}, {"t": "1 green chilli, roughly chopped, deseeded if you like it mild (optional)", "k": "chilli"}, {"t": "1 tbsp tomato purée", "k": "tomato purée"}, {"t": "1 tbsp garam masala", "k": "garam masala"}, {"t": "1 tsp ground cumin", "k": "cumin"}, {"t": "1 tsp ground turmeric", "k": "turmeric"}, {"t": "1 tsp ground coriander", "k": "ground coriander"}, {"t": "1 x 400g tin of chopped tomatoes", "k": "tomato"}, {"t": "1 x 570g jar of Queen Black Chickpeas, with their bean stock", "k": "black chickpeas"}, {"t": "70g spinach (optional)", "k": "spinach"}, {"t": "1 tbsp Greek yoghurt", "k": "yoghurt"}, {"t": "1 tsp mango chutney, plus extra to serve", "k": "mango chutney"}, {"t": "A handful of fresh coriander, roughly chopped", "k": "coriander"}, {"t": "Naan, rotis or rice", "k": "naan"}], "html": "<header><h1>Black Chickpea + Paneer Curry<\/h1><p class=\"meta\">Serves 4 · 30m<\/p><p class=\"tags\"><span class=\"tag\">vegetarian<\/span><span class=\"tag\">chickpeas<\/span><span class=\"tag\">one-pot<\/span><span class=\"tag\">dinner<\/span><\/p><p class=\"lede\">A spiced tomato curry of black chickpeas and fried paneer, finished with spinach, yoghurt and mango chutney.<\/p><\/header>\n<img class=\"hero\" src=\"img/black-chickpea-paneer-curry-1600.jpg\" srcset=\"img/black-chickpea-paneer-curry-800.jpg 800w, img/black-chickpea-paneer-curry-1600.jpg 1600w\" sizes=\"(max-width: 500px) calc(100vw - 40px), (max-width: 940px) 92vw, (max-width: 1200px) calc(940px - 8vw), 844px\" decoding=\"async\" alt=\"Black Chickpea + Paneer Curry\">\n\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>3 tbsp vegetable or coconut oil<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 x 226g block of paneer, cut into 2cm cubes<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 onion, roughly chopped<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>3 garlic cloves, finely grated or minced<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tbsp fresh ginger, finely grated or minced<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 green chilli, roughly chopped, deseeded if you like it mild (optional)<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tbsp tomato purée<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tbsp garam masala<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tsp ground cumin<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tsp ground turmeric<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tsp ground coriander<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 x 400g tin of chopped tomatoes<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 x 570g jar of Queen Black Chickpeas, with their bean stock<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>70g spinach (optional)<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tbsp Greek yoghurt<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tsp mango chutney, plus extra to serve<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>A handful of fresh coriander, roughly chopped<\/span><\/label><\/li><\/ul><h3>To serve<\/h3><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>Naan, rotis or rice<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><ol class=\"method\" start=\"1\"><li>Heat 1 tbsp of the <strong>3 tbsp oil<\/strong> in a deep frying pan over a medium-high heat.<\/li><li>Add the <strong>226g paneer<\/strong> and fry for 5 minutes, turning regularly, so each side is golden brown.<\/li><li>Lift the <strong>paneer<\/strong> out with tongs onto a plate lined with kitchen paper.<\/li><li>Heat the remaining 2 tbsp of the <strong>oil<\/strong> in the same pan over a medium-low heat.<\/li><li>Add the <strong>1 onion<\/strong> with a pinch of salt and cook for 8-10 minutes, stirring occasionally, until soft and starting to colour.<\/li><li>Add the <strong>3 garlic cloves<\/strong>, <strong>1 tbsp ginger<\/strong> and <strong>1 green chilli<\/strong> and cook for 1-2 minutes more, until fragrant.<\/li><li>Add the <strong>1 tbsp tomato purée<\/strong>, <strong>1 tbsp garam masala<\/strong>, <strong>1 tsp ground cumin<\/strong>, <strong>1 tsp ground turmeric<\/strong> and <strong>1 tsp ground coriander<\/strong> with a small splash of water, stirring to make a paste.<\/li><li>Fry for a couple of minutes, until the purée turns deep red and everything smells fragrant.<\/li><li>Pour in the <strong>400g tin of chopped tomatoes<\/strong> with a pinch of salt, stir to combine and simmer for 3-4 minutes.<\/li><li>Pour in the <strong>570g jar of black chickpeas and their bean stock<\/strong> and stir to combine.<\/li><li>Simmer for 7-8 minutes, to let the chickpeas soak up the spices.<\/li><li>Add the <strong>70g spinach<\/strong> and cook for about 4 minutes, until wilted.<\/li><li>Stir through the <strong>1 tbsp Greek yoghurt<\/strong>, <strong>1 tsp mango chutney<\/strong> and the fried <strong>paneer<\/strong>.<\/li><li>Check the seasoning and adjust to taste.<\/li><li>Spoon into bowls, top with the <strong>fresh coriander<\/strong> and serve with <strong>naan, rotis or rice<\/strong> for mopping, and extra <strong>mango chutney<\/strong>.<\/li><\/ol><\/section>\n<\/div>\n<section class=\"notes\"><h2>Notes<\/h2><p>Regular chickpeas work just as well if you cannot get black ones, though they have less bite and nuttiness.<\/p><p>Freezes well.<\/p><\/section>\n<p class=\"source\">Source: <a href=\"https://boldbeanco.com/blogs/beanspo-recipes/black-chickpea-paneer-curry-masala\" rel=\"noreferrer\">https://boldbeanco.com/blogs/beanspo-recipes/black-chickpea-paneer-curry-masala<\/a><\/p><p class=\"source\"><a href=\"black-chickpea-paneer-curry.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "bubbling-one-pan-cheesy-tomato-butter-beans", "name": "Bubbling One-Pan Cheesy Tomato Butter Beans", "title": "bubbling one-pan cheesy tomato butter beans", "tags": ["recipe", "vegetarian", "beans", "one-pot", "lunch", "dinner"], "terms": ["basil", "bread", "butter beans", "cheddar", "garlic", "lemon", "mozzarella", "onion", "oregano", "parsley", "rosemary", "salad leaves", "stock", "tomato", "tomato purée"], "image": true, "serves": "2", "time": "30m", "items": [{"t": "6 large ripe tomatoes", "k": "tomato"}, {"t": "1 small onion, diced", "k": "onion"}, {"t": "3 fat garlic cloves, finely chopped", "k": "garlic"}, {"t": "1 tbsp tomato purée", "k": "tomato purée"}, {"t": "1 tsp dried oregano", "k": "oregano"}, {"t": "1 tsp dried rosemary", "k": "rosemary"}, {"t": "A small bunch (roughly 10g) of fresh basil or parsley, finely chopped", "k": "basil"}, {"t": "1 x 660g jar of Queen Butter Beans, with their bean stock", "k": "butter beans"}, {"t": "75g mozzarella", "k": "mozzarella"}, {"t": "75g cheddar, grated", "k": "cheddar"}, {"t": "Crusty bread", "k": "bread"}, {"t": "Green salad leaves, dressed in lemon juice and olive oil", "k": "salad leaves"}], "html": "<header><h1>Bubbling One-Pan Cheesy Tomato Butter Beans<\/h1><p class=\"meta\">Serves 2 · 30m<\/p><p class=\"tags\"><span class=\"tag\">vegetarian<\/span><span class=\"tag\">beans<\/span><span class=\"tag\">one-pot<\/span><span class=\"tag\">lunch<\/span><span class=\"tag\">dinner<\/span><\/p><p class=\"lede\">Fresh tomatoes cooked down with butter beans and melted mozzarella and cheddar, all in one pan.<\/p><\/header>\n<img class=\"hero\" src=\"img/bubbling-one-pan-cheesy-tomato-butter-beans-1600.jpg\" srcset=\"img/bubbling-one-pan-cheesy-tomato-butter-beans-800.jpg 800w, img/bubbling-one-pan-cheesy-tomato-butter-beans-1600.jpg 1600w\" sizes=\"(max-width: 500px) calc(100vw - 40px), (max-width: 940px) 92vw, (max-width: 1200px) calc(940px - 8vw), 844px\" decoding=\"async\" alt=\"Bubbling One-Pan Cheesy Tomato Butter Beans\">\n\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>3 tbsp olive oil<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>6 large ripe tomatoes<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 small onion, diced<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>3 fat garlic cloves, finely chopped<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tbsp tomato purée<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tsp dried oregano<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tsp dried rosemary<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>A small bunch (roughly 10g) of fresh basil or parsley, finely chopped<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 x 660g jar of Queen Butter Beans, with their bean stock<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>75g mozzarella<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>75g cheddar, grated<\/span><\/label><\/li><\/ul><h3>To serve<\/h3><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>Crusty bread<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Green salad leaves, dressed in lemon juice and olive oil<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><ol class=\"method\" start=\"1\"><li>Heat the <strong>3 tbsp olive oil<\/strong> in a large, wide pan over a medium-low heat.<\/li><li>Cut the tops off the <strong>6 tomatoes<\/strong> and nestle them cut-side down around the edge of the pan.<\/li><li>Add the <strong>1 small onion<\/strong> to the middle of the pan and stir gently so it is coated in the oil.<\/li><li>Cover and cook for 12-15 minutes, until the tomatoes have softened and the onion has turned translucent, adding a splash of boiling water if anything starts to catch.<\/li><li>Peel away the <strong>tomato<\/strong> skins and discard them.<\/li><li>Crush the <strong>tomatoes<\/strong> into the pan with the back of a fork, keeping some texture rather than working them smooth.<\/li><li>Add the <strong>3 garlic cloves<\/strong>, <strong>1 tbsp tomato purée<\/strong>, <strong>1 tsp dried oregano<\/strong> and <strong>1 tsp dried rosemary<\/strong> with a good pinch of salt and pepper.<\/li><li>Stir well and simmer for a few minutes, until fragrant.<\/li><li>Stir through most of the <strong>10g basil or parsley<\/strong>, saving some to garnish.<\/li><li>Pour in the <strong>660g jar of butter beans<\/strong> with their bean stock, stir to combine and cook for 2 minutes until warmed through.<\/li><li>Tear in the <strong>75g mozzarella<\/strong> and add the <strong>75g cheddar<\/strong>, stirring until they melt into the sauce and it turns rich and creamy.<\/li><li>Serve hot, scattered with the remaining <strong>basil or parsley<\/strong>, with <strong>crusty bread<\/strong> for dunking and the dressed <strong>salad leaves<\/strong> alongside.<\/li><\/ol><\/section>\n<\/div>\n<section class=\"notes\"><h2>Notes<\/h2><p>Peeling the tomato skins is worth the effort: the juices break down into something silky rather than stringy.<\/p><\/section>\n<p class=\"source\">Source: <a href=\"https://boldbeanco.com/blogs/beanspo-recipes/bubbling-one-pan-cheesy-tomato-butter-beans\" rel=\"noreferrer\">https://boldbeanco.com/blogs/beanspo-recipes/bubbling-one-pan-cheesy-tomato-butter-beans<\/a><\/p><p class=\"source\"><a href=\"bubbling-one-pan-cheesy-tomato-butter-beans.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "butterfly-cakes", "name": "Butterfly Cakes", "title": "butterfly cakes", "tags": ["recipe", "vegetarian", "snack"], "terms": ["baking powder", "butter", "eggs", "flour", "sugar"], "image": true, "serves": "12", "time": "", "items": [{"t": "120g flour", "k": "flour"}, {"t": "85g sugar", "k": "sugar"}, {"t": "85g butter", "k": "butter"}, {"t": "1 small tsp baking powder", "k": "baking powder"}, {"t": "1 egg", "k": "eggs"}], "html": "<header><h1>Butterfly Cakes<\/h1><p class=\"meta\">Makes 12<\/p><p class=\"tags\"><span class=\"tag\">vegetarian<\/span><span class=\"tag\">snack<\/span><\/p><\/header>\n<img class=\"hero\" src=\"img/butterfly-cakes-1600.jpg\" srcset=\"img/butterfly-cakes-800.jpg 800w, img/butterfly-cakes-1600.jpg 1600w\" sizes=\"(max-width: 500px) calc(100vw - 40px), (max-width: 940px) 92vw, (max-width: 1200px) calc(940px - 8vw), 844px\" decoding=\"async\" alt=\"Butterfly Cakes\">\n<p class=\"before\"><strong>Before you start<\/strong> heat the oven to 180°C.<\/p>\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>120g flour<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>85g sugar<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>85g butter<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 small tsp baking powder<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 egg<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><ol class=\"method\" start=\"1\"><li>Cream the <strong>85g butter<\/strong> and <strong>85g sugar<\/strong> together.<\/li><li>Beat in the <strong>1 egg<\/strong>.<\/li><li>Sift the <strong>120g flour<\/strong> and the <strong>1 small tsp baking powder<\/strong> together and fold into the creamed mixture.<\/li><li>Divide the mixture evenly into small paper cases.<\/li><li>Bake at 180°C for 18-20 mins.<\/li><li>Form butterflies with the <strong>butter cream<\/strong>.<\/li><\/ol><\/section>\n<\/div>\n\n<p class=\"source\"><a href=\"butterfly-cakes.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "carlin-pea-ragu", "name": "Carlin Pea Ragu", "title": "carlin pea ragu", "tags": ["recipe", "vegetarian", "chickpeas", "pasta", "dinner"], "terms": ["bread", "carlin peas", "carrot", "celery", "garlic", "marmite", "mixed herbs", "onion", "parmesan", "parsley", "pasta", "rosemary", "stock", "thyme", "tomato", "tomato purée", "vinegar"], "image": true, "serves": "4", "time": "40m", "items": [{"t": "1 onion, finely chopped", "k": "onion"}, {"t": "1 stick of celery, finely chopped", "k": "celery"}, {"t": "1 large carrot, peeled and finely chopped", "k": "carrot"}, {"t": "1 tbsp tomato purée", "k": "tomato purée"}, {"t": "3 garlic cloves, finely chopped", "k": "garlic"}, {"t": "1 tsp mixed Italian herbs, or dried rosemary or thyme", "k": "mixed herbs"}, {"t": "1 x 570g jar of Queen Carlin Peas, with their bean stock", "k": "carlin peas"}, {"t": "1 x 400g tin of chopped tomatoes", "k": "tomato"}, {"t": "1 tsp Marmite", "k": "marmite"}, {"t": "200ml vegetable stock", "k": "stock"}, {"t": "200g orecchiette or conchiglie", "k": "pasta"}, {"t": "1 tbsp red wine vinegar", "k": "vinegar"}, {"t": "45g Parmesan, grated, plus extra to serve", "k": "parmesan"}, {"t": "A handful of fresh parsley, roughly chopped", "k": "parsley"}, {"t": "Garlic or crusty bread (optional)", "k": "bread"}], "html": "<header><h1>Carlin Pea Ragu<\/h1><p class=\"meta\">Serves 4 · 40m<\/p><p class=\"tags\"><span class=\"tag\">vegetarian<\/span><span class=\"tag\">chickpeas<\/span><span class=\"tag\">pasta<\/span><span class=\"tag\">dinner<\/span><\/p><p class=\"lede\">A vegetarian ragu of carlin peas simmered with soffritto, tomatoes and Marmite, stirred through orecchiette.<\/p><\/header>\n<img class=\"hero\" src=\"img/carlin-pea-ragu-1600.jpg\" srcset=\"img/carlin-pea-ragu-800.jpg 800w, img/carlin-pea-ragu-1600.jpg 1600w\" sizes=\"(max-width: 500px) calc(100vw - 40px), (max-width: 940px) 92vw, (max-width: 1200px) calc(940px - 8vw), 844px\" decoding=\"async\" alt=\"Carlin Pea Ragu\">\n\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>4 tbsp olive oil<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 onion, finely chopped<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 stick of celery, finely chopped<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 large carrot, peeled and finely chopped<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tbsp tomato purée<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>3 garlic cloves, finely chopped<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tsp mixed Italian herbs, or dried rosemary or thyme<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 x 570g jar of Queen Carlin Peas, with their bean stock<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 x 400g tin of chopped tomatoes<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tsp Marmite<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>200ml vegetable stock<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>200g orecchiette or conchiglie<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tbsp red wine vinegar<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>45g Parmesan, grated, plus extra to serve<\/span><\/label><\/li><\/ul><h3>To serve<\/h3><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>A handful of fresh parsley, roughly chopped<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Garlic or crusty bread (optional)<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><ol class=\"method\" start=\"1\"><li>Heat 3 tbsp of the <strong>4 tbsp olive oil<\/strong> in a large pan over a medium heat.<\/li><li>Add the <strong>1 onion<\/strong>, <strong>1 stick of celery<\/strong> and <strong>1 large carrot<\/strong> with a pinch of salt.<\/li><li>Cook for 10-12 minutes, stirring often, until softened and lightly golden.<\/li><li>Add the <strong>1 tbsp tomato purée<\/strong> with a splash of water and cook for 2 minutes, until it darkens in colour.<\/li><li>Stir in the <strong>3 garlic cloves<\/strong> and <strong>1 tsp mixed Italian herbs<\/strong> and cook for 1-2 minutes, until fragrant.<\/li><li>Add the <strong>570g jar of carlin peas<\/strong> with their bean stock, the <strong>400g tin of chopped tomatoes<\/strong> and the <strong>1 tsp Marmite<\/strong>, which gives an umami boost, and stir to combine.<\/li><li>Swill a splash of the <strong>200ml vegetable stock<\/strong> around the empty tomato tin to rinse it out, then add it to the pan along with the rest of the stock.<\/li><li>Simmer for 8-10 minutes, until slightly reduced and thickened.<\/li><li>Put the <strong>200g orecchiette<\/strong> on to boil in salted water.<\/li><li>Gently mash some of the <strong>carlin peas<\/strong> with the back of a spoon, for a thick, meaty, ragu-like texture.<\/li><li>Add the <strong>1 tbsp red wine vinegar<\/strong>, stir well and simmer for another 5-8 minutes, until thick and saucy.<\/li><li>Stir through the <strong>45g Parmesan<\/strong> and season with salt and plenty of cracked black pepper.<\/li><li>Drain the <strong>pasta<\/strong>, reserving a little of the cooking water.<\/li><li>Add the <strong>pasta<\/strong> to the ragu and stir so it is fully coated, loosening with a splash of the pasta water if necessary.<\/li><li>Spoon into bowls and top with the <strong>parsley<\/strong>, a drizzle of the remaining <strong>olive oil<\/strong> and <strong>extra Parmesan<\/strong>.<\/li><\/ol><\/section>\n<\/div>\n<section class=\"notes\"><h2>Notes<\/h2><p>Orecchiette works particularly well because its cup shape holds the peas; conchiglie is a good alternative.<\/p><p>A good one for batch cooking — the ragu keeps through the week and is also excellent over buttery polenta.<\/p><p>Grated cheddar works in place of the Parmesan to serve. Use a vegetarian alternative to the Parmesan if you need to.<\/p><\/section>\n<p class=\"source\">Source: <a href=\"https://boldbeanco.com/blogs/beanspo-recipes/carlin-pea-ragu\" rel=\"noreferrer\">https://boldbeanco.com/blogs/beanspo-recipes/carlin-pea-ragu<\/a><\/p><p class=\"source\"><a href=\"carlin-pea-ragu.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "charred-courgette-sumac-chickpea-salad-with-garlicky-lemon-yoghurt", "name": "Charred Courgette + Sumac Chickpea Salad with Garlicky Lemon Yoghurt", "title": "charred courgette + sumac chickpea salad with garlicky lemon yoghurt", "tags": ["recipe", "vegetarian", "chickpeas", "lunch", "dinner"], "terms": ["basil", "chickpeas", "chilli flakes", "courgette", "garlic", "lemon", "lettuce", "mint", "peas", "sumac", "yoghurt"], "image": true, "serves": "3-4", "time": "20m", "items": [{"t": "3 courgettes, quartered lengthways then cut into thirds", "k": "courgette"}, {"t": "1 x 660g jar of Queen Chickpeas, drained", "k": "chickpeas"}, {"t": "1 tbsp sumac", "k": "sumac"}, {"t": "70g petit pois, defrosted if frozen", "k": "peas"}, {"t": "2 baby gem lettuces, leaves separated", "k": "lettuce"}, {"t": "A large bunch (roughly 30g) of fresh mint and basil, leaves picked", "k": "basil"}, {"t": "1 tsp chilli flakes", "k": "chilli flakes"}, {"t": "3 heaped tbsp Greek yoghurt or plant-based alternative", "k": "yoghurt"}, {"t": "1 lemon, juice and half the zest", "k": "lemon"}, {"t": "1 garlic clove, finely grated", "k": "garlic"}], "html": "<header><h1>Charred Courgette + Sumac Chickpea Salad with Garlicky Lemon Yoghurt<\/h1><p class=\"meta\">Serves 3-4 · 20m<\/p><p class=\"tags\"><span class=\"tag\">vegetarian<\/span><span class=\"tag\">chickpeas<\/span><span class=\"tag\">lunch<\/span><span class=\"tag\">dinner<\/span><\/p><p class=\"lede\">Griddled courgettes and sumac-tossed chickpeas with petit pois and baby gem, dressed in a garlicky lemon yoghurt.<\/p><\/header>\n<img class=\"hero\" src=\"img/charred-courgette-sumac-chickpea-salad-with-garlicky-lemon-yoghurt-1600.jpg\" srcset=\"img/charred-courgette-sumac-chickpea-salad-with-garlicky-lemon-yoghurt-800.jpg 800w, img/charred-courgette-sumac-chickpea-salad-with-garlicky-lemon-yoghurt-1600.jpg 1600w\" sizes=\"(max-width: 500px) calc(100vw - 40px), (max-width: 940px) 92vw, (max-width: 1200px) calc(940px - 8vw), 844px\" decoding=\"async\" alt=\"Charred Courgette + Sumac Chickpea Salad with Garlicky Lemon Yoghurt\">\n\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><h3>Salad<\/h3><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>3 courgettes, quartered lengthways then cut into thirds<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 tbsp olive oil<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 x 660g jar of Queen Chickpeas, drained<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tbsp sumac<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>70g petit pois, defrosted if frozen<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 baby gem lettuces, leaves separated<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>A large bunch (roughly 30g) of fresh mint and basil, leaves picked<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tsp chilli flakes<\/span><\/label><\/li><\/ul><h3>Lemony yoghurt dressing<\/h3><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>3 heaped tbsp Greek yoghurt or plant-based alternative<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 lemon, juice and half the zest<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 garlic clove, finely grated<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tbsp olive oil<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><ol class=\"method\" start=\"1\"><li>Brush the <strong>3 courgettes<\/strong> with the <strong>2 tbsp olive oil<\/strong> and season with a good pinch of salt.<\/li><li>Heat a griddle pan over a high heat.<\/li><li>Cook the <strong>courgettes<\/strong> for 3-4 minutes on each side, until deeply charred and tender, then set aside.<\/li><li>Meanwhile, toss the drained <strong>660g jar of chickpeas<\/strong> with the <strong>1 tbsp sumac<\/strong> and a pinch of salt until evenly coated.<\/li><li>Mix the <strong>3 heaped tbsp Greek yoghurt<\/strong>, the <strong>juice of 1 lemon and half its zest<\/strong>, the <strong>1 grated garlic clove<\/strong> and the <strong>1 tbsp olive oil<\/strong> together in a small bowl.<\/li><li>Season the dressing to taste, adding more lemon if you like it sharp.<\/li><li>Tumble the <strong>courgettes<\/strong>, <strong>chickpeas<\/strong>, <strong>70g petit pois<\/strong> and the leaves of the <strong>2 baby gem lettuces<\/strong> into a large bowl or onto a serving platter.<\/li><li>Drizzle over the dressing.<\/li><li>Scatter with the <strong>30g mint and basil leaves<\/strong> and the <strong>1 tsp chilli flakes<\/strong>.<\/li><\/ol><\/section>\n<\/div>\n<section class=\"notes\"><h2>Notes<\/h2><p>The courgettes are even better charred on a barbecue.<\/p><p>Serve alongside grilled halloumi to make more of a meal of it.<\/p><\/section>\n<p class=\"source\">Source: <a href=\"https://boldbeanco.com/blogs/beanspo-recipes/charred-courgette-chickpea-salad-with-garlicky-herby-yogurt\" rel=\"noreferrer\">https://boldbeanco.com/blogs/beanspo-recipes/charred-courgette-chickpea-salad-with-garlicky-herby-yogurt<\/a><\/p><p class=\"source\"><a href=\"charred-courgette-sumac-chickpea-salad-with-garlicky-lemon-yoghurt.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "cheesy-butter-bean-tomato-garlic-pasta-bake", "name": "Cheesy Butter Bean, Tomato + Garlic Pasta Bake", "title": "cheesy butter bean, tomato + garlic pasta bake", "tags": ["recipe", "vegetarian", "beans", "pasta", "lunch", "dinner"], "terms": ["basil", "bread", "butter beans", "cheddar", "chilli flakes", "garlic", "lemon", "mozzarella", "onion", "parmesan", "passata", "pasta", "salad leaves", "spinach", "stock", "tomato purée"], "image": true, "serves": "3", "time": "40m", "items": [{"t": "1 red or brown onion, finely chopped", "k": "onion"}, {"t": "150g rigatoni, fusilli or penne", "k": "pasta"}, {"t": "2-3 fat garlic cloves, finely chopped", "k": "garlic"}, {"t": "1 tbsp tomato purée", "k": "tomato purée"}, {"t": "½ tsp chilli flakes, or to taste", "k": "chilli flakes"}, {"t": "500ml passata", "k": "passata"}, {"t": "A large handful of fresh basil leaves", "k": "basil"}, {"t": "1 x 660g jar of Queen Butter Beans, with their bean stock", "k": "butter beans"}, {"t": "120g spinach leaves (optional)", "k": "spinach"}, {"t": "50g cheddar, coarsely grated", "k": "cheddar"}, {"t": "125g ball of mozzarella", "k": "mozzarella"}, {"t": "40g Parmesan, finely grated", "k": "parmesan"}, {"t": "Mixed salad leaves, dressed in olive oil and lemon juice", "k": "salad leaves"}, {"t": "Garlic bread", "k": "bread"}], "html": "<header><h1>Cheesy Butter Bean, Tomato + Garlic Pasta Bake<\/h1><p class=\"meta\">Serves 3 · 40m<\/p><p class=\"tags\"><span class=\"tag\">vegetarian<\/span><span class=\"tag\">beans<\/span><span class=\"tag\">pasta<\/span><span class=\"tag\">lunch<\/span><span class=\"tag\">dinner<\/span><\/p><p class=\"lede\">Pasta and butter beans in a garlicky tomato sauce, baked under cheddar, mozzarella and Parmesan.<\/p><\/header>\n<img class=\"hero\" src=\"img/cheesy-butter-bean-tomato-garlic-pasta-bake-1600.jpg\" srcset=\"img/cheesy-butter-bean-tomato-garlic-pasta-bake-800.jpg 800w, img/cheesy-butter-bean-tomato-garlic-pasta-bake-1600.jpg 1600w\" sizes=\"(max-width: 500px) calc(100vw - 40px), (max-width: 940px) 92vw, (max-width: 1200px) calc(940px - 8vw), 844px\" decoding=\"async\" alt=\"Cheesy Butter Bean, Tomato + Garlic Pasta Bake\">\n<p class=\"before\"><strong>Before you start<\/strong> heat the oven to 230°C/210°C fan.<\/p>\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>2 tbsp olive oil<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 red or brown onion, finely chopped<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>150g rigatoni, fusilli or penne<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2-3 fat garlic cloves, finely chopped<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tbsp tomato purée<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>½ tsp chilli flakes, or to taste<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>500ml passata<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>A large handful of fresh basil leaves<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 x 660g jar of Queen Butter Beans, with their bean stock<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>120g spinach leaves (optional)<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>50g cheddar, coarsely grated<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>125g ball of mozzarella<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>40g Parmesan, finely grated<\/span><\/label><\/li><\/ul><h3>To serve<\/h3><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>Mixed salad leaves, dressed in olive oil and lemon juice<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Garlic bread<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><ol class=\"method\" start=\"1\"><li>Heat the oven to 230°C/210°C fan.<\/li><li>Heat the <strong>2 tbsp olive oil<\/strong> in a large ovenproof pan or shallow casserole dish over a medium heat. If you do not have an ovenproof pan, use a large frying pan and transfer everything to a baking dish later.<\/li><li>Add the <strong>1 onion<\/strong> and cook for 8-10 minutes until starting to soften, adding a splash of water to help it along if needed.<\/li><li>Meanwhile, cook the <strong>150g pasta<\/strong> in salted water until just under al dente, following the packet instructions.<\/li><li>Reserve a mug of the pasta water, then drain the <strong>pasta<\/strong>.<\/li><li>Stir the <strong>2-3 garlic cloves<\/strong>, <strong>1 tbsp tomato purée<\/strong> and <strong>½ tsp chilli flakes<\/strong> into the onion with 2 tbsp water to make a paste.<\/li><li>Cook for 1-2 minutes, until fragrant and the tomato purée has deepened in colour.<\/li><li>Pour in the <strong>500ml passata<\/strong> and most of the <strong>basil leaves<\/strong>, saving a few to garnish.<\/li><li>Season with salt and a few cracks of black pepper, then simmer for 7-8 minutes, stirring occasionally, until slightly reduced.<\/li><li>Stir in the <strong>660g jar of butter beans<\/strong> with their bean stock, the cooked <strong>pasta<\/strong> and the <strong>120g spinach<\/strong>, if using, loosening with a little of the reserved pasta water if necessary.<\/li><li>Simmer for 5-6 minutes, until the spinach wilts.<\/li><li>Mash a few of the <strong>beans<\/strong> against the side of the pan for a creamier sauce, leaving most of them whole.<\/li><li>Transfer everything to a large baking dish if you started in a frying pan.<\/li><li>Top with the <strong>50g cheddar<\/strong>, tear over the <strong>125g mozzarella<\/strong> and scatter over the <strong>40g Parmesan<\/strong>.<\/li><li>Bake at 230°C/210°C fan for 10-15 minutes, until golden, bubbling and just starting to crisp on top.<\/li><li>Rest for 5 minutes before serving with <strong>garlic bread<\/strong> and the dressed <strong>salad leaves<\/strong>.<\/li><\/ol><\/section>\n<\/div>\n<section class=\"notes\"><h2>Notes<\/h2><p>Give it a few minutes under a hot grill at the end if the top needs help crisping.<\/p><p>Gluten-free pasta works fine here.<\/p><p>Use a vegetarian alternative to the Parmesan if you need to.<\/p><p>Good for batch cooking and meal prep; a crunchy green salad cuts through the richness.<\/p><\/section>\n<p class=\"source\">Source: <a href=\"https://boldbeanco.com/blogs/beanspo-recipes/cheesy-butter-bean-tomato-garlic-pasta-bake\" rel=\"noreferrer\">https://boldbeanco.com/blogs/beanspo-recipes/cheesy-butter-bean-tomato-garlic-pasta-bake<\/a><\/p><p class=\"source\"><a href=\"cheesy-butter-bean-tomato-garlic-pasta-bake.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "chicken-and-posh-ham", "name": "Chicken and Posh Ham", "title": "chicken and posh ham", "tags": ["recipe", "chicken", "dinner"], "terms": ["chicken", "lemon", "parmesan", "prosciutto", "thyme"], "image": true, "serves": "", "time": "", "items": [{"t": "2 sprigs of fresh thyme", "k": "thyme"}, {"t": "2 skinless chicken breast fillets, preferably free-range or organic", "k": "chicken"}, {"t": "1 lemon", "k": "lemon"}, {"t": "35g grated Parmesan cheese", "k": "parmesan"}, {"t": "6 slices of prosciutto", "k": "prosciutto"}], "html": "<header><h1>Chicken and Posh Ham<\/h1><p class=\"tags\"><span class=\"tag\">chicken<\/span><span class=\"tag\">dinner<\/span><\/p><\/header>\n<img class=\"hero\" src=\"img/chicken-and-posh-ham-1600.jpg\" srcset=\"img/chicken-and-posh-ham-800.jpg 800w, img/chicken-and-posh-ham-1600.jpg 1600w\" sizes=\"(max-width: 500px) calc(100vw - 40px), (max-width: 940px) 92vw, (max-width: 1200px) calc(940px - 8vw), 844px\" decoding=\"async\" alt=\"Chicken and Posh Ham\">\n\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>2 sprigs of fresh thyme<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 skinless chicken breast fillets, preferably free-range or organic<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Freshly ground black pepper<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 lemon<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>35g grated Parmesan cheese<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>6 slices of prosciutto<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><h3>To prepare the chicken<\/h3><ol class=\"method\" start=\"1\"><li>Grate the <strong>35g Parmesan<\/strong> and pick the leaves off the stalks of the <strong>2 sprigs of fresh thyme<\/strong>.<\/li><li>Carefully score the underside of the <strong>2 chicken breasts<\/strong> in a criss-cross fashion with a small knife. Season with a little <strong>freshly ground black pepper<\/strong> (you don&#x27;t need salt as the prosciutto is quite salty).<\/li><li>Lay your breasts next to each other and sprinkle over most of the <strong>thyme<\/strong> leaves. Grate a little zest from the <strong>1 lemon<\/strong> over them and sprinkle with <strong>Parmesan<\/strong>.<\/li><li>Lay <strong>3 prosciutto slices<\/strong> on each chicken breast overlapping them slightly. Drizzle a little <strong>olive oil<\/strong> and sprinkle with the remaining <strong>thyme<\/strong> leaves.<\/li><li>Put a square of plastic wrap over each breast and give them a few really good bashes with the bottom of a saucepan until they are about 1cm thick.<\/li><\/ol><h3>To cook the chicken<\/h3><ol class=\"method\" start=\"6\"><li>Put a frying pan on a medium heat. Remove the plastic wrap and carefully transfer the chicken breasts, prosciutto side down, into the pan. Drizzle over some <strong>olive oil<\/strong>. Cook for 3 minutes on each side, turning halfway through giving the ham side an extra 30 seconds to crisp up.<\/li><\/ol><h3>To serve<\/h3><ol class=\"method\" start=\"7\"><li>Either serve the chicken breasts whole or cut them into thick slices and pile them on a plate. Serve with <strong>lemon<\/strong> wedges for squeezing over and a good drizzle of <strong>olive oil<\/strong>.<\/li><\/ol><\/section>\n<\/div>\n<section class=\"notes\"><h2>Notes<\/h2><p>Lovely with mashed potatoes and green veggies or a crunchy salad.<\/p><\/section>\n<p class=\"source\"><a href=\"chicken-and-posh-ham.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "chickpea-caesar-salad", "name": "Chickpea Caesar Salad", "title": "chickpea caesar salad", "tags": ["recipe", "pescatarian", "fish", "chickpeas", "lunch", "dinner"], "terms": ["anchovies", "bread", "chickpeas", "garlic", "lemon", "lettuce", "mayonnaise", "mustard", "parmesan"], "image": true, "serves": "4", "time": "30m", "items": [{"t": "150g ciabatta (or thick slices of another bread)", "k": "bread"}, {"t": "1 large cos or romaine lettuce, leaves separated", "k": "lettuce"}, {"t": "1 x 660g jar of Queen Chickpeas, drained", "k": "chickpeas"}, {"t": "2 anchovies in oil, roughly chopped", "k": "anchovies"}, {"t": "1 garlic clove, grated", "k": "garlic"}, {"t": "4 tbsp mayonnaise", "k": "mayonnaise"}, {"t": "1 tsp Dijon mustard", "k": "mustard"}, {"t": "20g Parmesan, plus extra to serve", "k": "parmesan"}, {"t": "1 lemon, juice only", "k": "lemon"}], "html": "<header><h1>Chickpea Caesar Salad<\/h1><p class=\"meta\">Serves 4 · 30m<\/p><p class=\"tags\"><span class=\"tag\">pescatarian<\/span><span class=\"tag\">fish<\/span><span class=\"tag\">chickpeas<\/span><span class=\"tag\">lunch<\/span><span class=\"tag\">dinner<\/span><\/p><p class=\"lede\">A Caesar salad with chickpeas in place of the chicken, with baked ciabatta croutons and a creamy anchovy dressing.<\/p><\/header>\n<img class=\"hero\" src=\"img/chickpea-caesar-salad-1600.jpg\" srcset=\"img/chickpea-caesar-salad-800.jpg 800w, img/chickpea-caesar-salad-1600.jpg 1600w\" sizes=\"(max-width: 500px) calc(100vw - 40px), (max-width: 940px) 92vw, (max-width: 1200px) calc(940px - 8vw), 844px\" decoding=\"async\" alt=\"Chickpea Caesar Salad\">\n<p class=\"before\"><strong>Before you start<\/strong> heat the oven to 180°C.<\/p>\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>150g ciabatta (or thick slices of another bread)<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 tbsp olive oil<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 large cos or romaine lettuce, leaves separated<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 x 660g jar of Queen Chickpeas, drained<\/span><\/label><\/li><\/ul><h3>Dressing<\/h3><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>2 anchovies in oil, roughly chopped<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 garlic clove, grated<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>4 tbsp mayonnaise<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tsp Dijon mustard<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>20g Parmesan, plus extra to serve<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 lemon, juice only<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><ol class=\"method\" start=\"1\"><li>Heat the oven to 180°C.<\/li><li>Tear the <strong>150g ciabatta<\/strong> into chunky croutons.<\/li><li>Tumble the croutons onto a baking tray with the <strong>2 tbsp olive oil<\/strong> and a pinch of salt and pepper.<\/li><li>Bake for 8-10 minutes, turning often so they crisp evenly, until golden.<\/li><li>Meanwhile, add the <strong>2 anchovies<\/strong>, <strong>1 grated garlic clove<\/strong>, <strong>4 tbsp mayonnaise<\/strong>, <strong>1 tsp Dijon mustard<\/strong>, <strong>20g Parmesan<\/strong> and the <strong>juice of 1 lemon<\/strong> to an empty jar or mixing bowl.<\/li><li>Shake or mix well to combine, then check the seasoning. It should be the consistency of yoghurt — add a splash of water to loosen it if needed.<\/li><li>Tip the dressing into a large mixing bowl and add the <strong>1 cos lettuce<\/strong>, the drained <strong>660g jar of chickpeas<\/strong> and half the croutons.<\/li><li>Toss well to coat.<\/li><li>Tip onto a serving platter, top with the remaining croutons and shave over <strong>extra Parmesan<\/strong>.<\/li><\/ol><\/section>\n<\/div>\n<section class=\"notes\"><h2>Notes<\/h2><p>This dressing is the shortcut version, built on mayonnaise; a from-scratch Caesar dressing works just as well.<\/p><\/section>\n<p class=\"source\">Source: <a href=\"https://boldbeanco.com/blogs/beanspo-recipes/chickpea-caesar-salad\" rel=\"noreferrer\">https://boldbeanco.com/blogs/beanspo-recipes/chickpea-caesar-salad<\/a><\/p><p class=\"source\"><a href=\"chickpea-caesar-salad.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "chickpeas-alla-vodka-with-charred-tenderstem-broccoli", "name": "Chickpeas alla Vodka with Charred Tenderstem Broccoli", "title": "chickpeas alla vodka with charred tenderstem broccoli", "tags": ["recipe", "vegetarian", "chickpeas", "dinner"], "terms": ["basil", "bread", "broccoli", "chickpeas", "chilli flakes", "crème fraîche", "double cream", "garlic", "lemon", "onion", "paprika", "parmesan", "salad leaves", "shallot", "stock", "tomato purée", "vodka"], "image": true, "serves": "2", "time": "30m", "items": [{"t": "1 banana shallot, or ½ onion, finely chopped", "k": "shallot"}, {"t": "3 garlic cloves, crushed", "k": "garlic"}, {"t": "A pinch of chilli flakes", "k": "chilli flakes"}, {"t": "100g tomato purée", "k": "tomato purée"}, {"t": "1 tsp smoked paprika", "k": "paprika"}, {"t": "60ml vodka", "k": "vodka"}, {"t": "100ml double cream, mascarpone or crème fraîche", "k": "crème fraîche"}, {"t": "1 x 660g jar of Queen Chickpeas, with their bean stock", "k": "chickpeas"}, {"t": "200g tenderstem broccoli", "k": "broccoli"}, {"t": "1 lemon, juice only", "k": "lemon"}, {"t": "40g Parmesan, grated, or a plant-based alternative", "k": "parmesan"}, {"t": "A small handful of fresh basil", "k": "basil"}, {"t": "Ciabatta bread", "k": "bread"}, {"t": "A green salad", "k": "salad leaves"}], "html": "<header><h1>Chickpeas alla Vodka with Charred Tenderstem Broccoli<\/h1><p class=\"meta\">Serves 2 · 30m<\/p><p class=\"tags\"><span class=\"tag\">vegetarian<\/span><span class=\"tag\">chickpeas<\/span><span class=\"tag\">dinner<\/span><\/p><p class=\"lede\">A vodka and tomato cream sauce built around chickpeas instead of pasta, served with grilled tenderstem broccoli.<\/p><\/header>\n<img class=\"hero\" src=\"img/chickpeas-alla-vodka-with-charred-tenderstem-broccoli-1600.jpg\" srcset=\"img/chickpeas-alla-vodka-with-charred-tenderstem-broccoli-800.jpg 800w, img/chickpeas-alla-vodka-with-charred-tenderstem-broccoli-1600.jpg 1600w\" sizes=\"(max-width: 500px) calc(100vw - 40px), (max-width: 940px) 92vw, (max-width: 1200px) calc(940px - 8vw), 844px\" decoding=\"async\" alt=\"Chickpeas alla Vodka with Charred Tenderstem Broccoli\">\n\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>2 tbsp olive oil, plus 1 tbsp for the broccoli<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 banana shallot, or ½ onion, finely chopped<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>3 garlic cloves, crushed<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>A pinch of chilli flakes<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>100g tomato purée<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tsp smoked paprika<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>60ml vodka<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>100ml double cream, mascarpone or crème fraîche<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 x 660g jar of Queen Chickpeas, with their bean stock<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>200g tenderstem broccoli<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 lemon, juice only<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>40g Parmesan, grated, or a plant-based alternative<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>A small handful of fresh basil<\/span><\/label><\/li><\/ul><h3>To serve<\/h3><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>Ciabatta bread<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>A green salad<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><ol class=\"method\" start=\"1\"><li>Heat the <strong>2 tbsp olive oil<\/strong> in a frying pan over a medium-low heat.<\/li><li>Add the <strong>1 banana shallot<\/strong> with a pinch of salt and cook for 7-8 minutes, until soft and translucent.<\/li><li>Stir in the <strong>3 garlic cloves<\/strong> and <strong>pinch of chilli flakes<\/strong> and cook for 30 seconds to 1 minute, until fragrant.<\/li><li>Increase the heat to medium, stir through the <strong>100g tomato purée<\/strong> and <strong>1 tsp smoked paprika<\/strong> and cook for 2 minutes, until the paste starts to darken and caramelise.<\/li><li>Pour in the <strong>60ml vodka<\/strong> and stir well, scraping any browned bits from the bottom of the pan.<\/li><li>Cook for 3 minutes, stirring occasionally, until the alcohol has reduced by about half.<\/li><li>Stir through the <strong>100ml double cream, mascarpone or crème fraîche<\/strong> to combine.<\/li><li>Add the <strong>660g jar of chickpeas and their bean stock<\/strong> and cook gently for 3-4 minutes, until the chickpeas are warmed through and glossy.<\/li><li>Meanwhile, heat the grill to medium.<\/li><li>Toss the <strong>200g tenderstem broccoli<\/strong> with the <strong>1 tbsp olive oil<\/strong>, salt and pepper, then spread it out on a tray in a single layer.<\/li><li>Grill for 6-8 minutes, turning halfway, until slightly charred, then finish with a small squeeze of <strong>lemon juice<\/strong>.<\/li><li>Squeeze the juice of half the <strong>lemon<\/strong> into the chickpeas and add the <strong>40g Parmesan<\/strong>.<\/li><li>Let everything melt together until silky, then season with salt and a few cracks of black pepper.<\/li><li>Spoon the chickpeas into bowls and serve with the grilled <strong>broccoli<\/strong>, the <strong>fresh basil<\/strong> and an extra squeeze of <strong>lemon<\/strong>.<\/li><\/ol><\/section>\n<\/div>\n<section class=\"notes\"><h2>Notes<\/h2><p>Crème fraîche gives a tangier, slightly thicker sauce; double cream is silkier.<\/p><p>The broccoli also works in an air fryer, about 5-6 minutes.<\/p><p>Good with warm ciabatta or a green salad alongside.<\/p><p>For the pasta version of the same sauce, see <a href=\"fusilli-a-la-vodka-with-basil-and-parmesan.html\">Fusilli a la Vodka with Basil and Parmesan<\/a>.<\/p><\/section>\n<p class=\"source\">Source: <a href=\"https://boldbeanco.com/blogs/beanspo-recipes/chickpeas-alla-vodka-with-charred-tenderstem-broccoli\" rel=\"noreferrer\">https://boldbeanco.com/blogs/beanspo-recipes/chickpeas-alla-vodka-with-charred-tenderstem-broccoli<\/a><\/p><p class=\"source\"><a href=\"chickpeas-alla-vodka-with-charred-tenderstem-broccoli.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "chickpeas-and-macaroni", "name": "Chickpeas and Macaroni", "title": "chickpeas and macaroni", "tags": ["recipe", "vegetarian", "pasta", "dinner"], "terms": ["basil", "bay leaves", "chickpeas", "chilli flakes", "cinnamon", "double cream", "garlic", "onion", "parsley", "pasta", "tomato", "tomato purée"], "image": true, "serves": "2", "time": "", "items": [{"t": "100g macaroni", "k": "pasta"}, {"t": "1 medium onion", "k": "onion"}, {"t": "1 x 400g tin chopped tomatoes", "k": "tomato"}, {"t": "1 x 400g tin chickpeas", "k": "chickpeas"}, {"t": "3 garlic cloves, crushed", "k": "garlic"}, {"t": "1 tbsp tomato purée", "k": "tomato purée"}, {"t": "100ml double cream", "k": "double cream"}, {"t": "3 bay leaves", "k": "bay leaves"}, {"t": "½ cinnamon stick", "k": "cinnamon"}, {"t": "½ tsp dried chilli flakes", "k": "chilli flakes"}, {"t": "2 tbsp parsley, chopped", "k": "parsley"}, {"t": "12 basil leaves", "k": "basil"}], "html": "<header><h1>Chickpeas and Macaroni<\/h1><p class=\"meta\">Serves 2<\/p><p class=\"tags\"><span class=\"tag\">vegetarian<\/span><span class=\"tag\">pasta<\/span><span class=\"tag\">dinner<\/span><\/p><\/header>\n<img class=\"hero\" src=\"img/chickpeas-and-macaroni-1600.jpg\" srcset=\"img/chickpeas-and-macaroni-800.jpg 800w, img/chickpeas-and-macaroni-1600.jpg 1600w\" sizes=\"(max-width: 500px) calc(100vw - 40px), (max-width: 940px) 92vw, (max-width: 1200px) calc(940px - 8vw), 844px\" decoding=\"async\" alt=\"Chickpeas and Macaroni\">\n\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>100g macaroni<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 medium onion<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 x 400g tin chopped tomatoes<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 x 400g tin chickpeas<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>3 garlic cloves, crushed<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 tbsp olive oil<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tbsp tomato purée<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>100ml double cream<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>3 bay leaves<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>½ cinnamon stick<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>½ tsp dried chilli flakes<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 tbsp parsley, chopped<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>12 basil leaves<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><ol class=\"method\" start=\"1\"><li>Peel and roughly chop the <strong>1 medium onion<\/strong>, then soften it in a pan with the <strong>3 garlic cloves<\/strong> and <strong>2 tbsp olive oil<\/strong>. When the onions start to brown, add the <strong>1 tbsp tomato purée<\/strong>, <strong>400g tinned tomatoes<\/strong>, <strong>½ cinnamon stick<\/strong>, <strong>3 bay leaves<\/strong>, <strong>½ tsp chilli flakes<\/strong> and <strong>pepper<\/strong> and <strong>salt<\/strong>. Simmer for 15 minutes.<\/li><li>Bring a deep pan of water to the boil, salt it, then cook the <strong>100g macaroni<\/strong> for 9 minutes, until tender. Drain the macaroni. Drain the <strong>400g chickpeas<\/strong> and stir both into the tomato sauce. Simmer for 5 minutes, then stir in the <strong>100ml double cream<\/strong>.<\/li><li>Add the <strong>2 tbsp chopped parsley<\/strong> and the <strong>12 basil leaves<\/strong>. Divide the pasta and chickpeas between two deep bowls and serve.<\/li><\/ol><\/section>\n<\/div>\n\n<p class=\"source\"><a href=\"chickpeas-and-macaroni.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "chilli-prawn-pasta", "name": "Chilli Prawn Pasta", "title": "chilli prawn pasta", "tags": ["recipe", "pescatarian", "seafood", "pasta", "dinner"], "terms": ["basil", "chilli flakes", "coriander", "garlic", "lime", "onion", "passata", "pasta", "prawns", "red pepper", "stock", "vodka"], "image": true, "serves": "4", "time": "", "items": [{"t": "200g spaghetti", "k": "pasta"}, {"t": "1 onion, finely chopped", "k": "onion"}, {"t": "1 red pepper, finely chopped", "k": "red pepper"}, {"t": "2 garlic cloves", "k": "garlic"}, {"t": "1 tsp chilli flakes", "k": "chilli flakes"}, {"t": "Zest of 1 lime", "k": "lime"}, {"t": "100ml stock (fish or vegetable)", "k": "stock"}, {"t": "250ml tomato passata", "k": "passata"}, {"t": "50ml vodka (optional)", "k": "vodka"}, {"t": "400g raw prawns", "k": "prawns"}, {"t": "Coriander or basil", "k": "coriander"}, {"t": "Lime wedges (for serving)", "k": "lime"}], "html": "<header><h1>Chilli Prawn Pasta<\/h1><p class=\"meta\">Serves 4<\/p><p class=\"tags\"><span class=\"tag\">pescatarian<\/span><span class=\"tag\">seafood<\/span><span class=\"tag\">pasta<\/span><span class=\"tag\">dinner<\/span><\/p><\/header>\n<img class=\"hero\" src=\"img/chilli-prawn-pasta-1600.jpg\" srcset=\"img/chilli-prawn-pasta-800.jpg 800w, img/chilli-prawn-pasta-1600.jpg 1600w\" sizes=\"(max-width: 500px) calc(100vw - 40px), (max-width: 940px) 92vw, (max-width: 1200px) calc(940px - 8vw), 844px\" decoding=\"async\" alt=\"Chilli Prawn Pasta\">\n\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>200g spaghetti<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 onion, finely chopped<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 red pepper, finely chopped<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 garlic cloves<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tsp chilli flakes<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Zest of 1 lime<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>100ml stock (fish or vegetable)<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>250ml tomato passata<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>50ml vodka (optional)<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>400g raw prawns<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Coriander or basil<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Lime wedges (for serving)<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><ol class=\"method\" start=\"1\"><li>Get a rolling boil, salt the water and add the <strong>200g spaghetti<\/strong> for 10-12 mins, then drain.<\/li><li>Fry the <strong>1 onion<\/strong> and <strong>1 red pepper<\/strong> (with a dash of water).<\/li><li>Add the <strong>2 garlic cloves<\/strong>, <strong>1 tsp chilli flakes<\/strong>, and the <strong>zest of 1 lime<\/strong> and season.<\/li><li>Pour the <strong>100ml stock<\/strong> into the pan, put the lid on the pan and cook for 5 mins.<\/li><li>Pour in the <strong>250ml passata<\/strong> and simmer for 5 mins.<\/li><li>(Optional) add the <strong>50ml vodka<\/strong> and cook for 1 min<\/li><li>Throw in the <strong>400g raw prawns<\/strong> and cook until they turn pink and feel bouncy.<\/li><li>Serve <strong>pasta<\/strong> with sauce and add <strong>coriander/basil<\/strong> leaves to garnish with <strong>lime wedges<\/strong>.<\/li><\/ol><\/section>\n<\/div>\n\n<p class=\"source\"><a href=\"chilli-prawn-pasta.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "chipotle-roasted-squash-black-bean-traybake", "name": "Chipotle Roasted Squash + Black Bean Traybake", "title": "chipotle roasted squash + black bean traybake", "tags": ["recipe", "vegetarian", "beans", "one-pot", "dinner"], "terms": ["avocado", "black beans", "butternut squash", "chilli powder", "chipotle", "cinnamon", "coriander", "garlic", "honey", "lime", "maple syrup", "onion", "oregano", "paprika", "red pepper", "rice", "soured cream", "stock", "tomato purée", "yoghurt"], "image": true, "serves": "4", "time": "50m", "items": [{"t": "1 onion, finely chopped", "k": "onion"}, {"t": "1 large red pepper, roughly chopped", "k": "red pepper"}, {"t": "1 medium butternut squash, peeled and diced into 2cm cubes", "k": "butternut squash"}, {"t": "2 tbsp tomato purée", "k": "tomato purée"}, {"t": "1 tbsp honey or maple syrup", "k": "maple syrup"}, {"t": "2 tbsp chipotle chilli paste", "k": "chipotle"}, {"t": "1 tsp chilli powder", "k": "chilli powder"}, {"t": "1 tsp smoked paprika", "k": "paprika"}, {"t": "1 tsp dried oregano", "k": "oregano"}, {"t": "½ tsp ground cinnamon", "k": "cinnamon"}, {"t": "2 garlic cloves, roughly chopped", "k": "garlic"}, {"t": "1 x 700g jar of Queen Black Beans, with their bean stock", "k": "black beans"}, {"t": "Cooked rice", "k": "rice"}, {"t": "Yoghurt or sour cream", "k": "soured cream"}, {"t": "Sliced avocado", "k": "avocado"}, {"t": "A bunch of fresh coriander, roughly chopped", "k": "coriander"}, {"t": "Lime wedges", "k": "lime"}], "html": "<header><h1>Chipotle Roasted Squash + Black Bean Traybake<\/h1><p class=\"meta\">Serves 4 · 50m<\/p><p class=\"tags\"><span class=\"tag\">vegetarian<\/span><span class=\"tag\">beans<\/span><span class=\"tag\">one-pot<\/span><span class=\"tag\">dinner<\/span><\/p><p class=\"lede\">Butternut squash, onion and red pepper roasted in one tray with chipotle and smoked paprika, then stirred through with black beans and spooned over rice.<\/p><\/header>\n<img class=\"hero\" src=\"img/chipotle-roasted-squash-black-bean-traybake-1600.jpg\" srcset=\"img/chipotle-roasted-squash-black-bean-traybake-800.jpg 800w, img/chipotle-roasted-squash-black-bean-traybake-1600.jpg 1600w\" sizes=\"(max-width: 500px) calc(100vw - 40px), (max-width: 940px) 92vw, (max-width: 1200px) calc(940px - 8vw), 844px\" decoding=\"async\" alt=\"Chipotle Roasted Squash + Black Bean Traybake\">\n<p class=\"before\"><strong>Before you start<\/strong> heat the oven to 200°C.<\/p>\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>2 tbsp olive oil<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 onion, finely chopped<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 large red pepper, roughly chopped<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 medium butternut squash, peeled and diced into 2cm cubes<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 tbsp tomato purée<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tbsp honey or maple syrup<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 tbsp chipotle chilli paste<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tsp chilli powder<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tsp smoked paprika<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tsp dried oregano<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>½ tsp ground cinnamon<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 garlic cloves, roughly chopped<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 x 700g jar of Queen Black Beans, with their bean stock<\/span><\/label><\/li><\/ul><h3>To serve<\/h3><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>Cooked rice<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Yoghurt or sour cream<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Sliced avocado<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>A bunch of fresh coriander, roughly chopped<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Lime wedges<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><ol class=\"method\" start=\"1\"><li>Heat the oven to 200°C.<\/li><li>Tip the <strong>2 tbsp olive oil<\/strong>, <strong>1 onion<\/strong>, <strong>1 large red pepper<\/strong>, <strong>1 medium butternut squash<\/strong>, <strong>2 tbsp tomato purée<\/strong>, <strong>1 tbsp honey or maple syrup<\/strong>, <strong>2 tbsp chipotle chilli paste<\/strong>, <strong>1 tsp chilli powder<\/strong>, <strong>1 tsp smoked paprika<\/strong>, <strong>1 tsp dried oregano<\/strong> and <strong>½ tsp ground cinnamon<\/strong> into a large baking dish.<\/li><li>Add a splash of water, which will help steam the veg as it cooks, and mix everything well to coat.<\/li><li>Roast for 35-40 minutes, stirring halfway through, until the squash is just tender and the sauce has thickened.<\/li><li>Take the dish out of the oven and stir through the <strong>2 garlic cloves<\/strong>.<\/li><li>Tip in the <strong>700g jar of black beans<\/strong> with their bean stock and mix well to coat in the spices.<\/li><li>Roast for a further 5-6 minutes, just to warm the beans through and let them soak up the sauce — you are after a jammy, saucy texture rather than a crisp one.<\/li><li>Spoon the mixture over the <strong>cooked rice<\/strong>.<\/li><li>Serve with <strong>sliced avocado<\/strong>, a dollop of <strong>yoghurt or sour cream<\/strong>, the <strong>fresh coriander<\/strong> and a squeeze of <strong>lime<\/strong>.<\/li><\/ol><\/section>\n<\/div>\n<section class=\"notes\"><h2>Notes<\/h2><p>Sweet potato works just as well as the butternut squash.<\/p><p>Also good loaded onto soft tacos, or stuffed into a burrito.<\/p><p>Use maple syrup rather than honey, and a plant-based yoghurt or sour cream, to make it vegan.<\/p><\/section>\n<p class=\"source\">Source: <a href=\"https://boldbeanco.com/blogs/beanspo-recipes/chipotle-roasted-squash-black-bean-bean-bowls\" rel=\"noreferrer\">https://boldbeanco.com/blogs/beanspo-recipes/chipotle-roasted-squash-black-bean-bean-bowls<\/a><\/p><p class=\"source\"><a href=\"chipotle-roasted-squash-black-bean-traybake.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "chocolate-bread-and-butter-pudding", "name": "Chocolate Bread and Butter Pudding", "title": "chocolate bread and butter pudding", "tags": ["recipe", "vegetarian", "bread", "dessert"], "terms": ["bread", "butter", "cinnamon", "dark chocolate", "dark rum", "double cream", "eggs", "sugar"], "image": true, "serves": "", "time": "", "items": [{"t": "9 slices of white bread (1 day old)", "k": "bread"}, {"t": "150g dark chocolate", "k": "dark chocolate"}, {"t": "450ml whipping cream", "k": "double cream"}, {"t": "5 tbsp dark rum", "k": "dark rum"}, {"t": "120g caster sugar", "k": "sugar"}, {"t": "85g butter", "k": "butter"}, {"t": "Pinch of cinnamon", "k": "cinnamon"}, {"t": "3 large eggs", "k": "eggs"}], "html": "<header><h1>Chocolate Bread and Butter Pudding<\/h1><p class=\"tags\"><span class=\"tag\">vegetarian<\/span><span class=\"tag\">bread<\/span><span class=\"tag\">dessert<\/span><\/p><\/header>\n<img class=\"hero\" src=\"img/chocolate-bread-and-butter-pudding-1600.jpg\" srcset=\"img/chocolate-bread-and-butter-pudding-800.jpg 800w, img/chocolate-bread-and-butter-pudding-1600.jpg 1600w\" sizes=\"(max-width: 500px) calc(100vw - 40px), (max-width: 940px) 92vw, (max-width: 1200px) calc(940px - 8vw), 844px\" decoding=\"async\" alt=\"Chocolate Bread and Butter Pudding\">\n<p class=\"before\"><strong>Before you start<\/strong> heat the oven to 180°C. Needs 2 hours standing at room temperature, then 48 hours in the fridge before cooking.<\/p>\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>9 slices of white bread (1 day old)<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>150g dark chocolate<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>450ml whipping cream<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>5 tbsp dark rum<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>120g caster sugar<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>85g butter<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Pinch of cinnamon<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>3 large eggs<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><ol class=\"method\" start=\"1\"><li>Remove the crusts from the <strong>9 slices of white bread<\/strong> and cut each slice into 4 triangles.<\/li><li>Place the <strong>150g dark chocolate<\/strong>, <strong>450ml whipping cream<\/strong>, <strong>5 tbsp dark rum<\/strong>, <strong>120g caster sugar<\/strong>, <strong>85g butter<\/strong>, and <strong>pinch of cinnamon<\/strong> into a bain-marie. Wait until everything has melted and give it a good stir.<\/li><li>In a separate bowl, whisk the <strong>3 large eggs<\/strong> and then pour over the chocolate mixture, thoroughly blending them together with a whisk.<\/li><li>Spoon a 1cm layer of the chocolate mixture into the base of the dish.<\/li><li>Arrange half the triangles over the chocolate layer in overlapping rows.<\/li><li>Pour half the remaining chocolate mixture over the bread as evenly as possible.<\/li><li>Repeat the last two steps and press the bread down gently so that it gets covered evenly with the liquid as it cools.<\/li><li>Cover the dish with clingfilm and allow to stand at room temperature for 2 hours before putting in fridge for 48 hours before cooking.<\/li><li>Preheat oven to 180°C, remove clingfilm, and bake for 30-35 mins.<\/li><li>Let it stand for 10 mins and serve with double cream or ice cream.<\/li><\/ol><\/section>\n<\/div>\n\n<p class=\"source\"><a href=\"chocolate-bread-and-butter-pudding.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "chocolate-snowballs", "name": "Chocolate Snowballs", "title": "chocolate snowballs", "tags": ["recipe", "vegetarian", "snack"], "terms": ["butter", "cocoa powder", "digestive biscuits", "milk", "sugar"], "image": true, "serves": "", "time": "", "items": [{"t": "500g digestive biscuits, finely crushed", "k": "digestive biscuits"}, {"t": "100g butter", "k": "butter"}, {"t": "6 tbsp cocoa powder", "k": "cocoa powder"}, {"t": "1 x 400g tin condensed milk", "k": "milk"}, {"t": "6 tbsp icing sugar", "k": "sugar"}], "html": "<header><h1>Chocolate Snowballs<\/h1><p class=\"tags\"><span class=\"tag\">vegetarian<\/span><span class=\"tag\">snack<\/span><\/p><\/header>\n<img class=\"hero\" src=\"img/chocolate-snowballs-1600.jpg\" srcset=\"img/chocolate-snowballs-800.jpg 800w, img/chocolate-snowballs-1600.jpg 1600w\" sizes=\"(max-width: 500px) calc(100vw - 40px), (max-width: 940px) 92vw, (max-width: 1200px) calc(940px - 8vw), 844px\" decoding=\"async\" alt=\"Chocolate Snowballs\">\n<p class=\"before\"><strong>Before you start<\/strong> needs 1 hour setting in the fridge.<\/p>\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>500g digestive biscuits, finely crushed<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>100g butter<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>6 tbsp cocoa powder<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 x 400g tin condensed milk<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>6 tbsp icing sugar<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Petit four paper cases<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><ol class=\"method\" start=\"1\"><li>In a large bowl, mix together the <strong>500g crushed digestive biscuits<\/strong> and <strong>6 tbsp cocoa powder<\/strong>.<\/li><li>Melt the <strong>100g butter<\/strong> in a pan, then pour into the cocoa mixture.<\/li><li>Gradually add the <strong>400g condensed milk<\/strong>, whilst stirring, to get a sticky but not sloppy consistency.<\/li><li>Roll the mixture into small balls, dip them in the <strong>6 tbsp icing sugar<\/strong> and place each into a petit four case.<\/li><li>Leave to set in the fridge for 1 hour.<\/li><\/ol><\/section>\n<\/div>\n\n<p class=\"source\"><a href=\"chocolate-snowballs.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "citrus-and-cashew-nut-salad", "name": "Citrus and Cashew Nut Salad", "title": "citrus and cashew nut salad", "tags": ["recipe", "vegan", "lunch"], "terms": ["beetroot", "cabbage", "cashews", "celeriac", "chilli", "coriander", "fennel", "ginger", "grapefruit", "lime", "mint", "orange", "soy sauce", "sugar", "vinegar"], "image": true, "serves": "4", "time": "", "items": [{"t": "1 grapefruit", "k": "grapefruit"}, {"t": "1 large orange", "k": "orange"}, {"t": "250g red cabbage", "k": "cabbage"}, {"t": "150g fennel", "k": "fennel"}, {"t": "150g celeriac", "k": "celeriac"}, {"t": "250g beetroot", "k": "beetroot"}, {"t": "2 tbsp red wine vinegar", "k": "vinegar"}, {"t": "3 tbsp lime juice", "k": "lime"}, {"t": "1 tbsp light soy sauce", "k": "soy sauce"}, {"t": "35g ginger, peeled and grated", "k": "ginger"}, {"t": "3 tbsp light muscovado sugar", "k": "sugar"}, {"t": "2 small hot chillies, deseeded, finely chopped", "k": "chilli"}, {"t": "75g cashews, roasted and salted, plus a few to finish", "k": "cashews"}, {"t": "20 mint leaves, finely shredded", "k": "mint"}, {"t": "20 coriander leaves", "k": "coriander"}], "html": "<header><h1>Citrus and Cashew Nut Salad<\/h1><p class=\"meta\">Serves 4<\/p><p class=\"tags\"><span class=\"tag\">vegan<\/span><span class=\"tag\">lunch<\/span><\/p><\/header>\n<img class=\"hero\" src=\"img/citrus-and-cashew-nut-salad-1600.jpg\" srcset=\"img/citrus-and-cashew-nut-salad-800.jpg 800w, img/citrus-and-cashew-nut-salad-1600.jpg 1600w\" sizes=\"(max-width: 500px) calc(100vw - 40px), (max-width: 940px) 92vw, (max-width: 1200px) calc(940px - 8vw), 844px\" decoding=\"async\" alt=\"Citrus and Cashew Nut Salad\">\n\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>1 grapefruit<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 large orange<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>250g red cabbage<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>150g fennel<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>150g celeriac<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>250g beetroot<\/span><\/label><\/li><\/ul><h3>For the dressing<\/h3><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>2 tbsp red wine vinegar<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>3 tbsp lime juice<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>75ml olive oil<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tbsp light soy sauce<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>35g ginger, peeled and grated<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>3 tbsp light muscovado sugar<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 small hot chillies, deseeded, finely chopped<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>75g cashews, roasted and salted, plus a few to finish<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>20 mint leaves, finely shredded<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>20 coriander leaves<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><ol class=\"method\" start=\"1\"><li>Make the dressing: put the <strong>2 tbsp red wine vinegar<\/strong>, <strong>3 tbsp lime juice<\/strong>, <strong>75ml olive oil<\/strong> and <strong>1 tbsp light soy sauce<\/strong> in a mixing bowl. Add the <strong>35g peeled ginger<\/strong> to the liquids with the <strong>3 tbsp light muscovado sugar<\/strong>. Stir in the <strong>2 small hot chillies<\/strong> and stir in.<\/li><li>Crush the <strong>75g cashews<\/strong> to a coarse, nubbly powder with a pestle and mortar (or the end of a rolling pin), then add to the dressing with the <strong>20 mint leaves<\/strong> and the <strong>20 coriander leaves<\/strong>, torn up a little if they are particularly large. Stir the dressing and set aside.<\/li><li>Remove the peel and white pith from the <strong>1 grapefruit<\/strong> and <strong>1 large orange<\/strong>, saving as much juice as you can. Separate the segments with a sharp knife and add them to the dressing with any juice.<\/li><li>Finely shred the <strong>250g red cabbage<\/strong> and <strong>150g fennel<\/strong> and add to the dressing. Peel the <strong>150g celeriac<\/strong> and <strong>250g beetroot<\/strong>, slice thinly, then cut into long, thin matchsticks. Toss with the dressing, check the seasoning and set aside for 30 minutes or more before serving. Add the reserved whole <strong>cashews<\/strong> just before bringing the salad to the table.<\/li><\/ol><\/section>\n<\/div>\n<section class=\"notes\"><h2>Notes<\/h2><p>The dressing sounds like a lot of trouble. It isn&#x27;t. Everything just needs a quick blast in the blender or food processor – although I find the texture of the cashew nuts most pleasing when I grind them using a pestle and mortar, leaving them as a rough, gravelly powder. Once made, it is probably best to eat it the same day.<\/p><\/section>\n<p class=\"source\"><a href=\"citrus-and-cashew-nut-salad.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "clares-avocado-and-goats-cheese-salad", "name": "Clare's Avocado and Goat's Cheese Salad", "title": "clare's avocado and goat's cheese salad", "tags": ["recipe", "vegetarian", "lunch"], "terms": ["avocado", "beetroot", "goat's cheese", "salad leaves", "vinegar"], "image": false, "serves": "", "time": "", "items": [{"t": "Mixed leaves", "k": "salad leaves"}, {"t": "Citrusy soft goat's cheese (rindless)", "k": "goat's cheese"}, {"t": "Avocado", "k": "avocado"}, {"t": "Beetroot", "k": "beetroot"}, {"t": "Balsamic vinegar (aged)", "k": "vinegar"}], "html": "<header><h1>Clare&#x27;s Avocado and Goat&#x27;s Cheese Salad<\/h1><p class=\"tags\"><span class=\"tag\">vegetarian<\/span><span class=\"tag\">lunch<\/span><\/p><\/header>\n\n\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>Mixed leaves<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Citrusy soft goat&#x27;s cheese (rindless)<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Avocado<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Beetroot<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Balsamic vinegar (aged)<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Extra virgin olive oil<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Black pepper<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><ol class=\"method\" start=\"1\"><li>Combine the <strong>mixed leaves<\/strong>, sliced <strong>avocado<\/strong> and <strong>beetroot<\/strong>, then crumble over the <strong>goat&#x27;s cheese<\/strong>.<\/li><li>Dress with the <strong>aged balsamic vinegar<\/strong> and <strong>extra virgin olive oil<\/strong>, and season with <strong>black pepper<\/strong>.<\/li><\/ol><\/section>\n<\/div>\n<section class=\"notes\"><h2>Notes<\/h2><p>You could add: peppers, walnuts, pears, and use other cheeses such as gorgonzola or feta.<\/p><p>The original document gave no quantities and no method — the steps above are the plain assembly, so adjust freely. It also contained <a href=\"harissa-chickpeas.html\">Harissa Chickpeas<\/a>, now a separate note.<\/p><\/section>\n<p class=\"source\"><a href=\"clares-avocado-and-goats-cheese-salad.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "clares-chicken-and-ham-pie", "name": "Clare's Chicken and Ham Pie", "title": "clare's chicken and ham pie", "tags": ["recipe", "chicken", "pastry", "dinner"], "terms": ["butter", "carrot", "chicken", "chips", "flour", "ham", "milk", "mushroom", "puff pastry", "stock", "white wine"], "image": false, "serves": "", "time": "", "items": [{"t": "1 roll of puff pastry", "k": "puff pastry"}, {"t": "4 or 5 chicken breasts", "k": "chicken"}, {"t": "225g wafer thin ham", "k": "ham"}, {"t": "150ml chicken stock", "k": "stock"}, {"t": "150g-200g button mushrooms", "k": "mushroom"}, {"t": "2 large carrots", "k": "carrot"}, {"t": "300-400ml white wine", "k": "white wine"}, {"t": "410g evaporated milk", "k": "milk"}, {"t": "25g plain flour", "k": "flour"}, {"t": "25g butter (for cooking meat)", "k": "butter"}, {"t": "1 tsp milk (for glazing)", "k": "milk"}, {"t": "Chips", "k": "chips"}], "html": "<header><h1>Clare&#x27;s Chicken and Ham Pie<\/h1><p class=\"tags\"><span class=\"tag\">chicken<\/span><span class=\"tag\">pastry<\/span><span class=\"tag\">dinner<\/span><\/p><\/header>\n\n<p class=\"before\"><strong>Before you start<\/strong> heat the oven to 200°C fan.<\/p>\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>1 roll of puff pastry<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>4 or 5 chicken breasts<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>225g wafer thin ham<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>150ml chicken stock<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>150g-200g button mushrooms<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 large carrots<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>300-400ml white wine<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>410g evaporated milk<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>25g plain flour<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Black pepper<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>25g butter (for cooking meat)<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tsp milk (for glazing)<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Chips<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><ol class=\"method\" start=\"1\"><li>Chop the <strong>150g-200g button mushrooms<\/strong> into quarters and the <strong>2 large carrots<\/strong> into chunks (thick rings then chopped into quarters/sixths).<\/li><li>Trim crappy bits off the <strong>4 or 5 chicken breasts<\/strong> and cut into chunks.<\/li><li>Melt the <strong>25g butter<\/strong> on low/medium heat (almost all the way round to simmer setting).<\/li><li>Add the <strong>chicken<\/strong>. Keep turning until white all over and then a bit longer (roughly 5 mins) until largest chunk is white inside.<\/li><li>Tip the <strong>chicken<\/strong> into a bowl so the pan can be drained then put the chicken back in.<\/li><li>Tear the <strong>225g wafer thin ham<\/strong> into chunks and add to the pan.<\/li><li>Turn the heat back on and stir until all mixed up and the <strong>ham<\/strong> is looking slightly cooked (about 4 to 5 mins).<\/li><li>Add the <strong>carrots<\/strong> and <strong>mushrooms<\/strong> and stir continuously until the mushrooms look cooked (about 3 to 5 minutes).<\/li><li>Add the <strong>300-400ml white wine<\/strong> and stir in, leave to simmer for about 10 minutes, then stir it and simmer for about another 5 minutes (until liquid reduced by about half).<\/li><li>While simmering, make <strong>150ml of chicken stock<\/strong> in a jug and mix in the <strong>410g evaporated milk<\/strong>.<\/li><li>Put the <strong>25g plain flour<\/strong> in a bowl. Add a small bit of the stock/milk mix and stir (with beater) to form a thick paste, then add a bit more and stir to make a thin paste, then add the rest and stir (this is to ensure flour evenly distributed without lumps).<\/li><li>Once the reduction is complete, pour the mix into the pan and stir thoroughly.<\/li><li>Allow to come to the boil and stir while it thickens (only takes a few minutes).<\/li><li>Add <strong>black pepper<\/strong> during thickening.<\/li><li>Turn off heat once thickened (not too thick). Can leave like this if making pie later.<\/li><li>Preheat oven to 200°C fan.<\/li><li>Use the <strong>butter<\/strong> to lightly grease the dish (including the rim).<\/li><li>Pour the pan contents into the dish and cover with the <strong>puff pastry<\/strong> and use roller to trim and then glaze with the <strong>1 tsp milk<\/strong> (don&#x27;t make any holes).<\/li><li>Cook for 25 minutes, doing the <strong>chips<\/strong> when appropriate.<\/li><\/ol><\/section>\n<\/div>\n\n<p class=\"source\"><a href=\"clares-chicken-and-ham-pie.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "creamy-courgette-beanotto", "name": "Creamy Courgette Beanotto", "title": "creamy courgette beanotto", "tags": ["recipe", "vegetarian", "beans", "one-pot", "dinner"], "terms": ["basil", "courgette", "crème fraîche", "garlic", "lemon", "parmesan", "parsley", "pine nuts", "stock", "sunflower seeds", "white beans"], "image": true, "serves": "2-3", "time": "30m", "items": [{"t": "2 courgettes, 1 coarsely grated, 1 sliced into ½cm rounds", "k": "courgette"}, {"t": "2 garlic cloves, finely grated", "k": "garlic"}, {"t": "Zest and juice of ½ lemon, plus extra zest to serve", "k": "lemon"}, {"t": "1 x 570g jar of Queen White Beans, or 1 x 660g jar of Organic White Beans, with their bean stock", "k": "white beans"}, {"t": "1 heaped tbsp crème fraîche", "k": "crème fraîche"}, {"t": "45g Parmesan, grated, plus extra to serve", "k": "parmesan"}, {"t": "15g parsley, leaves finely chopped", "k": "parsley"}, {"t": "A good handful of fresh basil leaves", "k": "basil"}, {"t": "A handful of pine nuts or sunflower seeds (optional)", "k": "sunflower seeds"}], "html": "<header><h1>Creamy Courgette Beanotto<\/h1><p class=\"meta\">Serves 2-3 · 30m<\/p><p class=\"tags\"><span class=\"tag\">vegetarian<\/span><span class=\"tag\">beans<\/span><span class=\"tag\">one-pot<\/span><span class=\"tag\">dinner<\/span><\/p><p class=\"lede\">White beans cooked risotto-style with courgette, lemon, crème fraîche and Parmesan.<\/p><\/header>\n<img class=\"hero\" src=\"img/creamy-courgette-beanotto-1600.jpg\" srcset=\"img/creamy-courgette-beanotto-800.jpg 800w, img/creamy-courgette-beanotto-1600.jpg 1600w\" sizes=\"(max-width: 500px) calc(100vw - 40px), (max-width: 940px) 92vw, (max-width: 1200px) calc(940px - 8vw), 844px\" decoding=\"async\" alt=\"Creamy Courgette Beanotto\">\n\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>2 tbsp olive oil, plus extra to serve<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 courgettes, 1 coarsely grated, 1 sliced into ½cm rounds<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 garlic cloves, finely grated<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Zest and juice of ½ lemon, plus extra zest to serve<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 x 570g jar of Queen White Beans, or 1 x 660g jar of Organic White Beans, with their bean stock<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 heaped tbsp crème fraîche<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>45g Parmesan, grated, plus extra to serve<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>15g parsley, leaves finely chopped<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>A good handful of fresh basil leaves<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>A handful of pine nuts or sunflower seeds (optional)<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><ol class=\"method\" start=\"1\"><li>Squeeze as much liquid as you can out of the <strong>1 grated courgette<\/strong>.<\/li><li>Toast the <strong>handful of pine nuts<\/strong> in a dry pan for 2-3 minutes until golden, then set aside.<\/li><li>Heat the <strong>2 tbsp olive oil<\/strong> in a large pan over a medium heat.<\/li><li>Add the <strong>1 sliced courgette<\/strong> with a pinch of salt and cook for 7-8 minutes, stirring occasionally, until starting to brown.<\/li><li>Add the <strong>grated courgette<\/strong> and the <strong>2 garlic cloves<\/strong> and cook for a further 2-3 minutes, until the courgette softens.<\/li><li>Grate in the <strong>zest of ½ lemon<\/strong>.<\/li><li>Pour in the <strong>570g jar of white beans<\/strong> with their bean stock.<\/li><li>Fill the empty jar a quarter full with water, swirl it around and add that to the pan too — it acts as a stock. Stir to combine.<\/li><li>Season well with cracked black pepper, tasting before you add any salt as the beans are already well seasoned.<\/li><li>Reduce the heat to low and stir in the <strong>1 heaped tbsp crème fraîche<\/strong> and the <strong>45g Parmesan<\/strong>, working fairly quickly so the crème fraîche does not split.<\/li><li>Stir in the <strong>15g parsley<\/strong> and tear in most of the <strong>basil leaves<\/strong>, saving a few to garnish.<\/li><li>Add the <strong>juice of ½ lemon<\/strong> and check the seasoning.<\/li><li>Spoon into bowls and grate over <strong>extra lemon zest<\/strong> and <strong>extra Parmesan<\/strong>.<\/li><li>Scatter over the toasted <strong>pine nuts<\/strong> and the remaining <strong>basil<\/strong>, and finish with a drizzle of <strong>olive oil<\/strong>.<\/li><\/ol><\/section>\n<\/div>\n<section class=\"notes\"><h2>Notes<\/h2><p>Something crunchy on top makes a real difference — pine nuts, toasted seeds or breadcrumbs all work.<\/p><p>Make it vegan: use a plant-based crème fraîche and a vegan alternative to the Parmesan.<\/p><p>The source calls for one jar of white beans and links both a 570g and a 660g jar; either size works.<\/p><p>See also <a href=\"miso-mushroom-beanotto.html\">Miso Mushroom Beanotto<\/a> for the colder-weather version.<\/p><\/section>\n<p class=\"source\">Source: <a href=\"https://boldbeanco.com/blogs/beanspo-recipes/creamy-courgette-bean-otto\" rel=\"noreferrer\">https://boldbeanco.com/blogs/beanspo-recipes/creamy-courgette-bean-otto<\/a><\/p><p class=\"source\"><a href=\"creamy-courgette-beanotto.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "creamy-courgette-lasagne", "name": "Creamy Courgette Lasagne", "title": "creamy courgette lasagne", "tags": ["recipe", "vegetarian", "pasta", "dinner"], "terms": ["cheddar", "courgette", "garlic", "onion", "pasta", "pasta sauce", "ricotta", "tomato"], "image": true, "serves": "", "time": "", "items": [{"t": "9 dried lasagne sheets", "k": "pasta"}, {"t": "1 onion, finely chopped", "k": "onion"}, {"t": "700g courgette (about 6), coarsely grated", "k": "courgette"}, {"t": "2 garlic cloves, crushed", "k": "garlic"}, {"t": "250g tub ricotta", "k": "ricotta"}, {"t": "50g cheddar", "k": "cheddar"}, {"t": "350g jar tomato sauce for pasta", "k": "pasta sauce"}], "html": "<header><h1>Creamy Courgette Lasagne<\/h1><p class=\"tags\"><span class=\"tag\">vegetarian<\/span><span class=\"tag\">pasta<\/span><span class=\"tag\">dinner<\/span><\/p><\/header>\n<img class=\"hero\" src=\"img/creamy-courgette-lasagne-1600.jpg\" srcset=\"img/creamy-courgette-lasagne-800.jpg 800w, img/creamy-courgette-lasagne-1600.jpg 1600w\" sizes=\"(max-width: 500px) calc(100vw - 40px), (max-width: 940px) 92vw, (max-width: 1200px) calc(940px - 8vw), 844px\" decoding=\"async\" alt=\"Creamy Courgette Lasagne\">\n<p class=\"before\"><strong>Before you start<\/strong> heat the oven to 220°C/fan 200°C/gas 7.<\/p>\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>9 dried lasagne sheets<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tbsp sunflower oil<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 onion, finely chopped<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>700g courgette (about 6), coarsely grated<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 garlic cloves, crushed<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>250g tub ricotta<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>50g cheddar<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>350g jar tomato sauce for pasta<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><ol class=\"method\" start=\"1\"><li>Heat oven to 220°C/fan 200°C/gas 7. Put a pan of water on to boil, then cook the <strong>9 lasagne sheets<\/strong> for about 5 mins until softened, but not cooked through. Rinse in cold water, then drizzle with a little <strong>oil<\/strong> to stop them sticking together.<\/li><li>Meanwhile, heat the <strong>1 tbsp sunflower oil<\/strong> in a large frying pan, then fry the <strong>1 onion<\/strong>. After 3 mins, add the <strong>700g courgettes<\/strong> and <strong>2 garlic cloves<\/strong> and continue to fry until the courgette has softened and turned bright green.<\/li><li>Stir in 2/3 of both the <strong>250g ricotta<\/strong> and the <strong>50g cheddar<\/strong>, then season to taste.<\/li><li>Heat the <strong>350g tomato sauce<\/strong> in the microwave for 2 mins on High until hot.<\/li><li>In a large baking dish, layer up the <strong>lasagne<\/strong>, starting with half the <strong>courgette<\/strong> mix, then <strong>pasta<\/strong>, then <strong>tomato sauce<\/strong>. Repeat, top with blobs of the remaining <strong>ricotta<\/strong>, then scatter with the rest of the <strong>cheddar<\/strong>. Bake on the top shelf for about 10 mins until the pasta is tender and the cheese is golden.<\/li><\/ol><\/section>\n<\/div>\n\n<p class=\"source\"><a href=\"creamy-courgette-lasagne.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "creamy-halloumi-pea-butter-bean-curry", "name": "Creamy Halloumi, Pea + Butter Bean Curry", "title": "creamy halloumi, pea + butter bean curry", "tags": ["recipe", "vegetarian", "beans", "dinner"], "terms": ["butter beans", "chilli flakes", "chilli powder", "coriander", "cumin", "garam masala", "garlic", "ginger", "ground coriander", "halloumi", "mango chutney", "naan", "nigella seeds", "onion", "peas", "rice", "stock", "tomato", "tomato purée", "turmeric", "yoghurt"], "image": true, "serves": "3", "time": "35m", "items": [{"t": "1 onion, roughly chopped", "k": "onion"}, {"t": "3 garlic cloves, finely grated or minced", "k": "garlic"}, {"t": "A small thumb of fresh ginger, finely grated or minced, or ¼ tsp ground ginger", "k": "ginger"}, {"t": "1 tbsp tomato purée", "k": "tomato purée"}, {"t": "2 tsp ground cumin", "k": "cumin"}, {"t": "2 tsp garam masala", "k": "garam masala"}, {"t": "1 tsp ground coriander", "k": "ground coriander"}, {"t": "1 tsp ground turmeric", "k": "turmeric"}, {"t": "½ tsp chilli powder or chilli flakes", "k": "chilli powder"}, {"t": "1 x 400g tin of chopped tomatoes", "k": "tomato"}, {"t": "75g frozen peas", "k": "peas"}, {"t": "200g halloumi, cut into 2cm cubes", "k": "halloumi"}, {"t": "1 x 660g jar of Queen Butter Beans, with their bean stock", "k": "butter beans"}, {"t": "1-2 tbsp Greek yoghurt", "k": "yoghurt"}, {"t": "1 tsp mango chutney", "k": "mango chutney"}, {"t": "A handful of fresh coriander, roughly chopped", "k": "coriander"}, {"t": "Rice or naan", "k": "rice"}, {"t": "Nigella seeds", "k": "nigella seeds"}], "html": "<header><h1>Creamy Halloumi, Pea + Butter Bean Curry<\/h1><p class=\"meta\">Serves 3 · 35m<\/p><p class=\"tags\"><span class=\"tag\">vegetarian<\/span><span class=\"tag\">beans<\/span><span class=\"tag\">dinner<\/span><\/p><p class=\"lede\">A mildly spiced tomato curry of butter beans and peas, finished with fried halloumi, yoghurt and mango chutney.<\/p><\/header>\n<img class=\"hero\" src=\"img/creamy-halloumi-pea-butter-bean-curry-1600.jpg\" srcset=\"img/creamy-halloumi-pea-butter-bean-curry-800.jpg 800w, img/creamy-halloumi-pea-butter-bean-curry-1600.jpg 1600w\" sizes=\"(max-width: 500px) calc(100vw - 40px), (max-width: 940px) 92vw, (max-width: 1200px) calc(940px - 8vw), 844px\" decoding=\"async\" alt=\"Creamy Halloumi, Pea + Butter Bean Curry\">\n\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>2 tbsp neutral oil, such as rapeseed or vegetable, plus a little extra for frying the halloumi<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 onion, roughly chopped<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>3 garlic cloves, finely grated or minced<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>A small thumb of fresh ginger, finely grated or minced, or ¼ tsp ground ginger<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tbsp tomato purée<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 tsp ground cumin<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 tsp garam masala<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tsp ground coriander<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tsp ground turmeric<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>½ tsp chilli powder or chilli flakes<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 x 400g tin of chopped tomatoes<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>75g frozen peas<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>200g halloumi, cut into 2cm cubes<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 x 660g jar of Queen Butter Beans, with their bean stock<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1-2 tbsp Greek yoghurt<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tsp mango chutney<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>A handful of fresh coriander, roughly chopped<\/span><\/label><\/li><\/ul><h3>To serve<\/h3><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>Rice or naan<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Nigella seeds<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><ol class=\"method\" start=\"1\"><li>Heat the <strong>2 tbsp neutral oil<\/strong> in a large pan over a medium heat.<\/li><li>Add the <strong>1 onion<\/strong> and cook for 8-10 minutes until softened.<\/li><li>Add the <strong>3 garlic cloves<\/strong> and the <strong>ginger<\/strong> and cook for a further 2 minutes until fragrant.<\/li><li>Add the <strong>1 tbsp tomato purée<\/strong>, <strong>2 tsp ground cumin<\/strong>, <strong>2 tsp garam masala<\/strong>, <strong>1 tsp ground coriander<\/strong>, <strong>1 tsp ground turmeric<\/strong> and <strong>½ tsp chilli powder<\/strong> with a small splash of water, stirring to make a paste.<\/li><li>Fry for a couple of minutes, until the purée turns deep red and everything smells fragrant.<\/li><li>Pour in the <strong>400g tin of chopped tomatoes<\/strong> and the <strong>75g frozen peas<\/strong> with a pinch of salt and stir to combine.<\/li><li>Cook for 8-10 minutes, until the peas have turned from vibrant green to a more muted green.<\/li><li>Meanwhile, heat a little <strong>oil<\/strong> in a separate non-stick frying pan over a medium heat.<\/li><li>Fry the <strong>200g halloumi<\/strong> for 2-3 minutes on each side, until golden.<\/li><li>Pour the <strong>660g jar of butter beans and their bean stock<\/strong> into the tomato sauce and stir to combine.<\/li><li>Simmer gently for 3-4 minutes to warm through.<\/li><li>Fold the fried <strong>halloumi<\/strong> gently into the sauce.<\/li><li>Stir in the <strong>1-2 tbsp Greek yoghurt<\/strong>, using more if you like it creamier, and the <strong>1 tsp mango chutney<\/strong>.<\/li><li>Check the seasoning and adjust to taste.<\/li><li>Serve into bowls with <strong>rice<\/strong> or <strong>naan<\/strong>, scattered with the <strong>fresh coriander<\/strong> and a sprinkle of <strong>nigella seeds<\/strong>.<\/li><\/ol><\/section>\n<\/div>\n<section class=\"notes\"><h2>Notes<\/h2><p>The bean stock does the work of thickening the sauce, so use the jar liquid rather than draining it.<\/p><p>An unsweetened coconut or soy yoghurt works in place of the Greek yoghurt.<\/p><\/section>\n<p class=\"source\">Source: <a href=\"https://boldbeanco.com/blogs/beanspo-recipes/creamy-halloumi-butter-bean-curry-with-peas\" rel=\"noreferrer\">https://boldbeanco.com/blogs/beanspo-recipes/creamy-halloumi-butter-bean-curry-with-peas<\/a><\/p><p class=\"source\"><a href=\"creamy-halloumi-pea-butter-bean-curry.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "crispy-kale-and-bulgar-wheat-salad", "name": "Crispy Kale and Bulgar Wheat Salad", "title": "crispy kale and bulgar wheat salad", "tags": ["recipe", "vegetarian", "bulgur", "lunch"], "terms": ["almonds", "bulgur wheat", "coriander", "ginger", "goat's cheese", "kale", "lemon", "pomegranate", "yoghurt", "za'atar"], "image": true, "serves": "2", "time": "", "items": [{"t": "200g bulgur wheat", "k": "bulgur wheat"}, {"t": "5cm ginger, finely grated", "k": "ginger"}, {"t": "Zest of 2 lemons", "k": "lemon"}, {"t": "200g kale", "k": "kale"}, {"t": "1 heaped tbsp za'atar", "k": "za'atar"}, {"t": "1 tbsp lemon juice", "k": "lemon"}, {"t": "100g goats cheese, crumbled", "k": "goat's cheese"}, {"t": "50g whole almonds, toasted", "k": "almonds"}, {"t": "Pomegranate seeds", "k": "pomegranate"}, {"t": "Coriander, roughly chopped", "k": "coriander"}, {"t": "Natural/Greek yoghurt", "k": "yoghurt"}], "html": "<header><h1>Crispy Kale and Bulgar Wheat Salad<\/h1><p class=\"meta\">Serves 2<\/p><p class=\"tags\"><span class=\"tag\">vegetarian<\/span><span class=\"tag\">bulgur<\/span><span class=\"tag\">lunch<\/span><\/p><\/header>\n<img class=\"hero\" src=\"img/crispy-kale-and-bulgar-wheat-salad-1600.jpg\" srcset=\"img/crispy-kale-and-bulgar-wheat-salad-800.jpg 800w, img/crispy-kale-and-bulgar-wheat-salad-1600.jpg 1600w\" sizes=\"(max-width: 500px) calc(100vw - 40px), (max-width: 940px) 92vw, (max-width: 1200px) calc(940px - 8vw), 844px\" decoding=\"async\" alt=\"Crispy Kale and Bulgar Wheat Salad\">\n<p class=\"before\"><strong>Before you start<\/strong> heat the oven to 200°C.<\/p>\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>200g bulgur wheat<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>5cm ginger, finely grated<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Zest of 2 lemons<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>400ml boiling water<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>200g kale<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 heaped tbsp za&#x27;atar<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tbsp lemon juice<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tbsp extra virgin olive oil<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>100g goats cheese, crumbled<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>50g whole almonds, toasted<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Pomegranate seeds<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Coriander, roughly chopped<\/span><\/label><\/li><\/ul><h3>To serve<\/h3><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>Natural/Greek yoghurt<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><ol class=\"method\" start=\"1\"><li>Preheat the oven to 200°C.<\/li><li>Mix the <strong>200g bulgur wheat<\/strong>, <strong>5cm ginger<\/strong>, <strong>zest of 2 lemons<\/strong>, <strong>sea salt<\/strong>, and <strong>400ml boiling water<\/strong> in a roasting tin.<\/li><li>Toss the <strong>200g kale<\/strong> with the <strong>olive oil<\/strong> and tip evenly over the <strong>bulgur wheat<\/strong>.<\/li><li>Transfer to the oven and roast for 15 minutes.<\/li><li>Whisk together the <strong>1 heaped tbsp za&#x27;atar<\/strong>, <strong>1 tbsp lemon juice<\/strong>, and <strong>1 tbsp extra virgin olive oil<\/strong> and set aside.<\/li><li>Mix the cooked <strong>bulgur wheat<\/strong> and the crispy <strong>kale<\/strong> with the dressing.<\/li><li>Scatter over the <strong>100g goats cheese<\/strong>, <strong>50g almonds<\/strong>, <strong>pomegranate seeds<\/strong>, and <strong>coriander<\/strong>.<\/li><li>Serve hot with the <strong>yoghurt<\/strong> alongside.<\/li><\/ol><\/section>\n<\/div>\n\n<p class=\"source\"><a href=\"crispy-kale-and-bulgar-wheat-salad.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "cucumber-melon-and-feta-salad", "name": "Cucumber, Melon & Feta Salad", "title": "cucumber, melon & feta salad", "tags": ["recipe", "vegetarian", "lunch", "dinner"], "terms": ["chilli", "cucumber", "feta", "honey", "melon", "mint", "vinegar"], "image": true, "serves": "4", "time": "", "items": [{"t": "1 tbsp red or white wine vinegar", "k": "vinegar"}, {"t": "1 tsp clear honey", "k": "honey"}, {"t": "1 cantaloupe melon", "k": "melon"}, {"t": "1 cucumber, trimmed", "k": "cucumber"}, {"t": "12 fresh mint leaves, finely shredded", "k": "mint"}, {"t": "100g Greek feta, crumbled", "k": "feta"}, {"t": "1 mild red chilli, deseeded and finely sliced", "k": "chilli"}], "html": "<header><h1>Cucumber, Melon &amp; Feta Salad<\/h1><p class=\"meta\">Serves 4 · 20m prep<\/p><p class=\"tags\"><span class=\"tag\">vegetarian<\/span><span class=\"tag\">lunch<\/span><span class=\"tag\">dinner<\/span><\/p><p class=\"lede\">A really refreshing salad that makes a perfect hot-weather supper. Works a treat with griddled flatbreads on the side.<\/p><\/header>\n<img class=\"hero\" src=\"img/cucumber-melon-and-feta-salad-1600.jpg\" srcset=\"img/cucumber-melon-and-feta-salad-800.jpg 800w, img/cucumber-melon-and-feta-salad-1600.jpg 1600w\" sizes=\"(max-width: 500px) calc(100vw - 40px), (max-width: 940px) 92vw, (max-width: 1200px) calc(940px - 8vw), 844px\" decoding=\"async\" alt=\"Cucumber, Melon &amp; Feta Salad\">\n\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>3 tbsp olive oil (use extra virgin if you have it)<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tbsp red or white wine vinegar<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tsp clear honey<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 cantaloupe melon<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 cucumber, trimmed<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>12 fresh mint leaves, finely shredded<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>100g Greek feta, crumbled<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 mild red chilli, deseeded and finely sliced<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><ol class=\"method\" start=\"1\"><li>Start by making the dressing. In a large mixing bowl, whisk together the <strong>3 tbsp olive oil<\/strong>, <strong>1 tbsp wine vinegar<\/strong> and <strong>1 tsp honey<\/strong>; season.<\/li><li>Halve and deseed the <strong>1 cantaloupe melon<\/strong>, then cut away the skin. Roughly chop the melon into chunks (about 3cm each; don&#x27;t worry if they are odd shapes). Cut the <strong>1 cucumber<\/strong> in a similar way.<\/li><li>Add both to the dressing along with most of the <strong>12 mint leaves<\/strong>, <strong>100g feta<\/strong> and <strong>1 red chilli<\/strong>. Toss together, then divide between plates, scattering the remaining mint, feta and chilli over the top. Serve immediately.<\/li><\/ol><\/section>\n<\/div>\n<section class=\"notes\"><h2>Notes<\/h2><p>Cook&#x27;s tip — adjust the heat: always taste a small piece of chilli before adding to your dish. If it&#x27;s very hot, you may want to use a little less.<\/p><\/section>\n<p class=\"source\">Source: Waitrose, July 2023<\/p><p class=\"source\"><a href=\"cucumber-melon-and-feta-salad.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "dads-chicken-and-ham-pie", "name": "Dad's Chicken and Ham Pie", "title": "dad's chicken and ham pie", "tags": ["recipe", "chicken", "pastry", "dinner"], "terms": ["butter", "carrot", "chicken", "chips", "flour", "ham", "milk", "mushroom", "puff pastry", "stock", "white wine"], "image": true, "serves": "4", "time": "", "items": [{"t": "1 roll of puff pastry", "k": "puff pastry"}, {"t": "150ml chicken stock", "k": "stock"}, {"t": "4 or 5 chicken breasts", "k": "chicken"}, {"t": "25g plain flour", "k": "flour"}, {"t": "225g wafer thin ham", "k": "ham"}, {"t": "150g-200g button mushrooms", "k": "mushroom"}, {"t": "25g butter (for cooking meat)", "k": "butter"}, {"t": "2 large carrots", "k": "carrot"}, {"t": "1 tsp milk (for glazing)", "k": "milk"}, {"t": "300-400ml white wine", "k": "white wine"}, {"t": "Chips", "k": "chips"}, {"t": "410g evaporated milk", "k": "milk"}], "html": "<header><h1>Dad&#x27;s Chicken and Ham Pie<\/h1><p class=\"meta\">Serves 4<\/p><p class=\"tags\"><span class=\"tag\">chicken<\/span><span class=\"tag\">pastry<\/span><span class=\"tag\">dinner<\/span><\/p><\/header>\n<img class=\"hero\" src=\"img/dads-chicken-and-ham-pie-1600.jpg\" srcset=\"img/dads-chicken-and-ham-pie-800.jpg 800w, img/dads-chicken-and-ham-pie-1600.jpg 1600w\" sizes=\"(max-width: 500px) calc(100vw - 40px), (max-width: 940px) 92vw, (max-width: 1200px) calc(940px - 8vw), 844px\" decoding=\"async\" alt=\"Dad&#x27;s Chicken and Ham Pie\">\n<p class=\"before\"><strong>Before you start<\/strong> heat the oven to 200°C fan.<\/p>\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>1 roll of puff pastry<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>150ml chicken stock<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>4 or 5 chicken breasts<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>25g plain flour<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>225g wafer thin ham<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Black pepper<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>150g-200g button mushrooms<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>25g butter (for cooking meat)<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 large carrots<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tsp milk (for glazing)<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>300-400ml white wine<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Chips<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>410g evaporated milk<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><ol class=\"method\" start=\"1\"><li>Chop the <strong>150g-200g button mushrooms<\/strong> into halves/quarters and the <strong>2 large carrots<\/strong> into chunks (thick rings then chopped into quarters/sixths).<\/li><li>Trim crappy bits off the <strong>4 or 5 chicken breasts<\/strong> and cut into chunks.<\/li><li>Melt the <strong>25g butter<\/strong> on low/medium heat (almost all the way round to simmer setting).<\/li><li>Add the <strong>chicken<\/strong>. Keep turning until white all over and then a bit longer (roughly 5 mins) until largest bit white inside.<\/li><li>Tip the <strong>chicken<\/strong> into a bowl so the pan can be drained then put the chicken back in.<\/li><li>Tear the <strong>225g wafer thin ham<\/strong> into chunks and add to the pan.<\/li><li>Turn the heat back on and stir until all mixed up and the <strong>ham<\/strong> is looking slightly cooked (about 4 to 5 mins).<\/li><li>Add the <strong>carrots<\/strong> and <strong>mushrooms<\/strong> and stir continuously until the mushrooms look cooked (about 3 to 5 minutes).<\/li><li>Add the <strong>300-400ml white wine<\/strong> and stir in, leave to simmer for about 10 minutes, then stir it and simmer for about another 5 minutes (until liquid reduced by about half).<\/li><li>While simmering, make <strong>150ml of chicken stock<\/strong> in a jug and mix in the <strong>410g evaporated milk<\/strong>.<\/li><li>Put the <strong>25g plain flour<\/strong> in a bowl. Add a small bit of the stock/milk mix and stir (with beater) to form a thick paste, then add a bit more and stir to make a thin paste, then add the rest and stir (this is to ensure flour evenly distributed without lumps).<\/li><li>Once the reduction is complete, pour the mix into the pan and stir thoroughly.<\/li><li>Allow to come to the boil and stir while it thickens (only takes a few minutes).<\/li><li>Add <strong>black pepper<\/strong> during thickening.<\/li><li>Turn off heat once thickened (not too thick). Can leave like this if making pie later.<\/li><li>Pre-heat oven to 200°C fan.<\/li><li>Use the <strong>butter<\/strong> to lightly grease the dish (including the rim).<\/li><li>Pour the pan contents into the dish and cover with the <strong>puff pastry<\/strong> and use roller to trim and then glaze with the <strong>1 tsp milk<\/strong> (don&#x27;t make any holes).<\/li><li>Cook for 25 minutes, doing the <strong>chips<\/strong> when appropriate.<\/li><\/ol><\/section>\n<\/div>\n\n<p class=\"source\"><a href=\"dads-chicken-and-ham-pie.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "delias-char-grilled-aubergine-salad", "name": "Delia's Char-grilled Aubergine Salad", "title": "delia's char-grilled aubergine salad", "tags": ["recipe", "vegetarian", "lunch"], "terms": ["aubergine", "basil", "crème fraîche", "feta", "paprika", "salad leaves", "spinach", "tomato", "vinegar"], "image": true, "serves": "4", "time": "", "items": [{"t": "2 medium aubergines, cut into 1cm slices", "k": "aubergine"}, {"t": "8 small, ripe plum tomatoes", "k": "tomato"}, {"t": "200g pack feta cheese, cut into thin slices", "k": "feta"}, {"t": "1 heaped tbsp torn fresh basil leaves", "k": "basil"}, {"t": "2 tbsp balsamic vinegar", "k": "vinegar"}, {"t": "110g spinach / assorted salad leaves", "k": "salad leaves"}, {"t": "200ml tub half-fat crème fraîche", "k": "crème fraîche"}, {"t": "A little paprika", "k": "paprika"}], "html": "<header><h1>Delia&#x27;s Char-grilled Aubergine Salad<\/h1><p class=\"meta\">Serves 4<\/p><p class=\"tags\"><span class=\"tag\">vegetarian<\/span><span class=\"tag\">lunch<\/span><\/p><\/header>\n<img class=\"hero\" src=\"img/delias-char-grilled-aubergine-salad-1600.jpg\" srcset=\"img/delias-char-grilled-aubergine-salad-800.jpg 800w, img/delias-char-grilled-aubergine-salad-1600.jpg 1600w\" sizes=\"(max-width: 500px) calc(100vw - 40px), (max-width: 940px) 92vw, (max-width: 1200px) calc(940px - 8vw), 844px\" decoding=\"async\" alt=\"Delia&#x27;s Char-grilled Aubergine Salad\">\n\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>2 medium aubergines, cut into 1cm slices<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>8 small, ripe plum tomatoes<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>200g pack feta cheese, cut into thin slices<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>8 tbsp extra virgin olive oil<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 heaped tbsp torn fresh basil leaves<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 tbsp balsamic vinegar<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>110g spinach / assorted salad leaves<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>200ml tub half-fat crème fraîche<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>A little paprika<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><ol class=\"method\" start=\"1\"><li>Skin the <strong>8 plum tomatoes<\/strong> by covering them with boiling water for 1 minute, then drain them and slip off their skins. Alternatively, if you have a gas hob, burn the skins off on a hob flame.<\/li><li>Place the <strong>tomatoes<\/strong> onto a baking tray, cut-side up, drizzle over <strong>olive oil<\/strong> and roast for 50-60 mins.<\/li><li>Lay out the <strong>2 medium aubergine<\/strong> slices and sprinkle both sides with <strong>salt<\/strong> (to dry them) and wait for 20 mins.<\/li><li>Blot the <strong>aubergine<\/strong> with kitchen paper to remove the moisture and brush them with <strong>olive oil<\/strong> and sprinkle with <strong>pepper<\/strong>.<\/li><li>Brush a griddle pan lightly with <strong>olive oil<\/strong> and get to a high heat before grilling the <strong>aubergine<\/strong> for about 2 ½ mins on each side.<\/li><li>Add <strong>6 tbsp of the olive oil<\/strong> in a bowl with the <strong>1 heaped tbsp basil<\/strong>, <strong>2 tbsp balsamic vinegar<\/strong> and mix in the <strong>aubergine<\/strong> slices.<\/li><li>Divide the <strong>110g salad leaves<\/strong> between 4 plates and arrange the <strong>tomatoes<\/strong> and <strong>aubergines<\/strong> alternately all around. Then place the <strong>200g feta<\/strong> slices in the middle of each salad and drizzle with the remaining marinade.<\/li><li>Put <strong>1 tbsp of the crème fraîche<\/strong> on top of each salad and sprinkle a little <strong>paprika<\/strong> over.<\/li><\/ol><\/section>\n<\/div>\n\n<p class=\"source\"><a href=\"delias-char-grilled-aubergine-salad.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "fusilli-a-la-vodka-with-basil-and-parmesan", "name": "Fusilli a la Vodka with Basil and Parmesan", "title": "fusilli a la vodka with basil and parmesan", "tags": ["recipe", "vegetarian", "pasta", "dinner"], "terms": ["basil", "butter", "chilli flakes", "double cream", "garlic", "parmesan", "pasta", "shallot", "tomato purée", "vodka"], "image": false, "serves": "", "time": "", "items": [{"t": "450g fusilli", "k": "pasta"}, {"t": "½ a shallot", "k": "shallot"}, {"t": "2 tbsp vodka", "k": "vodka"}, {"t": "230g double cream", "k": "double cream"}, {"t": "1 tsp red pepper flakes", "k": "chilli flakes"}, {"t": "7 tbsp tomato purée", "k": "tomato purée"}, {"t": "1 garlic clove", "k": "garlic"}, {"t": "Unsalted butter", "k": "butter"}, {"t": "Parmesan", "k": "parmesan"}, {"t": "Basil", "k": "basil"}], "html": "<header><h1>Fusilli a la Vodka with Basil and Parmesan<\/h1><p class=\"tags\"><span class=\"tag\">vegetarian<\/span><span class=\"tag\">pasta<\/span><span class=\"tag\">dinner<\/span><\/p><\/header>\n\n\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>450g fusilli<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>½ a shallot<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 tbsp vodka<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>230g double cream<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tsp red pepper flakes<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>7 tbsp tomato purée<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 garlic clove<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Olive oil<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Unsalted butter<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Parmesan<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Basil<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><ol class=\"method\" start=\"1\"><li>Heat <strong>olive oil<\/strong> in a large frying pan over medium heat. Add the <strong>½ shallot<\/strong> and <strong>1 garlic clove<\/strong> and cook, stirring occasionally, until softened, about 5 minutes.<\/li><li>Add the <strong>7 tbsp tomato purée<\/strong> and cook, stirring occasionally, until the purée is brick red and starts to caramelise, about 5 minutes.<\/li><li>Add the <strong>2 tbsp vodka<\/strong> and cook, stirring constantly, until liquid is mostly evaporated, about 2 minutes.<\/li><li>Add the <strong>230g double cream<\/strong> and <strong>1 tsp red pepper flakes<\/strong> and stir until well blended. Season with <strong>salt and pepper<\/strong>; remove from heat.<\/li><li>Meanwhile, cook the <strong>450g fusilli<\/strong> in a large pot of boiling salted water, stirring occasionally, until al dente. Drain, reserving 2 or 3 ladles of pasta cooking liquid.<\/li><li>Add the <strong>pasta<\/strong> to the pan with the sauce along with the <strong>butter<\/strong> and 1 or 2 ladles of pasta cooking liquid. Cook over medium-low heat, stirring constantly and adding more pasta cooking liquid if needed, until butter has melted and a thick, glossy sauce has formed, about 2 minutes.<\/li><li>Season with <strong>salt and pepper<\/strong> and add <strong>Parmesan<\/strong>, tossing to coat. Divide pasta among bowls, then top with <strong>basil<\/strong> and more <strong>Parmesan<\/strong>.<\/li><\/ol><\/section>\n<\/div>\n\n<p class=\"source\"><a href=\"fusilli-a-la-vodka-with-basil-and-parmesan.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "gorgonzola-risotto", "name": "Gorgonzola Risotto", "title": "gorgonzola risotto", "tags": ["recipe", "vegetarian", "rice", "one-pot", "dinner"], "terms": ["butter", "garlic", "gorgonzola", "leek", "rice", "stock", "tarragon", "white wine"], "image": false, "serves": "3", "time": "", "items": [{"t": "25g butter", "k": "butter"}, {"t": "2 leeks, sliced", "k": "leek"}, {"t": "1 garlic clove", "k": "garlic"}, {"t": "125g risotto rice", "k": "rice"}, {"t": "1 glass white wine", "k": "white wine"}, {"t": "900ml vegetable stock", "k": "stock"}, {"t": "2 tbsp tarragon, chopped", "k": "tarragon"}, {"t": "125g gorgonzola cheese", "k": "gorgonzola"}], "html": "<header><h1>Gorgonzola Risotto<\/h1><p class=\"meta\">Serves 3<\/p><p class=\"tags\"><span class=\"tag\">vegetarian<\/span><span class=\"tag\">rice<\/span><span class=\"tag\">one-pot<\/span><span class=\"tag\">dinner<\/span><\/p><\/header>\n\n\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>1 tbsp olive oil<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>25g butter<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 leeks, sliced<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 garlic clove<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>125g risotto rice<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 glass white wine<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>900ml vegetable stock<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 tbsp tarragon, chopped<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>125g gorgonzola cheese<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><ol class=\"method\" start=\"1\"><li>Heat the <strong>1 tbsp of olive oil<\/strong> and ½ (<strong>12.5g<\/strong>) of the <strong>butter<\/strong> in a wide, shallow pan. Add the <strong>2 leeks<\/strong> and <strong>1 garlic clove<\/strong> and cook over a gentle heat for 4-5 minutes, stirring occasionally.<\/li><li>Add the <strong>125g risotto rice<\/strong> and stir to coat in the oil.<\/li><li>Increase the heat a little and pour in the <strong>1 glass of white wine<\/strong>. Simmer for 2 minutes.<\/li><li>Add a ladleful of the <strong>900ml vegetable stock<\/strong> and simmer, stirring occasionally until all the liquid has been absorbed. Continue adding the <strong>stock<\/strong> in this way until it has all been used and the rice is tender and creamy.<\/li><li>Season and stir in the <strong>2 tbsp tarragon<\/strong>. Remove from the heat and fold the remaining <strong>butter<\/strong> and the <strong>125g gorgonzola cheese<\/strong> through the risotto. Serve immediately.<\/li><\/ol><\/section>\n<\/div>\n\n<p class=\"source\"><a href=\"gorgonzola-risotto.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "harissa-chickpeas", "name": "Harissa Chickpeas", "title": "harissa chickpeas", "tags": ["recipe", "vegan", "lunch"], "terms": ["chickpeas", "cumin", "fennel seeds", "harissa", "lemon"], "image": false, "serves": "", "time": "", "items": [{"t": "1 large can of chickpeas in water, drained", "k": "chickpeas"}, {"t": "½ tsp cumin seeds", "k": "cumin"}, {"t": "½ tsp fennel seeds", "k": "fennel seeds"}, {"t": "Lemon juice", "k": "lemon"}, {"t": "Harissa paste", "k": "harissa"}], "html": "<header><h1>Harissa Chickpeas<\/h1><p class=\"tags\"><span class=\"tag\">vegan<\/span><span class=\"tag\">lunch<\/span><\/p><\/header>\n\n\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>1 large can of chickpeas in water, drained<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>½ tsp cumin seeds<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>½ tsp fennel seeds<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Lemon juice<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Harissa paste<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Pinch of salt<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><ol class=\"method\" start=\"1\"><li>Grind the <strong>½ tsp cumin seeds<\/strong> and <strong>½ tsp fennel seeds<\/strong> together, but not to a powder.<\/li><li>Drain the <strong>1 large can of chickpeas<\/strong>.<\/li><li>Throw the spices over the <strong>chickpeas<\/strong> with <strong>lemon juice<\/strong>.<\/li><li>Add <strong>harissa paste<\/strong> and a <strong>pinch of salt<\/strong>.<\/li><\/ol><\/section>\n<\/div>\n<section class=\"notes\"><h2>Notes<\/h2><p>Separated out from Clare&amp;#x27;s Avocado and Goat&amp;#x27;s Cheese Salad, where this was recorded in the same document. The two may have been intended to go together.<\/p><\/section>\n<p class=\"source\"><a href=\"harissa-chickpeas.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "honey-mustard-chicken-pasta", "name": "Honey Mustard Chicken Pasta", "title": "honey mustard chicken pasta", "tags": ["recipe", "chicken", "pasta", "lunch"], "terms": ["basil", "chicken", "honey", "mayonnaise", "mustard", "pasta", "spring onion", "tomato"], "image": false, "serves": "3", "time": "", "items": [{"t": "300g farfalle or other pasta", "k": "pasta"}, {"t": "3 tbsp reduced-fat (or full-fat) mayo", "k": "mayonnaise"}, {"t": "1 heaped tsp wholegrain mustard", "k": "mustard"}, {"t": "1 tsp clear honey", "k": "honey"}, {"t": "300g cooked chicken, in small chunks", "k": "chicken"}, {"t": "4 spring onions (or half a red onion), thinly sliced", "k": "spring onion"}, {"t": "Small bunch basil, roughly torn", "k": "basil"}, {"t": "4 tomatoes, in eighths", "k": "tomato"}], "html": "<header><h1>Honey Mustard Chicken Pasta<\/h1><p class=\"meta\">Serves 3<\/p><p class=\"tags\"><span class=\"tag\">chicken<\/span><span class=\"tag\">pasta<\/span><span class=\"tag\">lunch<\/span><\/p><\/header>\n\n\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>300g farfalle or other pasta<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>3 tbsp reduced-fat (or full-fat) mayo<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 heaped tsp wholegrain mustard<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tsp clear honey<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>300g cooked chicken, in small chunks<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>4 spring onions (or half a red onion), thinly sliced<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Small bunch basil, roughly torn<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>4 tomatoes, in eighths<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><ol class=\"method\" start=\"1\"><li>Boil the <strong>300g farfalle<\/strong>, then cool under running water.<\/li><li>Mix the <strong>3 tbsp mayo<\/strong>, <strong>1 heaped tsp wholegrain mustard<\/strong> and <strong>1 tsp clear honey<\/strong> in a large bowl and loosen with a little water to make a dressing with the consistency of double cream.<\/li><li>Add the <strong>pasta<\/strong>, <strong>300g cooked chicken<\/strong>, <strong>4 spring onions<\/strong>, <strong>basil<\/strong> and <strong>4 tomatoes<\/strong>, season to taste, then gently mix together.<\/li><\/ol><\/section>\n<\/div>\n\n<p class=\"source\"><a href=\"honey-mustard-chicken-pasta.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "huevos-rancheros", "name": "Huevos Rancheros", "title": "huevos rancheros", "tags": ["recipe", "vegetarian", "bread", "one-pot", "breakfast"], "terms": ["bay leaves", "cheddar", "chilli", "cloves", "eggs", "garlic", "onion", "red pepper", "tomato", "tortillas"], "image": true, "serves": "", "time": "", "items": [{"t": "1 onion", "k": "onion"}, {"t": "2 cloves of garlic", "k": "garlic"}, {"t": "2 red peppers", "k": "red pepper"}, {"t": "2 fresh red or orange chillies", "k": "chilli"}, {"t": "1 large dried chilli", "k": "chilli"}, {"t": "3 fresh bay leaves", "k": "bay leaves"}, {"t": "2 x 400g tins of quality plum tomatoes", "k": "tomato"}, {"t": "2 large ripe tomatoes", "k": "tomato"}, {"t": "6 large free-range eggs", "k": "eggs"}, {"t": "6 tortillas", "k": "tortillas"}, {"t": "Cheddar cheese, to serve", "k": "cheddar"}], "html": "<header><h1>Huevos Rancheros<\/h1><p class=\"tags\"><span class=\"tag\">vegetarian<\/span><span class=\"tag\">bread<\/span><span class=\"tag\">one-pot<\/span><span class=\"tag\">breakfast<\/span><\/p><\/header>\n<img class=\"hero\" src=\"img/huevos-rancheros-1600.jpg\" srcset=\"img/huevos-rancheros-800.jpg 800w, img/huevos-rancheros-1600.jpg 1600w\" sizes=\"(max-width: 500px) calc(100vw - 40px), (max-width: 940px) 92vw, (max-width: 1200px) calc(940px - 8vw), 844px\" decoding=\"async\" alt=\"Huevos Rancheros\">\n<p class=\"before\"><strong>Before you start<\/strong> heat the oven to 180°C/gas 4 if you plan to warm the tortillas in it.<\/p>\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>1 onion<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 cloves of garlic<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 red peppers<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 fresh red or orange chillies<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Olive oil<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 large dried chilli<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>3 fresh bay leaves<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 x 400g tins of quality plum tomatoes<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 large ripe tomatoes<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>6 large free-range eggs<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>6 tortillas<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Cheddar cheese, to serve<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><ol class=\"method\" start=\"1\"><li>Peel and finely slice the <strong>1 onion<\/strong> and <strong>2 cloves of garlic<\/strong>. Deseed and finely slice the <strong>2 red peppers<\/strong> and <strong>2 fresh chillies<\/strong>.<\/li><li>Get a large frying pan (make sure you&#x27;ve got a lid to go with it) on a high heat and add several good lugs of <strong>olive oil<\/strong>.<\/li><li>Add the <strong>onion<\/strong>, <strong>garlic<\/strong>, <strong>peppers<\/strong>, <strong>fresh and dried chillies<\/strong>, <strong>3 bay leaves<\/strong> and a good pinch of <strong>sea salt and black pepper<\/strong>, and cook for 15 minutes, or until softened and caramelised, stirring regularly.<\/li><li>Pour in the <strong>2 x 400g tins of plum tomatoes<\/strong>, using a spoon or potato masher to break them up. Bring to the boil, then turn down to a medium heat and cook for a further 5 minutes to reduce the sauce.<\/li><li>When you&#x27;ve got a nice thick tomato stew consistency, have a taste and adjust the seasoning, if needed.<\/li><li>Slice the <strong>2 large ripe tomatoes<\/strong> and lay them over the top of the mixture.<\/li><li>Use a spoon to make small wells in the tomato stew, then crack in the <strong>6 eggs<\/strong> so they poach in the thick, delicious juices – try to crack them in as quickly as you can so they all get to cook for roughly the same amount of time.<\/li><li>Season from a height, put the lid on and let the <strong>eggs<\/strong> cook for around 3 to 4 minutes, or until cooked to your liking.<\/li><li>Warm the <strong>6 tortillas<\/strong> while this is happening. You can pop them into the oven at 180°C/gas 4 for a few minutes, microwave them for a few seconds or even lay them over the lid of the pan so they heat up as the eggs cook.<\/li><li>Take the lid off and check your <strong>eggs<\/strong> by giving them a poke with your finger. When they&#x27;re done to your liking, turn the heat off and take the pan to the table with the warmed <strong>tortillas<\/strong>, the <strong>Cheddar<\/strong> and a grater so everyone can get involved and make their own.<\/li><li>Personally, I like to grate a bit of cheese right on to a warm tortilla, spoon an egg and some of the wonderful tomato stew on top, wrap it up, and eat it right away. What a beautiful way to wake up!<\/li><\/ol><\/section>\n<\/div>\n\n<p class=\"source\"><a href=\"huevos-rancheros.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "kale-salad-bk", "name": "Kale Salad (BK)", "title": "kale salad (bk)", "tags": ["recipe", "vegetarian", "lunch"], "terms": ["breadcrumbs", "chilli flakes", "garlic", "kale", "lemon", "parmesan"], "image": false, "serves": "6-8", "time": "", "items": [{"t": "3 garlic cloves, finely minced", "k": "garlic"}, {"t": "1 tsp chilli flakes", "k": "chilli flakes"}, {"t": "Juice of 3 lemons", "k": "lemon"}, {"t": "500g kale or cavolo nero, washed and dried", "k": "kale"}, {"t": "150g finely grated Parmesan", "k": "parmesan"}, {"t": "4 tbsp breadcrumbs", "k": "breadcrumbs"}], "html": "<header><h1>Kale Salad (BK)<\/h1><p class=\"meta\">Serves 6-8<\/p><p class=\"tags\"><span class=\"tag\">vegetarian<\/span><span class=\"tag\">lunch<\/span><\/p><\/header>\n\n<p class=\"before\"><strong>Before you start<\/strong> needs 30 minutes resting at room temperature, or up to one day in the refrigerator.<\/p>\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><h3>Dressing<\/h3><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>125ml good-quality olive oil<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>3 garlic cloves, finely minced<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tsp chilli flakes<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Juice of 3 lemons<\/span><\/label><\/li><\/ul><h3>Salad<\/h3><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>500g kale or cavolo nero, washed and dried<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>150g finely grated Parmesan<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>4 tbsp breadcrumbs<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Flaky sea salt and freshly cracked pepper, to taste<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><ol class=\"method\" start=\"1\"><li>Mix together the <strong>125ml olive oil<\/strong>, <strong>juice of 3 lemons<\/strong>, <strong>3 garlic cloves<\/strong> and <strong>1 tsp chilli flakes<\/strong> in a large bowl.<\/li><li>After washing and drying the <strong>500g kale<\/strong>, cut and discard the tough inner ribs. Chop the leaves into smaller pieces and add to the bowl. Mix with the dressing so every piece is coated, using salad servers or clean hands. Leave to rest for 30 minutes at room temperature, or up to one day in the refrigerator.<\/li><li>Before serving, toss the kale again and add the <strong>150g Parmesan<\/strong>, <strong>4 tbsp breadcrumbs<\/strong> and <strong>flaky sea salt and cracked pepper<\/strong>. Toss again and taste, adding more salt, pepper, Parmesan or breadcrumbs as needed. Serve immediately.<\/li><\/ol><\/section>\n<\/div>\n<section class=\"notes\"><h2>Notes<\/h2><p>Serves 6-8 as a side.<\/p><\/section>\n<p class=\"source\">Source: <a href=\"https://www.boroughkitchen.com/blogs/news/danas-amazing-summer-kale-salad\" rel=\"noreferrer\">https://www.boroughkitchen.com/blogs/news/danas-amazing-summer-kale-salad<\/a><\/p><p class=\"source\"><a href=\"kale-salad-bk.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "masala-baked-beans-with-pickled-red-onion-fresh-coriander", "name": "Masala Baked Beans with Pickled Red Onion + Fresh Coriander", "title": "masala baked beans with pickled red onion + fresh coriander", "tags": ["recipe", "vegetarian", "beans", "bread", "breakfast", "lunch"], "terms": ["agave", "baked beans", "bread", "coriander", "honey", "onion", "vinegar"], "image": true, "serves": "2", "time": "10m", "items": [{"t": "1 x 390g jar of Bold Bean Co Masala Baked Beans", "k": "baked beans"}, {"t": "2 tbsp pickled red onions, shop-bought or made from scratch", "k": "onion"}, {"t": "A handful of coriander leaves", "k": "coriander"}, {"t": "2 slices of sourdough bread, or bread of choice", "k": "bread"}, {"t": "1 red onion, very finely sliced", "k": "onion"}, {"t": "120ml apple cider vinegar or white wine vinegar", "k": "vinegar"}, {"t": "1 tsp honey or agave", "k": "honey"}], "html": "<header><h1>Masala Baked Beans with Pickled Red Onion + Fresh Coriander<\/h1><p class=\"meta\">Serves 2 · 10m<\/p><p class=\"tags\"><span class=\"tag\">vegetarian<\/span><span class=\"tag\">beans<\/span><span class=\"tag\">bread<\/span><span class=\"tag\">breakfast<\/span><span class=\"tag\">lunch<\/span><\/p><p class=\"lede\">Jarred masala baked beans warmed through and piled onto toast with quick pickled red onion and coriander.<\/p><\/header>\n<img class=\"hero\" src=\"img/masala-baked-beans-with-pickled-red-onion-fresh-coriander-1600.jpg\" srcset=\"img/masala-baked-beans-with-pickled-red-onion-fresh-coriander-800.jpg 800w, img/masala-baked-beans-with-pickled-red-onion-fresh-coriander-1600.jpg 1600w\" sizes=\"(max-width: 500px) calc(100vw - 40px), (max-width: 940px) 92vw, (max-width: 1200px) calc(940px - 8vw), 844px\" decoding=\"async\" alt=\"Masala Baked Beans with Pickled Red Onion + Fresh Coriander\">\n<p class=\"before\"><strong>Before you start<\/strong> the pickled red onion needs at least 30 minutes pickling, or use shop-bought.<\/p>\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>1 x 390g jar of Bold Bean Co Masala Baked Beans<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 tbsp pickled red onions, shop-bought or made from scratch<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>A handful of coriander leaves<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 slices of sourdough bread, or bread of choice<\/span><\/label><\/li><\/ul><h3>For the quick pickled red onion<\/h3><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>1 red onion, very finely sliced<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>120ml apple cider vinegar or white wine vinegar<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>120ml water<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tsp honey or agave<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><ol class=\"method\" start=\"1\"><li>Put the <strong>1 red onion<\/strong>, <strong>120ml apple cider vinegar<\/strong>, <strong>120ml water<\/strong> and <strong>1 tsp honey or agave<\/strong> into a jar with a pinch of salt.<\/li><li>Secure the lid and shake.<\/li><li>Leave to pickle for at least 30 minutes.<\/li><li>Heat the <strong>390g jar of masala baked beans<\/strong> in a pan over a medium heat for 2-3 minutes.<\/li><li>Toast the <strong>2 slices of sourdough<\/strong> until crisp and golden — either in a toaster for a lighter finish, or in a pan with a drizzle of olive oil, frying both sides.<\/li><li>Spoon the beans onto the toast.<\/li><li>Top with the <strong>2 tbsp pickled red onions<\/strong> and the <strong>handful of coriander leaves<\/strong>, and serve immediately.<\/li><\/ol><\/section>\n<\/div>\n<section class=\"notes\"><h2>Notes<\/h2><p>Built around a ready-made jar of spiced beans (tomato and mango based) rather than plain beans, so it is really an assembly job. Any jar of spiced or curried baked beans will do the same work.<\/p><p>The pickled onions keep in the fridge for up to two weeks.<\/p><p>A dollop of yoghurt on top is good too.<\/p><p>Use agave rather than honey to make it vegan.<\/p><\/section>\n<p class=\"source\">Source: <a href=\"https://boldbeanco.com/blogs/beanspo-recipes/masala-baked-beans-with-pickled-red-onion-fresh-coriander\" rel=\"noreferrer\">https://boldbeanco.com/blogs/beanspo-recipes/masala-baked-beans-with-pickled-red-onion-fresh-coriander<\/a><\/p><p class=\"source\"><a href=\"masala-baked-beans-with-pickled-red-onion-fresh-coriander.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "miso-mushroom-beanotto", "name": "Miso Mushroom Beanotto", "title": "miso mushroom beanotto", "tags": ["recipe", "vegetarian", "beans", "one-pot", "dinner"], "terms": ["bread", "butter", "miso", "mushroom", "parmesan", "stock", "white beans"], "image": true, "serves": "2", "time": "35m", "items": [{"t": "30g butter", "k": "butter"}, {"t": "250-300g mushrooms, roughly chopped", "k": "mushroom"}, {"t": "1 x 570g jar of Queen White Beans, or 1 x 660g jar of Organic White Beans, with their bean stock", "k": "white beans"}, {"t": "1 heaped tbsp miso", "k": "miso"}, {"t": "45g Parmesan, grated, plus extra to serve", "k": "parmesan"}, {"t": "Crusty bread, to serve (optional)", "k": "bread"}], "html": "<header><h1>Miso Mushroom Beanotto<\/h1><p class=\"meta\">Serves 2 · 35m<\/p><p class=\"tags\"><span class=\"tag\">vegetarian<\/span><span class=\"tag\">beans<\/span><span class=\"tag\">one-pot<\/span><span class=\"tag\">dinner<\/span><\/p><p class=\"lede\">White beans cooked risotto-style in a miso and mushroom sauce, finished with Parmesan.<\/p><\/header>\n<img class=\"hero\" src=\"img/miso-mushroom-beanotto-1600.jpg\" srcset=\"img/miso-mushroom-beanotto-800.jpg 800w, img/miso-mushroom-beanotto-1600.jpg 1600w\" sizes=\"(max-width: 500px) calc(100vw - 40px), (max-width: 940px) 92vw, (max-width: 1200px) calc(940px - 8vw), 844px\" decoding=\"async\" alt=\"Miso Mushroom Beanotto\">\n\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>30g butter<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>250-300g mushrooms, roughly chopped<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 x 570g jar of Queen White Beans, or 1 x 660g jar of Organic White Beans, with their bean stock<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 heaped tbsp miso<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>45g Parmesan, grated, plus extra to serve<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Olive oil, to serve<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Crusty bread, to serve (optional)<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><ol class=\"method\" start=\"1\"><li>Melt the <strong>30g butter<\/strong> in a large pan over a medium heat.<\/li><li>Fry the <strong>250-300g mushrooms<\/strong> for roughly 5 minutes, until browned.<\/li><li>Add the <strong>570g jar of white beans<\/strong> with their bean stock.<\/li><li>Fill the empty jar a quarter full with water, swirl it around and add that to the pan too.<\/li><li>Stir everything together and cook for 4-5 minutes, until the beans are warmed through.<\/li><li>Stir in the <strong>1 heaped tbsp miso<\/strong> and cook for a further minute, until the sauce is rich and glossy. Add a splash of water to loosen it if necessary.<\/li><li>Just before serving, stir through the <strong>45g grated Parmesan<\/strong> and a few cracks of black pepper.<\/li><li>Spoon into bowls and finish with <strong>extra Parmesan<\/strong> and a drizzle of <strong>olive oil<\/strong>.<\/li><li>Serve with <strong>crusty bread<\/strong>, if you like.<\/li><\/ol><\/section>\n<\/div>\n<section class=\"notes\"><h2>Notes<\/h2><p>The source suggests leaving out the Parmesan for a vegan version; the butter would need swapping for a plant-based alternative too.<\/p><\/section>\n<p class=\"source\">Source: <a href=\"https://boldbeanco.com/blogs/beanspo-recipes/mushroom-miso-beanotto\" rel=\"noreferrer\">https://boldbeanco.com/blogs/beanspo-recipes/mushroom-miso-beanotto<\/a><\/p><p class=\"source\"><a href=\"miso-mushroom-beanotto.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "mums-baked-lemon-cheesecake", "name": "Mum's Baked Lemon Cheesecake", "title": "mum's baked lemon cheesecake", "tags": ["recipe", "vegetarian", "dessert"], "terms": ["butter", "digestive biscuits", "eggs", "flour", "lemon", "quark", "soured cream", "sugar", "vanilla extract"], "image": false, "serves": "", "time": "", "items": [{"t": "250g packet digestives", "k": "digestive biscuits"}, {"t": "125g unsalted butter", "k": "butter"}, {"t": "1 large unwaxed lemon", "k": "lemon"}, {"t": "2 x 250g tubs Quark", "k": "quark"}, {"t": "142ml carton soured cream", "k": "soured cream"}, {"t": "2 medium eggs", "k": "eggs"}, {"t": "175g golden caster sugar", "k": "sugar"}, {"t": "1½ tsp vanilla extract", "k": "vanilla extract"}, {"t": "1 level tbsp cornflour", "k": "flour"}], "html": "<header><h1>Mum&#x27;s Baked Lemon Cheesecake<\/h1><p class=\"tags\"><span class=\"tag\">vegetarian<\/span><span class=\"tag\">dessert<\/span><\/p><\/header>\n\n<p class=\"before\"><strong>Before you start<\/strong> heat the oven to 180°C/fan 160°C. Needs 1hr chilling for the base, then at least 2hr or overnight chilling once baked.<\/p>\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>250g packet digestives<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>125g unsalted butter<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 large unwaxed lemon<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 x 250g tubs Quark<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>142ml carton soured cream<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 medium eggs<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>175g golden caster sugar<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1½ tsp vanilla extract<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 level tbsp cornflour<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><ol class=\"method\" start=\"1\"><li>For the base, put the <strong>250g packet digestives<\/strong> in a food processor and whiz until fine. Melt the <strong>125g unsalted butter<\/strong>, add to the <strong>biscuits<\/strong> and mix in the processor until well combined.<\/li><li>Tip the mixture into a greased 20.5cm springform tin. Using the back of a spoon, press evenly into the base. Chill for 1hr until firm.<\/li><li>Preheat the oven to 180°C/fan 160°C. Grate the rind from the <strong>1 large unwaxed lemon<\/strong> and put aside. Halve the lemon, cut 3 thin slices from one half and put to one side. Squeeze the juice from the lemon into a small bowl or cup.<\/li><li>To make the filling, put the <strong>lemon rind<\/strong>, <strong>lemon juice<\/strong>, <strong>2 x 250g tubs Quark<\/strong>, <strong>142ml soured cream<\/strong>, <strong>2 medium eggs<\/strong>, <strong>175g golden caster sugar<\/strong>, <strong>1½ tsp vanilla extract<\/strong> and <strong>1 level tbsp cornflour<\/strong> into a large bowl. Using an electric mixer, whisk together until thick and smooth.<\/li><li>Pour mixture into tin and shake gently to level. Bake for 30 min. Put the <strong>lemon slices<\/strong>, overlapping on top. Bake for another 20-25 mins until just set and golden brown. Turn off oven, leaving the cheesecake inside and door ajar. When cheesecake is cool, chill for at least 2hr or overnight.<\/li><\/ol><\/section>\n<\/div>\n\n<p class=\"source\"><a href=\"mums-baked-lemon-cheesecake.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "mums-chicken-mooli", "name": "Mum's Chicken Mooli", "title": "mum's chicken mooli", "tags": ["recipe", "chicken", "one-pot", "dinner"], "terms": ["cardamom", "chicken", "chilli", "cinnamon", "cloves", "coconut milk", "garlic", "ginger", "lemon", "onion", "turmeric"], "image": true, "serves": "", "time": "", "items": [{"t": "4 chicken breasts, cut into big chunks", "k": "chicken"}, {"t": "6 cardamom", "k": "cardamom"}, {"t": "6 cloves", "k": "cloves"}, {"t": "5cm cinnamon stick", "k": "cinnamon"}, {"t": "1 large onion, finely sliced", "k": "onion"}, {"t": "2 garlic cloves", "k": "garlic"}, {"t": "3.5cm piece of ginger, chopped", "k": "ginger"}, {"t": "3 green chillies, seeded", "k": "chilli"}, {"t": "juice of 1 lemon", "k": "lemon"}, {"t": "1 tsp turmeric", "k": "turmeric"}, {"t": "50g creamed coconut (and 150ml hot water)", "k": "coconut milk"}], "html": "<header><h1>Mum&#x27;s Chicken Mooli<\/h1><p class=\"tags\"><span class=\"tag\">chicken<\/span><span class=\"tag\">one-pot<\/span><span class=\"tag\">dinner<\/span><\/p><\/header>\n<img class=\"hero\" src=\"img/mums-chicken-mooli-1600.jpg\" srcset=\"img/mums-chicken-mooli-800.jpg 800w, img/mums-chicken-mooli-1600.jpg 1600w\" sizes=\"(max-width: 500px) calc(100vw - 40px), (max-width: 940px) 92vw, (max-width: 1200px) calc(940px - 8vw), 844px\" decoding=\"async\" alt=\"Mum&#x27;s Chicken Mooli\">\n\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>4 chicken breasts, cut into big chunks<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>6 cardamom<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>6 cloves<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>5cm cinnamon stick<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 large onion, finely sliced<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 garlic cloves<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>3.5cm piece of ginger, chopped<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>3 green chillies, seeded<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>juice of 1 lemon<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tsp turmeric<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>50g creamed coconut (and 150ml hot water)<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><ol class=\"method\" start=\"1\"><li>Heat the oil in a pan, add the <strong>4 chicken breasts<\/strong> and quickly fry all over. Remove the chicken with a slotted spoon.<\/li><li>Add more oil to the pan and fry the <strong>6 cardamom<\/strong>, <strong>6 cloves<\/strong> and <strong>5cm cinnamon stick<\/strong> for 1 min.<\/li><li>Add the <strong>1 large onion<\/strong> and fry until soft.<\/li><li>Place the <strong>2 garlic cloves<\/strong>, <strong>3.5cm piece of ginger<\/strong>, <strong>3 green chillies<\/strong> and <strong>juice of 1 lemon<\/strong> in a food processor and work to a smooth paste.<\/li><li>Add the paste to the pan with the <strong>1 tsp turmeric<\/strong> and cook for 5 mins.<\/li><li>Melt the <strong>50g creamed coconut<\/strong> in the <strong>150ml hot water<\/strong> and add to the pan and season.<\/li><li>Simmer for 2 mins, then add the <strong>chicken<\/strong> and any juices.<\/li><li>Simmer for 15-20 mins until tender.<\/li><\/ol><\/section>\n<\/div>\n\n<p class=\"source\"><a href=\"mums-chicken-mooli.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "mums-curry-mince-cobbler", "name": "Mum's Curry Mince Cobbler", "title": "mum's curry mince cobbler", "tags": ["recipe", "beef", "dinner"], "terms": ["baked beans", "beef", "butter", "curry paste", "flour", "milk", "mushroom", "onion", "stock"], "image": true, "serves": "", "time": "", "items": [{"t": "1 onion, sliced", "k": "onion"}, {"t": "500g fresh minced beef", "k": "beef"}, {"t": "100g mushrooms, sliced", "k": "mushroom"}, {"t": "25g flour", "k": "flour"}, {"t": "300ml stock", "k": "stock"}, {"t": "1 x 425g can baked beans", "k": "baked beans"}, {"t": "10-15ml curry concentrate sauce", "k": "curry paste"}, {"t": "225g self-raising flour", "k": "flour"}, {"t": "50g butter", "k": "butter"}, {"t": "150ml milk", "k": "milk"}], "html": "<header><h1>Mum&#x27;s Curry Mince Cobbler<\/h1><p class=\"tags\"><span class=\"tag\">beef<\/span><span class=\"tag\">dinner<\/span><\/p><\/header>\n<img class=\"hero\" src=\"img/mums-curry-mince-cobbler-1600.jpg\" srcset=\"img/mums-curry-mince-cobbler-800.jpg 800w, img/mums-curry-mince-cobbler-1600.jpg 1600w\" sizes=\"(max-width: 500px) calc(100vw - 40px), (max-width: 940px) 92vw, (max-width: 1200px) calc(940px - 8vw), 844px\" decoding=\"async\" alt=\"Mum&#x27;s Curry Mince Cobbler\">\n<p class=\"before\"><strong>Before you start<\/strong> heat the oven to 200°C.<\/p>\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>1 onion, sliced<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>500g fresh minced beef<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>100g mushrooms, sliced<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>25g flour<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>300ml stock<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 x 425g can baked beans<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>10-15ml curry concentrate sauce<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>225g self-raising flour<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>50g butter<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>150ml milk<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><h3>Prepare the meat<\/h3><ol class=\"method\" start=\"1\"><li>Heat oil in a pan and fry the <strong>1 onion<\/strong>, <strong>500g minced beef<\/strong> and <strong>100g mushrooms<\/strong>.<\/li><li>Stir in the <strong>25g flour<\/strong> and cook for 1 min.<\/li><li>Remove from the heat and stir in the <strong>300ml stock<\/strong>.<\/li><li>Return to the heat and bring to the boil, whilst stirring.<\/li><li>Reduce heat and stir in the <strong>425g can baked beans<\/strong>, <strong>10-15ml curry concentrate<\/strong> and seasoning.<\/li><li>Simmer for 10 mins and then turn mixture into an ovenproof casserole dish.<\/li><li>Preheat oven to 200°C.<\/li><\/ol><h3>Prepare the cobblers<\/h3><ol class=\"method\" start=\"8\"><li>Sieve the <strong>225g self-raising flour<\/strong> and a pinch of salt into a bowl and rub in the <strong>50g butter<\/strong>.<\/li><li>Stir in the <strong>150ml milk<\/strong> to form a soft dough.<\/li><li>Roll out dough to 1cm thick. Using a 5cm fluted cutter, stamp out ~10 rounds.<\/li><\/ol><h3>To cook<\/h3><ol class=\"method\" start=\"11\"><li>Place rounds, slightly overlapping, on top of mince mixture and bake for 20 mins.<\/li><\/ol><\/section>\n<\/div>\n\n<p class=\"source\"><a href=\"mums-curry-mince-cobbler.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "mums-german-cheesecake", "name": "Mum's German Cheesecake", "title": "mum's german cheesecake", "tags": ["recipe", "vegetarian", "dessert"], "terms": ["butter", "digestive biscuits", "eggs", "quark", "sugar", "vanilla extract"], "image": false, "serves": "", "time": "", "items": [{"t": "100g packet digestives", "k": "digestive biscuits"}, {"t": "50g butter", "k": "butter"}, {"t": "340g Quark", "k": "quark"}, {"t": "85g caster sugar", "k": "sugar"}, {"t": "1 egg", "k": "eggs"}, {"t": "vanilla extract", "k": "vanilla extract"}], "html": "<header><h1>Mum&#x27;s German Cheesecake<\/h1><p class=\"tags\"><span class=\"tag\">vegetarian<\/span><span class=\"tag\">dessert<\/span><\/p><\/header>\n\n<p class=\"before\"><strong>Before you start<\/strong> heat the oven to 160°C/fan 150°C. Needs 1hr chilling for the base.<\/p>\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>100g packet digestives<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>50g butter<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>340g Quark<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>85g caster sugar<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 egg<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>vanilla extract<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>7&quot; sandwich tin<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><ol class=\"method\" start=\"1\"><li>For the base, put the <strong>100g packet digestives<\/strong> in a food processor and whiz until fine. Melt the <strong>50g butter<\/strong>, add to the <strong>biscuits<\/strong> and mix in the processor until well combined.<\/li><li>Line the tin with foil, tip the mixture and using the back of a spoon, press evenly into the base. Chill for 1hr until firm.<\/li><li>Preheat the oven to 160°C/fan 150°C. Cream the <strong>340g Quark<\/strong>, <strong>85g caster sugar<\/strong>, <strong>1 egg<\/strong> until smooth. Then add the <strong>vanilla extract<\/strong> and mix in.<\/li><li>Spread the mixture on the biscuit base and bake in the centre of the oven for 30-40 mins until set.<\/li><li>Turn off the heat and keep the cheesecake in it until cool. This helps to prevent it cracking. If liked, decorate with double cream and fruit.<\/li><\/ol><\/section>\n<\/div>\n\n<p class=\"source\"><a href=\"mums-german-cheesecake.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "mums-lemon-drizzle-cake", "name": "Mum's Lemon Drizzle Cake", "title": "mum's lemon drizzle cake", "tags": ["recipe", "vegetarian", "snack"], "terms": ["baking powder", "butter", "eggs", "flour", "lemon", "milk", "sugar"], "image": false, "serves": "", "time": "", "items": [{"t": "120g butter", "k": "butter"}, {"t": "170g self raising flour", "k": "flour"}, {"t": "1 tsp baking powder", "k": "baking powder"}, {"t": "170g caster sugar", "k": "sugar"}, {"t": "2 eggs", "k": "eggs"}, {"t": "3 tbsp milk", "k": "milk"}, {"t": "Grated rind of 1 lemon", "k": "lemon"}, {"t": "120g caster sugar", "k": "sugar"}, {"t": "Juice of 1 lemon", "k": "lemon"}], "html": "<header><h1>Mum&#x27;s Lemon Drizzle Cake<\/h1><p class=\"tags\"><span class=\"tag\">vegetarian<\/span><span class=\"tag\">snack<\/span><\/p><\/header>\n\n<p class=\"before\"><strong>Before you start<\/strong> heat the oven to 180°C.<\/p>\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><h3>Cake<\/h3><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>2 greased loaf tins<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>120g butter<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>170g self raising flour<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tsp baking powder<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>170g caster sugar<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 eggs<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>3 tbsp milk<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Grated rind of 1 lemon<\/span><\/label><\/li><\/ul><h3>Drizzle<\/h3><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>120g caster sugar<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Juice of 1 lemon<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><ol class=\"method\" start=\"1\"><li>Beat all cake ingredients together and put into cake tin.<\/li><li>Bake for 40-60 minutes at 180°C.<\/li><li>Mix the <strong>120g caster sugar<\/strong> and <strong>juice of 1 lemon<\/strong> and pour over the cooked cake (whilst still in the tin) and leave to set.<\/li><\/ol><\/section>\n<\/div>\n\n<p class=\"source\"><a href=\"mums-lemon-drizzle-cake.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "mums-lemon-trifle", "name": "Mum's Lemon Trifle", "title": "mum's lemon trifle", "tags": ["recipe", "vegetarian", "dessert"], "terms": ["butter", "double cream", "eggs", "lemon", "sugar", "trifle sponges"], "image": true, "serves": "", "time": "", "items": [{"t": "8 trifle sponges, split in ½ lengthways", "k": "trifle sponges"}, {"t": "120g butter", "k": "butter"}, {"t": "180g caster sugar", "k": "sugar"}, {"t": "4 eggs, separated", "k": "eggs"}, {"t": "2 large lemons, rind and juiced", "k": "lemon"}, {"t": "300ml whipping cream (to decorate)", "k": "double cream"}], "html": "<header><h1>Mum&#x27;s Lemon Trifle<\/h1><p class=\"tags\"><span class=\"tag\">vegetarian<\/span><span class=\"tag\">dessert<\/span><\/p><\/header>\n<img class=\"hero\" src=\"img/mums-lemon-trifle-1600.jpg\" srcset=\"img/mums-lemon-trifle-800.jpg 800w, img/mums-lemon-trifle-1600.jpg 1600w\" sizes=\"(max-width: 500px) calc(100vw - 40px), (max-width: 940px) 92vw, (max-width: 1200px) calc(940px - 8vw), 844px\" decoding=\"async\" alt=\"Mum&#x27;s Lemon Trifle\">\n<p class=\"before\"><strong>Before you start<\/strong> needs overnight chilling in the fridge.<\/p>\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>8 trifle sponges, split in ½ lengthways<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>120g butter<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>180g caster sugar<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>4 eggs, separated<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 large lemons, rind and juiced<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>300ml whipping cream (to decorate)<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><ol class=\"method\" start=\"1\"><li>Cream the <strong>120g butter<\/strong> and <strong>180g caster sugar<\/strong> until pale and fluffy.<\/li><li>Mix the <strong>4 egg yolks<\/strong> and beat into mixture a little at a time with an electric mixer.<\/li><li>Add the grated rind and juice of the <strong>2 large lemons<\/strong>.<\/li><li>Whisk the <strong>4 egg whites<\/strong> and fold into creamed lemon mixture.<\/li><li>Layer the <strong>8 trifle sponges<\/strong> and mixture into a 2 part souffle dish, starting and finishing with sponge (i.e. 2 layers of cream mixture and 3 layers of sponge).<\/li><li>Cover with foil and chill overnight in the fridge.<\/li><li>Decorate with the <strong>300ml whipped cream<\/strong>.<\/li><\/ol><\/section>\n<\/div>\n\n<p class=\"source\"><a href=\"mums-lemon-trifle.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "nigellas-quick-chilli", "name": "Nigella's Quick Chilli", "title": "nigella's quick chilli", "tags": ["recipe", "beef", "pork", "one-pot", "dinner"], "terms": ["beef", "cardamom", "chilli flakes", "chorizo", "cinnamon", "cumin", "ground coriander", "mixed beans", "pasta sauce", "sweet chilli sauce", "tomato"], "image": true, "serves": "4", "time": "", "items": [{"t": "150g chorizo sausage (not the salami sort), halved lengthways and cut into 5mm half moons", "k": "chorizo"}, {"t": "500g minced beef", "k": "beef"}, {"t": "½ tsp ground cumin", "k": "cumin"}, {"t": "½ tsp ground coriander", "k": "ground coriander"}, {"t": "½ tsp ground cinnamon", "k": "cinnamon"}, {"t": "3 cardamom pods, bruised", "k": "cardamom"}, {"t": "1 x 500g jar good-quality tomato and chunky vegetable sauce for pasta", "k": "pasta sauce"}, {"t": "1 x 390g can mixed spicy beans", "k": "mixed beans"}, {"t": "60ml sweet chilli sauce", "k": "sweet chilli sauce"}, {"t": "¼ tsp chilli flakes (optional, or if your canned beans are not spicy)", "k": "chilli flakes"}], "html": "<header><h1>Nigella&#x27;s Quick Chilli<\/h1><p class=\"meta\">Serves 4<\/p><p class=\"tags\"><span class=\"tag\">beef<\/span><span class=\"tag\">pork<\/span><span class=\"tag\">one-pot<\/span><span class=\"tag\">dinner<\/span><\/p><\/header>\n<img class=\"hero\" src=\"img/nigellas-quick-chilli-1600.jpg\" srcset=\"img/nigellas-quick-chilli-800.jpg 800w, img/nigellas-quick-chilli-1600.jpg 1600w\" sizes=\"(max-width: 500px) calc(100vw - 40px), (max-width: 940px) 92vw, (max-width: 1200px) calc(940px - 8vw), 844px\" decoding=\"async\" alt=\"Nigella&#x27;s Quick Chilli\">\n\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>150g chorizo sausage (not the salami sort), halved lengthways and cut into 5mm half moons<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>500g minced beef<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>½ tsp ground cumin<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>½ tsp ground coriander<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>½ tsp ground cinnamon<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>3 cardamom pods, bruised<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 x 500g jar good-quality tomato and chunky vegetable sauce for pasta<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 x 390g can mixed spicy beans<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>60ml sweet chilli sauce<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>¼ tsp chilli flakes (optional, or if your canned beans are not spicy)<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><ol class=\"method\" start=\"1\"><li>Put the <strong>150g sliced chorizo<\/strong> into a hot, heavy-based pan and cook over a medium heat until the sausage crisps a little and gives up its orange-red oil.<\/li><li>Add the <strong>500g minced beef<\/strong> and cook for about 5 minutes, breaking it up with a wooden fork to help it brown.<\/li><li>Stir in the <strong>½ tsp ground cumin<\/strong>, <strong>½ tsp ground coriander<\/strong>, <strong>½ tsp ground cinnamon<\/strong> and <strong>3 bruised cardamom pods<\/strong>, then add the <strong>500g jar tomato and vegetable pasta sauce<\/strong>, <strong>390g can spicy beans<\/strong> and <strong>60ml sweet chilli sauce<\/strong>. Also add the <strong>¼ tsp chilli flakes<\/strong> if you need more heat, or if you&#x27;ve managed only to find some regular canned beans.<\/li><li>Bring to the boil, then turn down the heat and simmer for 20 minutes.<\/li><li>You can eat this with rice or just as it is. If you&#x27;re not adding any rice, consider dolloping with a blob of sour cream and sprinkling over some grated cheese and chopped coriander.<\/li><\/ol><\/section>\n<\/div>\n<section class=\"notes\"><h2>Notes<\/h2><p>More Tex Mex than Mex, but none the worse for it — a simple, speedy supper.<\/p><p>If you&#x27;ve got a rice cooker, put the rice in to steam before you make the chilli.<\/p><\/section>\n<p class=\"source\">Source: Nigella Lawson, p.236<\/p><p class=\"source\"><a href=\"nigellas-quick-chilli.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "paneer-butter-masala", "name": "Paneer Butter Masala", "title": "paneer butter masala", "tags": ["recipe", "vegetarian", "one-pot", "dinner"], "terms": ["almonds", "butter", "chilli powder", "cinnamon", "cloves", "double cream", "fenugreek", "garlic", "ginger", "honey", "onion", "paneer", "passata", "peas"], "image": true, "serves": "4", "time": "", "items": [{"t": "500g hard paneer, cut into 2cm cubes", "k": "paneer"}, {"t": "3 tbsp unsalted butter", "k": "butter"}, {"t": "1 large brown onion, finely chopped", "k": "onion"}, {"t": "4cm ginger, peeled and grated", "k": "ginger"}, {"t": "6 cloves of garlic, crushed", "k": "garlic"}, {"t": "800g tomato passata", "k": "passata"}, {"t": "1 tbsp kasoori methi (dried fenugreek leaves)", "k": "fenugreek"}, {"t": "1 tsp ground cinnamon", "k": "cinnamon"}, {"t": "¼ tsp ground cloves", "k": "cloves"}, {"t": "½ tsp chilli powder", "k": "chilli powder"}, {"t": "2 tbsp honey", "k": "honey"}, {"t": "250g peas (fresh or defrosted)", "k": "peas"}, {"t": "100ml double cream (& extra to serve)", "k": "double cream"}, {"t": "handful of toasted, flaked almonds", "k": "almonds"}], "html": "<header><h1>Paneer Butter Masala<\/h1><p class=\"meta\">Serves 4<\/p><p class=\"tags\"><span class=\"tag\">vegetarian<\/span><span class=\"tag\">one-pot<\/span><span class=\"tag\">dinner<\/span><\/p><\/header>\n<img class=\"hero\" src=\"img/paneer-butter-masala-1600.jpg\" srcset=\"img/paneer-butter-masala-800.jpg 800w, img/paneer-butter-masala-1600.jpg 1600w\" sizes=\"(max-width: 500px) calc(100vw - 40px), (max-width: 940px) 92vw, (max-width: 1200px) calc(940px - 8vw), 844px\" decoding=\"async\" alt=\"Paneer Butter Masala\">\n\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>vegetable / rapeseed oil<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>500g hard paneer, cut into 2cm cubes<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>3 tbsp unsalted butter<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 large brown onion, finely chopped<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>4cm ginger, peeled and grated<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>6 cloves of garlic, crushed<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>800g tomato passata<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tbsp kasoori methi (dried fenugreek leaves)<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tsp ground cinnamon<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>¼ tsp ground cloves<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>½ tsp chilli powder<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 tbsp honey<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1½ tsp salt<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>250g peas (fresh or defrosted)<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>100ml double cream (&amp; extra to serve)<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>handful of toasted, flaked almonds<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><ol class=\"method\" start=\"1\"><li>Put 1 tbsp of <strong>oil<\/strong> into a large lidded frying pan over a medium heat and, when hot, add the cubes of <strong>500g hard paneer<\/strong>. Fry for a couple of minutes until golden on all sides, turning regularly, then remove to a plate.<\/li><li>Put the <strong>3 tbsp unsalted butter<\/strong> into the same pan over a medium heat. When hot, add the <strong>1 large brown onion<\/strong> and fry for around 10 minutes until translucent and turning golden.<\/li><li>Add the <strong>4cm ginger<\/strong> and <strong>6 cloves of garlic<\/strong>, stir-fry for 2-3 minutes, then add the <strong>800g tomato passata<\/strong>. Cover with the lid and cook for 12-15 minutes until reduced to a lovely thick sauce.<\/li><li>Add the <strong>1 tbsp kasoori methi<\/strong>, <strong>1 tsp ground cinnamon<\/strong>, <strong>¼ tsp ground cloves<\/strong>, <strong>½ tsp chilli powder<\/strong>, <strong>2 tbsp honey<\/strong> and <strong>1½ tsp salt<\/strong> to the pan. Stir, then add the fried <strong>paneer<\/strong>, cover with a lid and cook for 5 minutes, or until cooked through. Add the <strong>250g peas<\/strong> and <strong>100ml double cream<\/strong> and cook for a further 5 minutes.<\/li><li>To serve, scatter with the <strong>handful of toasted, flaked almonds<\/strong> and drizzle with a little extra <strong>cream<\/strong>. This curry is perfect with steamed, basmati rice.<\/li><\/ol><\/section>\n<\/div>\n\n<p class=\"source\"><a href=\"paneer-butter-masala.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "quick-cinnamon-buns", "name": "Quick Cinnamon Buns", "title": "quick cinnamon buns", "tags": ["recipe", "vegetarian", "breakfast", "snack"], "terms": ["baking powder", "butter", "cardamom", "cinnamon", "flour", "milk", "sugar"], "image": true, "serves": "", "time": "", "items": [{"t": "560g plain flour, plus more for rolling", "k": "flour"}, {"t": "2 tbsp baking powder", "k": "baking powder"}, {"t": "2 tsp ground cardamom", "k": "cardamom"}, {"t": "240g unsalted butter, cold, cut into small cubes", "k": "butter"}, {"t": "300g cold milk", "k": "milk"}, {"t": "caster sugar for dipping", "k": "sugar"}, {"t": "75g unsalted butter", "k": "butter"}, {"t": "250g light brown sugar", "k": "sugar"}, {"t": "1 tbsp ground cinnamon", "k": "cinnamon"}], "html": "<header><h1>Quick Cinnamon Buns<\/h1><p class=\"tags\"><span class=\"tag\">vegetarian<\/span><span class=\"tag\">breakfast<\/span><span class=\"tag\">snack<\/span><\/p><\/header>\n<img class=\"hero\" src=\"img/quick-cinnamon-buns-1600.jpg\" srcset=\"img/quick-cinnamon-buns-800.jpg 800w, img/quick-cinnamon-buns-1600.jpg 1600w\" sizes=\"(max-width: 500px) calc(100vw - 40px), (max-width: 940px) 92vw, (max-width: 1200px) calc(940px - 8vw), 844px\" decoding=\"async\" alt=\"Quick Cinnamon Buns\">\n<p class=\"before\"><strong>Before you start<\/strong> heat the oven to 180°C fan.<\/p>\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>560g plain flour, plus more for rolling<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 tbsp baking powder<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 tsp fine sea salt<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 tsp ground cardamom<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>240g unsalted butter, cold, cut into small cubes<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>300g cold milk<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>caster sugar for dipping<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>butter for greasing the tin<\/span><\/label><\/li><\/ul><h3>Filling<\/h3><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>75g unsalted butter<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>250g light brown sugar<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tbsp ground cinnamon<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><ol class=\"method\" start=\"1\"><li>Heat the oven to 180°C fan. Butter a 12-cup deep muffin tray.<\/li><li>First prepare the filling. Melt the <strong>75g unsalted butter<\/strong> and leave in a warm place so that it remains liquid. Mix together the <strong>250g light brown sugar<\/strong> and <strong>1 tbsp ground cinnamon<\/strong> until no lumps remain, then set aside.<\/li><li>Now make the dough. In the bowl of an electric mixer, combine all the dry ingredients with the cubes of <strong>240g unsalted butter<\/strong> and mix until you have a coarse meal. Slowly pour in the <strong>300g cold milk<\/strong> while the mixture is running, until the dough forms into a ball and comes away from the bowl.<\/li><li>Turn the dough out onto a lightly floured surface and leave to rest for a few minutes. Fold the dough gently over itself once or twice to pull it all together. Let the dough rest a second time, for 10 minutes.<\/li><li>Clear a large surface, dust lightly with more <strong>flour<\/strong> and roll out the dough into a large rectangle until about 5mm thick. Brush the surface of the dough with the melted <strong>butter<\/strong> and, before the butter hardens, sprinkle the <strong>cinnamon sugar<\/strong> on to the butter. You want a good, slightly thick layer.<\/li><li>Now roll the dough up, starting at the long side, keeping it neat and tight. Gently tug the dough towards you to get a taut roll whilst rolling away from you into a spiral. Once it&#x27;s all rolled up, gently squeeze the roll to ensure it&#x27;s the same thickness throughout.<\/li><li>Use a sharp knife to cut the roll crossways into 12 even slices. Take a slice of the cinnamon roll, peel back about 5cm of the loose end of the pastry and fold it back under the roll to loosely cover the bottom of the roll. Place in the muffin tray, flap-side down. Repeat with the remaining slices.<\/li><li>Bake the buns for 25 minutes. As soon as they&#x27;re out of the oven, flip them over on to a wire cooling rack, so that they don&#x27;t stick to the tray. Dip each cinnamon bun into a bowl of <strong>caster sugar<\/strong> and serve straight away.<\/li><\/ol><\/section>\n<\/div>\n\n<p class=\"source\"><a href=\"quick-cinnamon-buns.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "roast-pumpkin-curry", "name": "Roast Pumpkin Curry", "title": "roast pumpkin curry", "tags": ["recipe", "vegan", "dinner"], "terms": ["cardamom", "chilli powder", "coconut milk", "cumin", "curry leaves", "garlic", "ginger", "lime", "mustard seeds", "onion", "pumpkin", "turmeric"], "image": false, "serves": "4", "time": "", "items": [{"t": "½ pumpkin (approx 1kg)", "k": "pumpkin"}, {"t": "½ tsp Sri Lankan curry powder (see first recipe) or 1 tsp chilli powder", "k": "chilli powder"}, {"t": "1 medium red onion, peeled and thinly sliced", "k": "onion"}, {"t": "10 fresh curry leaves", "k": "curry leaves"}, {"t": "3 garlic cloves, peeled and sliced", "k": "garlic"}, {"t": "1 tsp mustard seeds", "k": "mustard seeds"}, {"t": "1 tsp cumin seeds", "k": "cumin"}, {"t": "2 whole cardamom pods, lightly bashed in a pestle and mortar", "k": "cardamom"}, {"t": "200ml coconut milk", "k": "coconut milk"}, {"t": "1½ tsp ground turmeric", "k": "turmeric"}, {"t": "4cm fresh root ginger, peeled and finely sliced or cut into matchsticks", "k": "ginger"}, {"t": "1 lime", "k": "lime"}, {"t": "10 fresh curry leaves", "k": "curry leaves"}], "html": "<header><h1>Roast Pumpkin Curry<\/h1><p class=\"meta\">Serves 4<\/p><p class=\"tags\"><span class=\"tag\">vegan<\/span><span class=\"tag\">dinner<\/span><\/p><\/header>\n\n<p class=\"before\"><strong>Before you start<\/strong> heat the oven to 220°C/fan 200°C/gas 7.<\/p>\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>½ pumpkin (approx 1kg)<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 tbsp coconut or vegetable oil<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>salt, to taste<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>½ tsp Sri Lankan curry powder (see first recipe) or 1 tsp chilli powder<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 medium red onion, peeled and thinly sliced<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>10 fresh curry leaves<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>3 garlic cloves, peeled and sliced<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tsp mustard seeds<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tsp cumin seeds<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 whole cardamom pods, lightly bashed in a pestle and mortar<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>200ml coconut milk<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1½ tsp ground turmeric<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>4cm fresh root ginger, peeled and finely sliced or cut into matchsticks<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 lime<\/span><\/label><\/li><\/ul><h3>For the tempering<\/h3><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>1 tbsp coconut or vegetable oil<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>10 fresh curry leaves<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><ol class=\"method\" start=\"1\"><li>First, roast the <strong>½ pumpkin<\/strong>. Preheat the oven to 220°C/fan 200°C/gas 7. Scoop out the seeds with a spoon and discard. Cut the pumpkin into wedges around 2cm thick (leave the skin on).<\/li><li>Place on a baking tray and toss in <strong>1 tbsp of the coconut or vegetable oil<\/strong> and sprinkle with <strong>salt<\/strong> and <strong>¼ tsp of the curry powder<\/strong>, mixing well. Roast for 20 to 25 minutes until tender and golden and starting to brown at the edges. Remove from the oven and leave to cool on the tray.<\/li><li>To make the curry, heat a medium-sized wok or saucepan over a medium-high flame. Add the <strong>remaining 1 tbsp of oil<\/strong>, and, when hot, fry the <strong>1 medium red onion<\/strong> until translucent.<\/li><li>Add the <strong>10 fresh curry leaves<\/strong> and <strong>3 garlic cloves<\/strong>, and, about a minute later, add the <strong>1 tsp mustard seeds<\/strong>, <strong>1 tsp cumin seeds<\/strong> and <strong>2 cardamom pods<\/strong>. Fry the mixture for one minute, being careful not to burn the spices, stirring and adding a little more oil if necessary.<\/li><li>Pour in the <strong>200ml coconut milk<\/strong> and add the <strong>1½ tsp ground turmeric<\/strong> and remaining <strong>¼ tsp of curry powder<\/strong>, <strong>1 tsp of salt<\/strong> and two pieces of the roasted <strong>pumpkin<\/strong> for flavour. Cook so that the curry is gently bubbling for three to four minutes, then turn off the flame.<\/li><li>Dish up by placing the roasted <strong>pumpkin<\/strong> wedges on a plate, and spooning the curry liquor over and around the pumpkin.<\/li><li>Heat up the <strong>1 tbsp oil<\/strong> for the tempering in a small pan and add the <strong>10 fresh curry leaves<\/strong>, letting them crisp up.<\/li><li>Scatter the tempered <strong>curry leaves<\/strong> over the pumpkin curry, add the <strong>4cm fresh root ginger<\/strong> and finish with squeezing over the <strong>1 lime<\/strong>.<\/li><\/ol><\/section>\n<\/div>\n<section class=\"notes\"><h2>Notes<\/h2><p>Prep time: 15 minutes. Cooking time: 40 minutes.<\/p><\/section>\n<p class=\"source\"><a href=\"roast-pumpkin-curry.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "roast-spiced-winter-roots-with-haricot-mash", "name": "Roast Spiced Winter Roots with Haricot Mash", "title": "roast spiced winter roots with haricot mash", "tags": ["recipe", "vegan", "potato", "dinner"], "terms": ["beetroot", "butter beans", "carrot", "chilli flakes", "cumin", "garlic", "ground coriander", "lemon", "parsley", "potato", "white beans"], "image": true, "serves": "4", "time": "", "items": [{"t": "500g beetroot, small", "k": "beetroot"}, {"t": "500g potatoes, small", "k": "potato"}, {"t": "8 carrots, small, slim", "k": "carrot"}, {"t": "2 large garlic cloves", "k": "garlic"}, {"t": "2 tsp cumin seeds", "k": "cumin"}, {"t": "2 tsp coriander seeds", "k": "ground coriander"}, {"t": "a pinch of dried chilli flakes", "k": "chilli flakes"}, {"t": "2 x 400g tins haricot, cannellini or butter beans", "k": "butter beans"}, {"t": "a good handful of parsley leaves", "k": "parsley"}, {"t": "1 tbsp lemon juice", "k": "lemon"}], "html": "<header><h1>Roast Spiced Winter Roots with Haricot Mash<\/h1><p class=\"meta\">Serves 4<\/p><p class=\"tags\"><span class=\"tag\">vegan<\/span><span class=\"tag\">potato<\/span><span class=\"tag\">dinner<\/span><\/p><\/header>\n<img class=\"hero\" src=\"img/roast-spiced-winter-roots-with-haricot-mash-1600.jpg\" srcset=\"img/roast-spiced-winter-roots-with-haricot-mash-800.jpg 800w, img/roast-spiced-winter-roots-with-haricot-mash-1600.jpg 1600w\" sizes=\"(max-width: 500px) calc(100vw - 40px), (max-width: 940px) 92vw, (max-width: 1200px) calc(940px - 8vw), 844px\" decoding=\"async\" alt=\"Roast Spiced Winter Roots with Haricot Mash\">\n<p class=\"before\"><strong>Before you start<\/strong> heat the oven to 180°C fan/gas 6.<\/p>\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>500g beetroot, small<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>500g potatoes, small<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>8 carrots, small, slim<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 large garlic cloves<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 tsp cumin seeds<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 tsp coriander seeds<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>½ tsp sea salt<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>a pinch of dried chilli flakes<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>4 tbsp groundnut oil<\/span><\/label><\/li><\/ul><h3>For the mash<\/h3><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>2 x 400g tins haricot, cannellini or butter beans<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 tbsp olive oil<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>a good handful of parsley leaves<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tbsp lemon juice<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><ol class=\"method\" start=\"1\"><li>Peel and crush the <strong>2 large garlic cloves<\/strong> to a paste. Using a spice mill or pestle and mortar, crush the <strong>2 tsp cumin<\/strong> and <strong>2 tsp coriander seeds<\/strong> to a coarse powder, then mix in the <strong>½ tsp sea salt<\/strong> and several grinds of <strong>black pepper<\/strong>.<\/li><li>Add the <strong>pinch of dried chilli flakes<\/strong> and stir in the crushed <strong>garlic<\/strong> and <strong>4 tbsp groundnut oil<\/strong>. Set the oven at 180°C fan/gas 6.<\/li><li>Bring a couple of deep pans of water to the boil. Trim the <strong>500g beetroot<\/strong>, without breaking the skin, then put them in the water and let them cook for 25-30 minutes, depending on their size, until they are soft enough to pierce easily with a skewer. Cut the <strong>500g potatoes<\/strong> in half and add them to the second pan and boil them for 15 minutes.<\/li><li>Drain the beetroot and cut them in half. If they are large, cut them into wedges. Drain the potatoes. Slice the <strong>8 carrots<\/strong> in half. Toss the carrots, beetroot and potatoes in the spiced oil then transfer to a roasting tin and bake for 35-45 minutes. (I like to turn each one over halfway through cooking so they get evenly browned.)<\/li><li>To make the mash, drain the <strong>2 x 400g tins of beans<\/strong> and put them in a small pan, just covered with water. Bring to the boil, then lower the heat and leave to simmer for 10 minutes.<\/li><li>Drain and return the beans to the empty pan, add the <strong>2 tbsp olive oil<\/strong>, <strong>a good handful of parsley leaves<\/strong>, a little <strong>black pepper<\/strong> and the <strong>1 tbsp lemon juice<\/strong>, then mash to a smooth purée with a potato masher or food processor.<\/li><li>Pile the mashed beans on a serving dish, then place the roasted spiced roots on top and serve.<\/li><\/ol><\/section>\n<\/div>\n<section class=\"notes\"><h2>Notes<\/h2><p>Vegan.<\/p><\/section>\n<p class=\"source\"><a href=\"roast-spiced-winter-roots-with-haricot-mash.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "roasted-aubergine-hispi-cabbage-zaatar-chickpeas-with-spicy-aubergine-tahini", "name": "Roasted Aubergine, Hispi Cabbage + Za'atar Chickpeas with Spicy Aubergine Tahini", "title": "roasted aubergine, hispi cabbage + za'atar chickpeas with spicy aubergine tahini", "tags": ["recipe", "vegan", "chickpeas", "dinner"], "terms": ["aubergine", "cabbage", "chickpeas", "chilli", "cumin", "lemon", "parsley", "sumac", "tahini", "za'atar"], "image": true, "serves": "4", "time": "1h15m", "items": [{"t": "2 medium aubergines, sliced into rounds", "k": "aubergine"}, {"t": "1 tbsp za'atar spice blend", "k": "za'atar"}, {"t": "1 hispi cabbage (600-700g), cut into 8 wedges", "k": "cabbage"}, {"t": "2 tbsp za'atar spice blend", "k": "za'atar"}, {"t": "1 x 660g jar of Queen Chickpeas, drained and rinsed", "k": "chickpeas"}, {"t": "1 tsp sumac", "k": "sumac"}, {"t": "1 small aubergine", "k": "aubergine"}, {"t": "100g tahini", "k": "tahini"}, {"t": "50g pickled green chillies, roughly chopped", "k": "chilli"}, {"t": "2½ tbsp pickled chilli liquid", "k": "chilli"}, {"t": "30g fresh parsley, chopped", "k": "parsley"}, {"t": "½ large lemon, juice only", "k": "lemon"}, {"t": "1 tsp ground cumin", "k": "cumin"}, {"t": "A small handful of fresh parsley, chopped", "k": "parsley"}, {"t": "A sprinkle of sumac", "k": "sumac"}, {"t": "Sliced green chilli (optional)", "k": "chilli"}], "html": "<header><h1>Roasted Aubergine, Hispi Cabbage + Za&#x27;atar Chickpeas with Spicy Aubergine Tahini<\/h1><p class=\"meta\">Serves 4 · 1h15m<\/p><p class=\"tags\"><span class=\"tag\">vegan<\/span><span class=\"tag\">chickpeas<\/span><span class=\"tag\">dinner<\/span><\/p><p class=\"lede\">A tray of za&#x27;atar-roasted aubergine, charred hispi cabbage and crisp chickpeas, served under a blended aubergine and tahini sauce.<\/p><\/header>\n<img class=\"hero\" src=\"img/roasted-aubergine-hispi-cabbage-zaatar-chickpeas-with-spicy-aubergine-tahini-1600.jpg\" srcset=\"img/roasted-aubergine-hispi-cabbage-zaatar-chickpeas-with-spicy-aubergine-tahini-800.jpg 800w, img/roasted-aubergine-hispi-cabbage-zaatar-chickpeas-with-spicy-aubergine-tahini-1600.jpg 1600w\" sizes=\"(max-width: 500px) calc(100vw - 40px), (max-width: 940px) 92vw, (max-width: 1200px) calc(940px - 8vw), 844px\" decoding=\"async\" alt=\"Roasted Aubergine, Hispi Cabbage + Za&#x27;atar Chickpeas with Spicy Aubergine Tahini\">\n<p class=\"before\"><strong>Before you start<\/strong> heat the oven to 200°C fan. The whole aubergine for the tahini roasts hotter, at 220°C fan, and takes 35-40 minutes, so start it first if you want everything ready together.<\/p>\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><h3>For the roasted aubergine<\/h3><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>2 medium aubergines, sliced into rounds<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>3-4 tbsp olive oil<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tbsp za&#x27;atar spice blend<\/span><\/label><\/li><\/ul><h3>For the roasted hispi and chickpeas<\/h3><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>1 hispi cabbage (600-700g), cut into 8 wedges<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>3 tbsp olive oil<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 tbsp za&#x27;atar spice blend<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 x 660g jar of Queen Chickpeas, drained and rinsed<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tsp sumac<\/span><\/label><\/li><\/ul><h3>For the spicy aubergine tahini<\/h3><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>1 small aubergine<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>100g tahini<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>50g pickled green chillies, roughly chopped<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2½ tbsp pickled chilli liquid<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1-2 tsp sea salt<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>30g fresh parsley, chopped<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>½ large lemon, juice only<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tsp ground cumin<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>50ml olive oil<\/span><\/label><\/li><\/ul><h3>To serve<\/h3><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>A small handful of fresh parsley, chopped<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>A sprinkle of sumac<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Sliced green chilli (optional)<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><h3>To roast the aubergine<\/h3><ol class=\"method\" start=\"1\"><li>Heat the oven to 200°C fan and line a roasting tray with baking parchment.<\/li><li>Toss the <strong>2 medium aubergines<\/strong> with the <strong>3-4 tbsp olive oil<\/strong>, <strong>1 tbsp za&#x27;atar<\/strong> and some salt and pepper.<\/li><li>Spread the <strong>aubergine<\/strong> out on the lined tray and roast for 25-30 minutes, flipping halfway, until golden and soft.<\/li><\/ol><h3>To roast the hispi and chickpeas<\/h3><ol class=\"method\" start=\"4\"><li>Toss the <strong>1 hispi cabbage<\/strong> with 2 tbsp of the <strong>3 tbsp olive oil<\/strong>, 1 tbsp of the <strong>2 tbsp za&#x27;atar<\/strong> and some salt and pepper.<\/li><li>Spread the <strong>cabbage<\/strong> wedges out on a separate roasting tray.<\/li><li>Toss the <strong>660g jar of chickpeas<\/strong> with the remaining <strong>olive oil<\/strong>, the remaining <strong>za&#x27;atar<\/strong> and the <strong>1 tsp sumac<\/strong>, then season with salt and pepper.<\/li><li>Spread the <strong>chickpeas<\/strong> out on the tray next to the cabbage wedges.<\/li><li>Roast for 10-15 minutes, until the cabbage is crisp but still has some bite inside and the chickpeas are just crispy.<\/li><\/ol><h3>To make the spicy aubergine tahini<\/h3><ol class=\"method\" start=\"9\"><li>Roast the <strong>1 small aubergine<\/strong> whole at 220°C fan for 35-40 minutes, until properly soft and collapsed.<\/li><li>Scoop out the flesh and blitz it smooth in a blender or food processor.<\/li><li>Add the <strong>100g tahini<\/strong>, <strong>50g pickled green chillies<\/strong>, <strong>2½ tbsp pickled chilli liquid<\/strong>, <strong>1-2 tsp sea salt<\/strong>, <strong>30g parsley<\/strong>, <strong>juice of ½ large lemon<\/strong>, <strong>1 tsp ground cumin<\/strong> and <strong>50ml olive oil<\/strong>.<\/li><li>Blend until creamy, gradually adding 1-2 tbsp ice-cold water to loosen.<\/li><li>Taste and adjust the seasoning with more salt or lemon.<\/li><\/ol><h3>To assemble<\/h3><ol class=\"method\" start=\"14\"><li>Arrange the roasted <strong>aubergine<\/strong>, <strong>hispi cabbage<\/strong> and crispy <strong>chickpeas<\/strong> in an ovenproof serving dish.<\/li><li>Return the dish to the oven for 5 minutes to bring everything together.<\/li><li>Drizzle generously with the <strong>aubergine tahini<\/strong>.<\/li><li>Finish with the <strong>chopped parsley<\/strong>, a sprinkle of <strong>sumac<\/strong> and <strong>sliced green chilli<\/strong> if you like heat, and serve warm.<\/li><\/ol><\/section>\n<\/div>\n<section class=\"notes\"><h2>Notes<\/h2><p>The source roasts the whole aubergine for the tahini at 220°C fan while the rest of the dish goes in at 200°C fan. Either run it in the oven first and drop the temperature, or accept a slightly longer roast at 200°C fan.<\/p><p>Use milder chillies, or fewer, if you do not want much heat.<\/p><p>From Farmer J&#x27;s cookbook <em>The Farmer&#x27;s Pantry<\/em>.<\/p><\/section>\n<p class=\"source\">Source: <a href=\"https://boldbeanco.com/blogs/beanspo-recipes/roasted-aubergine-hispi-cabbage-zaatar-chickpeas-spicy-aubergine-tahini\" rel=\"noreferrer\">https://boldbeanco.com/blogs/beanspo-recipes/roasted-aubergine-hispi-cabbage-zaatar-chickpeas-spicy-aubergine-tahini<\/a><\/p><p class=\"source\"><a href=\"roasted-aubergine-hispi-cabbage-zaatar-chickpeas-with-spicy-aubergine-tahini.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "roasted-chickpea-and-kale-salad-with-a-creamy-tahini-yoghurt-dressing", "name": "Roasted Chickpea and Kale Salad with a Creamy Tahini + Yoghurt Dressing", "title": "roasted chickpea and kale salad with a creamy tahini + yoghurt dressing", "tags": ["recipe", "vegetarian", "lunch"], "terms": ["chickpeas", "cumin", "garlic", "kale", "lemon", "onion powder", "parmesan", "tahini", "yoghurt"], "image": true, "serves": "", "time": "", "items": [{"t": "1 bunch dinosaur kale, ribs removed and torn into pieces", "k": "kale"}, {"t": "160g tahini", "k": "tahini"}, {"t": "4 tbsp Greek yoghurt", "k": "yoghurt"}, {"t": "3 tbsp lemon juice", "k": "lemon"}, {"t": "3 tsp onion powder", "k": "onion powder"}, {"t": "2 garlic cloves, chopped", "k": "garlic"}, {"t": "1 can chickpeas, drained and pat dry", "k": "chickpeas"}, {"t": "1 tsp garlic powder", "k": "garlic"}, {"t": "1 tsp cumin", "k": "cumin"}, {"t": "shaved ricotta salata or Parmesan cheese", "k": "parmesan"}], "html": "<header><h1>Roasted Chickpea and Kale Salad with a Creamy Tahini + Yoghurt Dressing<\/h1><p class=\"tags\"><span class=\"tag\">vegetarian<\/span><span class=\"tag\">lunch<\/span><\/p><\/header>\n<img class=\"hero\" src=\"img/roasted-chickpea-and-kale-salad-with-a-creamy-tahini-yoghurt-dressing-1600.jpg\" srcset=\"img/roasted-chickpea-and-kale-salad-with-a-creamy-tahini-yoghurt-dressing-800.jpg 800w, img/roasted-chickpea-and-kale-salad-with-a-creamy-tahini-yoghurt-dressing-1600.jpg 1600w\" sizes=\"(max-width: 500px) calc(100vw - 40px), (max-width: 940px) 92vw, (max-width: 1200px) calc(940px - 8vw), 844px\" decoding=\"async\" alt=\"Roasted Chickpea and Kale Salad with a Creamy Tahini + Yoghurt Dressing\">\n<p class=\"before\"><strong>Before you start<\/strong> heat the oven to 190°C. Needs about 1 hour refrigerating.<\/p>\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>1 bunch dinosaur kale, ribs removed and torn into pieces<\/span><\/label><\/li><\/ul><h3>Creamy tahini and yoghurt dressing<\/h3><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>160g tahini<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>4 tbsp Greek yoghurt<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>3 tbsp lemon juice<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>3 tsp onion powder<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>3 tsp salt<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>½ tsp cracked black pepper<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 garlic cloves, chopped<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>6 tbsp water<\/span><\/label><\/li><\/ul><h3>Roasted chickpeas<\/h3><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>1 can chickpeas, drained and pat dry<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 tbsp extra virgin olive oil<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tsp garlic powder<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tsp cumin<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>½ tsp salt<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>¼ tsp cracked black pepper<\/span><\/label><\/li><\/ul><h3>To serve<\/h3><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>shaved ricotta salata or Parmesan cheese<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><ol class=\"method\" start=\"1\"><li>Place all <strong>dressing ingredients<\/strong> into a blender and blend until smooth and desired consistency has been achieved.<\/li><li>Pour dressing into a large mixing bowl, top with the <strong>1 bunch of kale<\/strong> and toss together until kale leaves are fully coated. Refrigerate for about 1 hour.<\/li><li>Preheat oven to 190°C.<\/li><li>Place all <strong>chickpea ingredients<\/strong> into another mixing bowl and toss together until completely combined. Pour mixture onto a baking sheet lined with parchment and roast for about 15 minutes. Toss mixture together with a wooden spoon and continue to roast chickpeas for about 10 minutes. Remove from heat.<\/li><li>Pour the <strong>chickpeas<\/strong> over the dressed kale and finish with the <strong>shaved ricotta salata or Parmesan cheese<\/strong>. Serve.<\/li><\/ol><\/section>\n<\/div>\n\n<p class=\"source\"><a href=\"roasted-chickpea-and-kale-salad-with-a-creamy-tahini-yoghurt-dressing.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "ruby-chicken", "name": "Ruby Chicken", "title": "ruby chicken", "tags": ["recipe", "chicken", "rice", "dinner"], "terms": ["bay leaves", "butter", "cardamom", "chicken", "chilli powder", "cinnamon", "coriander", "cumin", "dill", "double cream", "fenugreek", "garam masala", "garlic", "ginger", "honey", "lime", "pomegranate", "rice", "sugar", "tomato", "yoghurt"], "image": false, "serves": "4", "time": "", "items": [{"t": "55g garlic (13-15 cloves)", "k": "garlic"}, {"t": "30g fresh root ginger", "k": "ginger"}, {"t": "2½ tsp deggi mirch chilli powder", "k": "chilli powder"}, {"t": "50g butter", "k": "butter"}, {"t": "1½ tsp garam masala", "k": "garam masala"}, {"t": "2½ tsp ground cumin", "k": "cumin"}, {"t": "130ml double cream", "k": "double cream"}, {"t": "35g garlic (8-9 cloves)", "k": "garlic"}, {"t": "20g fresh root ginger", "k": "ginger"}, {"t": "1½ tsp deggi mirch chilli powder", "k": "chilli powder"}, {"t": "30g butter", "k": "butter"}, {"t": "1 tsp garam masala", "k": "garam masala"}, {"t": "1 tsp ground cumin", "k": "cumin"}, {"t": "80ml double cream", "k": "double cream"}, {"t": "880g chopped tomatoes", "k": "tomato"}, {"t": "2 bay leaves", "k": "bay leaves"}, {"t": "6 green cardamom pods", "k": "cardamom"}, {"t": "2 black cardamom pods", "k": "cardamom"}, {"t": "2 cinnamon sticks", "k": "cinnamon"}, {"t": "20g granulated sugar", "k": "sugar"}, {"t": "1 tbsp runny honey", "k": "honey"}, {"t": "1½ tsp fresh dill fronds", "k": "dill"}, {"t": "1 tsp dried fenugreek leaves, crushed to powder", "k": "fenugreek"}, {"t": "20g garlic (5-6 cloves)", "k": "garlic"}, {"t": "10g fresh root ginger", "k": "ginger"}, {"t": "1 tsp deggi mirch chilli powder", "k": "chilli powder"}, {"t": "20g unsalted butter (not for marinade)", "k": "butter"}, {"t": "½ tsp garam masala", "k": "garam masala"}, {"t": "1½ tsp ground cumin", "k": "cumin"}, {"t": "50ml double cream (not for marinade)", "k": "double cream"}, {"t": "700g skinless, boneless chicken thighs", "k": "chicken"}, {"t": "2 tsp lime juice", "k": "lime"}, {"t": "75g full-fat Greek yoghurt", "k": "yoghurt"}, {"t": "ginger matchsticks", "k": "ginger"}, {"t": "coriander leaves, chopped", "k": "coriander"}, {"t": "1 tbsp pomegranate seeds", "k": "pomegranate"}, {"t": "basmati rice", "k": "rice"}], "html": "<header><h1>Ruby Chicken<\/h1><p class=\"meta\">Serves 4<\/p><p class=\"tags\"><span class=\"tag\">chicken<\/span><span class=\"tag\">rice<\/span><span class=\"tag\">dinner<\/span><\/p><\/header>\n\n<p class=\"before\"><strong>Before you start<\/strong> needs 6 - 24 hours marinating.<\/p>\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><h3>Total (shopping list — the sum of the two groups below, not extra)<\/h3><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>55g garlic (13-15 cloves)<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>185ml vegetable oil<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>30g fresh root ginger<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>15g fine sea salt<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2½ tsp deggi mirch chilli powder<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>50g butter<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1½ tsp garam masala<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2½ tsp ground cumin<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>130ml double cream<\/span><\/label><\/li><\/ul><h3>Makhani sauce<\/h3><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>35g garlic (8-9 cloves)<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>175ml vegetable oil<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>20g fresh root ginger<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 tsp fine sea salt<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1½ tsp deggi mirch chilli powder<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>30g butter<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tsp garam masala<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tsp ground cumin<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>80ml double cream<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>880g chopped tomatoes<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 bay leaves<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>6 green cardamom pods<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 black cardamom pods<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 cinnamon sticks<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>20g granulated sugar<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tbsp runny honey<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1½ tsp fresh dill fronds<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tsp dried fenugreek leaves, crushed to powder<\/span><\/label><\/li><\/ul><h3>Chicken ruby<\/h3><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>20g garlic (5-6 cloves)<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 tsp vegetable oil<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>10g fresh root ginger<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>5g fine sea salt<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tsp deggi mirch chilli powder<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>20g unsalted butter (not for marinade)<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>½ tsp garam masala<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1½ tsp ground cumin<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>50ml double cream (not for marinade)<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>700g skinless, boneless chicken thighs<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 tsp lime juice<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>75g full-fat Greek yoghurt<\/span><\/label><\/li><\/ul><h3>Garnish and serve with<\/h3><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>ginger matchsticks<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>coriander leaves, chopped<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tbsp pomegranate seeds<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>basmati rice<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><h3>Chicken marinade<\/h3><ol class=\"method\" start=\"1\"><li>Blitz the ingredients together in a blender to a fine paste and transfer to a bowl.<\/li><li>Cut the <strong>700g skinless, boneless chicken thighs<\/strong> into 4cm chunks. Add to marinade and turn to coat.<\/li><li>Cover and leave to marinate for <em>6 - 24 hours<\/em>.<\/li><li>Heat the grill to medium-high and place the chicken on a rack in the grill pan, brush with the melted <strong>20g unsalted butter<\/strong> and grill for 8-10 minutes until cooked through and nicely charred.<\/li><li>Warm up the makhani sauce, <strong>50ml double cream<\/strong> and grilled chicken and simmer very gently for 10 minutes.<\/li><li>Serve the curry garnished with <strong>ginger matchsticks<\/strong>, <strong>chopped coriander<\/strong> and <strong>1 tbsp pomegranate seeds<\/strong>, with a bowl of steamed <strong>basmati rice<\/strong>.<\/li><\/ol><h3>Makhani sauce<\/h3><ol class=\"method\" start=\"7\"><li>Take <strong>half the 35g garlic<\/strong> and finely slice it. Warm a large saucepan over medium high heat and add the <strong>175ml vegetable oil<\/strong>. Toss in the chopped garlic and fry until slightly crispy, and remove and place aside to drain using a slotted spoon. Remove the oil from the heat whilst you do this.<\/li><li>Grind the <strong>remaining half of the garlic<\/strong> and <strong>20g fresh root ginger<\/strong> into a paste.<\/li><li>Blitz the <strong>880g chopped tomatoes<\/strong> to a fine consistency.<\/li><li>Add the <strong>2 bay leaves<\/strong>, <strong>6 green cardamom pods<\/strong>, <strong>2 black cardamom pods<\/strong> and <strong>2 cinnamon sticks<\/strong> to the pan. Let them crackle for 1 minute, stirring gently.<\/li><li>Turn the heat down and add the <strong>garlic &amp; ginger paste<\/strong> allowing it to brown but not burn.<\/li><li>Add the <strong>880g chopped tomatoes<\/strong>, <strong>2 tsp fine sea salt<\/strong>, <strong>1½ tsp deggi mirch chilli powder<\/strong> to the pan. Bring to a rapid simmer and then cook until reduced by half, stirring regularly. This should take about <em>30 minutes<\/em>.<\/li><li>Add the <strong>30g butter<\/strong> and simmer for <em>5 minutes<\/em>.<\/li><li>Add the <strong>1 tsp garam masala<\/strong>, <strong>20g granulated sugar<\/strong>, <strong>1 tbsp runny honey<\/strong>, <strong>1 tsp ground cumin<\/strong>, <strong>crisp garlic<\/strong>, <strong>1 tsp dried fenugreek leaves<\/strong>, and <strong>1½ tsp fresh dill fronds<\/strong> and cook for a further <em>15 minutes<\/em>.<\/li><li>If using the sauce straight away then add the <strong>80ml double cream<\/strong> and simmer gently for 5 minutes. If not, then allow it to cool, cover it and refrigerate it – add the cream whenever you go to eat it.<\/li><\/ol><\/section>\n<\/div>\n<section class=\"notes\"><h2>Notes<\/h2><p>Requires 6 - 24 hours of time to marinate the chicken!<\/p><\/section>\n<p class=\"source\"><a href=\"ruby-chicken.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "salmon-with-coriander-dahl-and-rice", "name": "Salmon with Coriander Dahl and Rice", "title": "salmon with coriander dahl and rice", "tags": ["recipe", "pescatarian", "fish", "rice", "dinner"], "terms": ["chilli flakes", "coriander", "garam masala", "naan", "onion", "red lentils", "rice", "salmon", "stock", "tomato", "turmeric"], "image": true, "serves": "", "time": "", "items": [{"t": "150g red lentils", "k": "red lentils"}, {"t": "800ml chicken stock", "k": "stock"}, {"t": "2 onions, grated", "k": "onion"}, {"t": "4 tomatoes, chopped", "k": "tomato"}, {"t": "1 tsp turmeric", "k": "turmeric"}, {"t": "2 tsp garam masala (plus extra for the salmon)", "k": "garam masala"}, {"t": "chilli flakes", "k": "chilli flakes"}, {"t": "coriander", "k": "coriander"}, {"t": "4 salmon fillets", "k": "salmon"}, {"t": "rice/naan to serve", "k": "rice"}], "html": "<header><h1>Salmon with Coriander Dahl and Rice<\/h1><p class=\"tags\"><span class=\"tag\">pescatarian<\/span><span class=\"tag\">fish<\/span><span class=\"tag\">rice<\/span><span class=\"tag\">dinner<\/span><\/p><\/header>\n<img class=\"hero\" src=\"img/salmon-with-coriander-dahl-and-rice-1600.jpg\" srcset=\"img/salmon-with-coriander-dahl-and-rice-800.jpg 800w, img/salmon-with-coriander-dahl-and-rice-1600.jpg 1600w\" sizes=\"(max-width: 500px) calc(100vw - 40px), (max-width: 940px) 92vw, (max-width: 1200px) calc(940px - 8vw), 844px\" decoding=\"async\" alt=\"Salmon with Coriander Dahl and Rice\">\n\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>150g red lentils<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>800ml chicken stock<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 onions, grated<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>4 tomatoes, chopped<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tsp turmeric<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 tsp garam masala (plus extra for the salmon)<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>chilli flakes<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>coriander<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>4 salmon fillets<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>nut/sunflower oil<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>rice/naan to serve<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><ol class=\"method\" start=\"1\"><li>Put the <strong>150g red lentils<\/strong>, <strong>800ml chicken stock<\/strong>, <strong>2 grated onions<\/strong>, <strong>4 chopped tomatoes<\/strong>, <strong>1 tsp turmeric<\/strong>, <strong>2 tsp garam masala<\/strong> and <strong>chilli flakes<\/strong> in a pan, bring to a simmer and cover and cook for 20 minutes until the lentils are tender.<\/li><li>Stir in the <strong>coriander<\/strong>.<\/li><li>Rub the <strong>4 salmon fillets<\/strong> with <strong>nut/sunflower oil<\/strong>, seasoning and extra <strong>garam masala<\/strong>.<\/li><li>Grill the salmon for 6-7 mins until just cooked.<\/li><li>Break the salmon into large chunks and gently stir through the dahl.<\/li><li>Serve with <strong>rice/naan<\/strong>.<\/li><\/ol><\/section>\n<\/div>\n\n<p class=\"source\"><a href=\"salmon-with-coriander-dahl-and-rice.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "sausage-casserole-hairy-bikers", "name": "Sausage Casserole (Hairy Bikers)", "title": "sausage casserole (hairy bikers)", "tags": ["recipe", "pork", "dinner"], "terms": ["bacon", "bay leaves", "butter beans", "chilli powder", "garlic", "mixed beans", "mixed herbs", "onion", "paprika", "pork sausages", "stock", "sugar", "thyme", "tomato", "tomato purée", "white wine", "worcestershire sauce"], "image": true, "serves": "", "time": "", "items": [{"t": "12 good quality pork sausages", "k": "pork sausages"}, {"t": "6 rashers rindless streaky bacon, cut into 2.5cm lengths", "k": "bacon"}, {"t": "2 medium onions, thinly sliced", "k": "onion"}, {"t": "2 garlic cloves, crushed", "k": "garlic"}, {"t": "½–1 tsp hot chilli powder or smoked paprika", "k": "paprika"}, {"t": "1 x 400g can chopped tomatoes", "k": "tomato"}, {"t": "300ml chicken stock", "k": "stock"}, {"t": "2 tbsp tomato purée", "k": "tomato purée"}, {"t": "1 tbsp Worcestershire sauce", "k": "worcestershire sauce"}, {"t": "1 tbsp dark brown muscovado sugar", "k": "sugar"}, {"t": "1 tsp dried mixed herbs", "k": "mixed herbs"}, {"t": "2 bay leaves", "k": "bay leaves"}, {"t": "3–4 sprigs of fresh thyme", "k": "thyme"}, {"t": "100ml red or white wine (optional)", "k": "white wine"}, {"t": "1 x 400g can butter beans or mixed beans", "k": "butter beans"}], "html": "<header><h1>Sausage Casserole (Hairy Bikers)<\/h1><p class=\"tags\"><span class=\"tag\">pork<\/span><span class=\"tag\">dinner<\/span><\/p><\/header>\n<img class=\"hero\" src=\"img/sausage-casserole-hairy-bikers-1600.jpg\" srcset=\"img/sausage-casserole-hairy-bikers-800.jpg 800w, img/sausage-casserole-hairy-bikers-1600.jpg 1600w\" sizes=\"(max-width: 500px) calc(100vw - 40px), (max-width: 940px) 92vw, (max-width: 1200px) calc(940px - 8vw), 844px\" decoding=\"async\" alt=\"Sausage Casserole (Hairy Bikers)\">\n\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>1–2 tbsp sunflower oil<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>12 good quality pork sausages<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>6 rashers rindless streaky bacon, cut into 2.5cm lengths<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 medium onions, thinly sliced<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 garlic cloves, crushed<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>½–1 tsp hot chilli powder or smoked paprika<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 x 400g can chopped tomatoes<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>300ml chicken stock<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 tbsp tomato purée<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tbsp Worcestershire sauce<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tbsp dark brown muscovado sugar<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tsp dried mixed herbs<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 bay leaves<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>3–4 sprigs of fresh thyme<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>100ml red or white wine (optional)<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 x 400g can butter beans or mixed beans<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>salt and freshly ground black pepper<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><ol class=\"method\" start=\"1\"><li>Heat <strong>1 tbsp of the sunflower oil<\/strong> in a large non-stick frying pan and fry the <strong>12 sausages<\/strong> gently for 10 minutes, turning every now and then until nicely browned all over. Transfer to a large saucepan or flameproof casserole dish and set aside.<\/li><li>Fry the <strong>6 rashers of bacon<\/strong> in the frying pan until they begin to brown and crisp, then add to the sausages.<\/li><li>Place the <strong>2 onions<\/strong> in the frying pan and fry over a medium heat for five minutes until they start to soften, stirring often. You should have enough fat in the pan, but if not, add a little more oil.<\/li><li>Add the <strong>2 garlic cloves<\/strong> and cook for 2–3 minutes more until the onions turn pale golden-brown, stirring frequently.<\/li><li>Sprinkle over the <strong>½–1 tsp chilli powder or smoked paprika<\/strong> and cook together for a few seconds longer.<\/li><li>Stir in the <strong>400g chopped tomatoes<\/strong>, <strong>300ml chicken stock<\/strong>, <strong>2 tbsp tomato purée<\/strong>, <strong>1 tbsp Worcestershire sauce<\/strong>, <strong>1 tbsp muscovado sugar<\/strong> and <strong>1 tsp dried mixed herbs<\/strong>.<\/li><li>Pour over the <strong>100ml wine<\/strong>, or some water if you&#x27;re not using wine, and bring to a simmer.<\/li><li>Tip carefully into the pan with the sausages and bacon and return to a simmer, then reduce the heat, cover loosely with a lid and leave to simmer very gently for 20 minutes, stirring from time to time.<\/li><li>Drain the <strong>400g butter beans<\/strong> and rinse them in a sieve under cold running water. Stir into the casserole and continue to cook for 10 minutes, stirring occasionally, until the sauce is thick.<\/li><li>Season to taste with <strong>salt and freshly ground black pepper<\/strong> and serve with rice or slices of rustic bread.<\/li><\/ol><\/section>\n<\/div>\n\n<p class=\"source\"><a href=\"sausage-casserole-hairy-bikers.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "smoky-aubergine-red-kidney-bean-tacos-with-crunchy-tahini-slaw", "name": "Smoky Aubergine + Red Kidney Bean Tacos with Crunchy Tahini Slaw", "title": "smoky aubergine + red kidney bean tacos with crunchy tahini slaw", "tags": ["recipe", "vegetarian", "beans", "bread", "dinner"], "terms": ["aubergine", "cabbage", "coriander", "dill", "garlic", "jalapeño", "lime", "mixed herbs", "paprika", "pomegranate molasses", "red kidney beans", "tahini", "tomato", "tomato purée", "tortillas", "yoghurt"], "image": true, "serves": "3", "time": "30m", "items": [{"t": "3 aubergines", "k": "aubergine"}, {"t": "250g cherry plum tomatoes", "k": "tomato"}, {"t": "1 garlic clove, finely sliced", "k": "garlic"}, {"t": "1 tbsp tomato purée", "k": "tomato purée"}, {"t": "2 heaped tsp smoked paprika", "k": "paprika"}, {"t": "1 x 700g jar of Queen Red Beans, drained", "k": "red kidney beans"}, {"t": "25g soft herbs, such as a mix of coriander and dill", "k": "mixed herbs"}, {"t": "1 tbsp Greek yoghurt, or vegan alternative", "k": "yoghurt"}, {"t": "3 tbsp tahini", "k": "tahini"}, {"t": "Juice of ½ lime", "k": "lime"}, {"t": "1 small garlic clove, grated", "k": "garlic"}, {"t": "2 tbsp jalapeños", "k": "jalapeño"}, {"t": "½ white cabbage, finely shredded", "k": "cabbage"}, {"t": "6-10 small soft tortillas", "k": "tortillas"}, {"t": "Pomegranate molasses (optional)", "k": "pomegranate molasses"}], "html": "<header><h1>Smoky Aubergine + Red Kidney Bean Tacos with Crunchy Tahini Slaw<\/h1><p class=\"meta\">Serves 3 · 30m<\/p><p class=\"tags\"><span class=\"tag\">vegetarian<\/span><span class=\"tag\">beans<\/span><span class=\"tag\">bread<\/span><span class=\"tag\">dinner<\/span><\/p><p class=\"lede\">Charred aubergine shredded into blistered tomatoes, smoked paprika and red kidney beans, piled into tortillas with a tahini-dressed cabbage slaw.<\/p><\/header>\n<img class=\"hero\" src=\"img/smoky-aubergine-red-kidney-bean-tacos-with-crunchy-tahini-slaw-1600.jpg\" srcset=\"img/smoky-aubergine-red-kidney-bean-tacos-with-crunchy-tahini-slaw-800.jpg 800w, img/smoky-aubergine-red-kidney-bean-tacos-with-crunchy-tahini-slaw-1600.jpg 1600w\" sizes=\"(max-width: 500px) calc(100vw - 40px), (max-width: 940px) 92vw, (max-width: 1200px) calc(940px - 8vw), 844px\" decoding=\"async\" alt=\"Smoky Aubergine + Red Kidney Bean Tacos with Crunchy Tahini Slaw\">\n<p class=\"before\"><strong>Before you start<\/strong> heat the grill to high.<\/p>\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>3 aubergines<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tbsp olive oil<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>250g cherry plum tomatoes<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 garlic clove, finely sliced<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tbsp tomato purée<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 heaped tsp smoked paprika<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 x 700g jar of Queen Red Beans, drained<\/span><\/label><\/li><\/ul><h3>Tahini dressed slaw<\/h3><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>25g soft herbs, such as a mix of coriander and dill<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tbsp Greek yoghurt, or vegan alternative<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>3 tbsp tahini<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Juice of ½ lime<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 small garlic clove, grated<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 tbsp jalapeños<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>½ white cabbage, finely shredded<\/span><\/label><\/li><\/ul><h3>To serve<\/h3><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>6-10 small soft tortillas<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Pomegranate molasses (optional)<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><ol class=\"method\" start=\"1\"><li>Put the <strong>3 aubergines<\/strong> directly under a hot grill.<\/li><li>Cook, turning regularly, for 10 minutes until totally blackened and collapsing.<\/li><li>Set the aubergines aside to cool slightly.<\/li><li>Heat the <strong>1 tbsp olive oil<\/strong> in a non-stick frying pan over a high heat.<\/li><li>Add the <strong>250g cherry plum tomatoes<\/strong> and cook for 5-6 minutes, until blistered, soft and slightly charred.<\/li><li>Lower the heat, add the <strong>1 garlic clove<\/strong> and fry for 1-2 minutes until fragrant.<\/li><li>Stir through the <strong>1 tbsp tomato purée<\/strong> and <strong>2 heaped tsp smoked paprika<\/strong>, trying not to break up the tomatoes too much.<\/li><li>Set aside a few coriander leaves from the <strong>25g soft herbs<\/strong> for garnish.<\/li><li>Put the remaining <strong>soft herbs<\/strong>, the <strong>1 tbsp Greek yoghurt<\/strong>, <strong>3 tbsp tahini<\/strong>, <strong>juice of ½ lime<\/strong>, <strong>1 small grated garlic clove<\/strong> and <strong>2 tbsp jalapeños<\/strong> into a small bowl with 1 tbsp of water and mix well to combine.<\/li><li>Add more water to loosen the dressing, if necessary.<\/li><li>Dress the <strong>½ white cabbage<\/strong> with the tahini dressing and a pinch of salt.<\/li><li>Once the aubergines are cool enough to handle, peel away the skin and shred the flesh with a fork.<\/li><li>Mash the flesh into smaller pieces.<\/li><li>Stir the aubergine into the tomato mixture.<\/li><li>Add the <strong>700g jar of red kidney beans<\/strong> and season with a good pinch of salt.<\/li><li>Heat a griddle pan over a medium-high heat and quickly griddle the <strong>6-10 small soft tortillas<\/strong> until lightly charred.<\/li><li>Spoon the aubergine and bean mixture onto the tortillas.<\/li><li>Top with the crunchy tahini slaw, then finish with the reserved coriander leaves and a drizzle of <strong>pomegranate molasses<\/strong>, if you like.<\/li><\/ol><\/section>\n<\/div>\n<section class=\"notes\"><h2>Notes<\/h2><p>Griddling the tortillas is optional, but it adds a great charred flavour. You can also do it over a naked flame.<\/p><p>Use a vegan yoghurt in the slaw to make it vegan.<\/p><p>The source lists the beans as drained but its method calls for them &quot;with their bean stock&quot; — draining keeps the filling thick enough for tacos.<\/p><\/section>\n<p class=\"source\">Source: <a href=\"https://boldbeanco.com/blogs/beanspo-recipes/smokey-aubergine-red-bean-tacos-with-crunchy-tahini-slaw\" rel=\"noreferrer\">https://boldbeanco.com/blogs/beanspo-recipes/smokey-aubergine-red-bean-tacos-with-crunchy-tahini-slaw<\/a><\/p><p class=\"source\"><a href=\"smoky-aubergine-red-kidney-bean-tacos-with-crunchy-tahini-slaw.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "sweet-potato-shakshuka", "name": "Sweet Potato Shakshuka", "title": "sweet potato shakshuka", "tags": ["recipe", "vegetarian", "potato", "breakfast", "dinner"], "terms": ["butter", "cheddar", "coriander", "cumin", "eggs", "garlic", "lemon", "onion", "sriracha", "sweet potato"], "image": true, "serves": "", "time": "", "items": [{"t": "1kg sweet potatoes, skin on and scrubbed clean", "k": "sweet potato"}, {"t": "1 small red onion (100g), thinly sliced into rounds", "k": "onion"}, {"t": "2 tbsp lemon juice, divided", "k": "lemon"}, {"t": "150g mature cheddar, roughly grated", "k": "cheddar"}, {"t": "3 garlic cloves, crushed", "k": "garlic"}, {"t": "1 tsp cumin seeds, roughly crushed", "k": "cumin"}, {"t": "8 medium eggs", "k": "eggs"}, {"t": "25g unsalted butter", "k": "butter"}, {"t": "¾ tbsp sriracha", "k": "sriracha"}, {"t": "2 tbsp picked fresh coriander leaves, with some stem attached", "k": "coriander"}], "html": "<header><h1>Sweet Potato Shakshuka<\/h1><p class=\"tags\"><span class=\"tag\">vegetarian<\/span><span class=\"tag\">potato<\/span><span class=\"tag\">breakfast<\/span><span class=\"tag\">dinner<\/span><\/p><\/header>\n<img class=\"hero\" src=\"img/sweet-potato-shakshuka-1600.jpg\" srcset=\"img/sweet-potato-shakshuka-800.jpg 800w, img/sweet-potato-shakshuka-1600.jpg 1600w\" sizes=\"(max-width: 500px) calc(100vw - 40px), (max-width: 940px) 92vw, (max-width: 1200px) calc(940px - 8vw), 844px\" decoding=\"async\" alt=\"Sweet Potato Shakshuka\">\n<p class=\"before\"><strong>Before you start<\/strong> heat the oven to 200°C fan.<\/p>\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>1kg sweet potatoes, skin on and scrubbed clean<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 small red onion (100g), thinly sliced into rounds<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 tbsp lemon juice, divided<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>3 tbsp olive oil, divided<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>150g mature cheddar, roughly grated<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>3 garlic cloves, crushed<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tsp cumin seeds, roughly crushed<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>8 medium eggs<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>25g unsalted butter<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>¾ tbsp sriracha<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 tbsp picked fresh coriander leaves, with some stem attached<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>salt and black pepper, to taste<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><ol class=\"method\" start=\"1\"><li><strong>Prep Sweet Potatoes:<\/strong> Preheat the oven to 200°C fan. Poke the <strong>sweet potatoes (1kg)<\/strong> all over with a fork and place them on a parchment-lined baking tray. Bake for 45–50 minutes until cooked through and softened. Set aside to cool and turn the oven down to 180°C fan.<\/li><li><strong>Pickle Onion:<\/strong> In a small bowl, mix together the <strong>onion (1 small red, 100g)<\/strong>, <strong>lemon juice (1 tbsp)<\/strong>, and a pinch of <strong>salt<\/strong>. Set aside.<\/li><li><strong>Crisp Skins:<\/strong> Remove the cooked potato skins and tear them into roughly 4cm pieces. Transfer the potato flesh to a large bowl. Place the <strong>skins<\/strong> back on the baking tray and toss with <strong>olive oil (1 tbsp)<\/strong>, <strong>salt (¼ tsp)<\/strong>, and a good grind of <strong>pepper<\/strong>. Bake for 8 minutes, or until nicely coloured and starting to crisp up. Set aside.<\/li><li><strong>Make Mash:<\/strong> Use a fork to mash the <strong>potato flesh<\/strong> until smooth. Add the <strong>cheddar (150g)<\/strong>, <strong>garlic (3 cloves)<\/strong>, <strong>cumin (1 tsp)<\/strong>, <strong>olive oil (another tbsp)<\/strong>, the <strong>remaining lemon juice (1 tbsp)<\/strong>, <strong>salt (1 tsp)<\/strong>, and a generous grind of <strong>pepper<\/strong>. Mix to combine.<\/li><li><strong>Shakshuka Base:<\/strong> Put the <strong>remaining olive oil (1 tbsp)<\/strong> into a large, lidded frying pan. Spoon the <strong>mashed potato mixture<\/strong> into the pan and distribute it evenly. Place on a medium-high heat and cook for about 7 minutes to colour the bottom.<\/li><li><strong>Add Eggs:<\/strong> Turn the heat down to medium and use a spoon to make eight wells in the potato mixture, breaking an <strong>egg (1 medium)<\/strong> into each. Sprinkle lightly with <strong>salt and pepper<\/strong>, cover with the lid, and cook for 4–5 minutes, rotating the pan, until the whites are set and the yolks are still runny.<\/li><li><strong>Make Sriracha Butter:<\/strong> While the eggs cook, put the <strong>butter (25g)<\/strong> and <strong>sriracha (¾ tbsp)<\/strong> into a small saucepan on a medium heat. Cook until the butter has melted, whisking constantly to emulsify. Remove the mixture from the heat before it starts to bubble.<\/li><li><strong>Serve:<\/strong> Spoon the <strong>sriracha butter<\/strong> all over the eggs. Top with a good handful of the crispy <strong>potato skins<\/strong>, <strong>half the pickled onion<\/strong>, and all the <strong>coriander leaves (2 tbsp)<\/strong>. Serve right away, with the rest of the <strong>potato skins<\/strong> and <strong>pickled onion<\/strong> to eat alongside.<\/li><\/ol><\/section>\n<\/div>\n\n<p class=\"source\">Source: <a href=\"https://thehappyfoodie.co.uk/recipes/ottolenghi-sweet-potato-shakshuka/\" rel=\"noreferrer\">https://thehappyfoodie.co.uk/recipes/ottolenghi-sweet-potato-shakshuka/<\/a><\/p><p class=\"source\"><a href=\"sweet-potato-shakshuka.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "the-ultimate-smoky-double-bean-chilli", "name": "The Ultimate Smoky Double-Bean Chilli", "title": "the ultimate smoky double-bean chilli", "tags": ["recipe", "vegetarian", "beans", "one-pot", "dinner"], "terms": ["avocado", "black beans", "cheddar", "chilli", "chilli powder", "chipotle", "cinnamon", "coriander", "cumin", "dark chocolate", "feta", "garlic", "lime", "onion", "paprika", "red kidney beans", "red pepper", "rice", "soured cream", "stock", "tomato", "tomato purée", "worcestershire sauce", "yoghurt"], "image": true, "serves": "6-8", "time": "1h", "items": [{"t": "1 dried ancho chilli (optional)", "k": "chilli"}, {"t": "2 large onions, roughly chopped", "k": "onion"}, {"t": "2 red peppers, diced", "k": "red pepper"}, {"t": "4 garlic cloves, finely grated", "k": "garlic"}, {"t": "2 tsp ground cumin", "k": "cumin"}, {"t": "2 tsp smoked paprika", "k": "paprika"}, {"t": "1 tsp ground cinnamon", "k": "cinnamon"}, {"t": "½-1 tsp chilli powder, or to taste", "k": "chilli powder"}, {"t": "1 heaped tbsp chipotle chilli paste", "k": "chipotle"}, {"t": "2 tbsp tomato purée", "k": "tomato purée"}, {"t": "400g chopped tomatoes", "k": "tomato"}, {"t": "250ml vegetable or beef stock", "k": "stock"}, {"t": "1 tbsp Worcestershire sauce", "k": "worcestershire sauce"}, {"t": "20g dark chocolate (75-90%)", "k": "dark chocolate"}, {"t": "1 x 570g jar of Queen Black Beans, with their bean stock", "k": "black beans"}, {"t": "1 x 700g jar of Queen Red Beans, with their bean stock", "k": "red kidney beans"}, {"t": "Cooked rice", "k": "rice"}, {"t": "Sour cream or yoghurt", "k": "soured cream"}, {"t": "Sliced avocado", "k": "avocado"}, {"t": "Pickled red onions", "k": "onion"}, {"t": "Fresh coriander, chopped", "k": "coriander"}, {"t": "Grated cheddar or crumbled feta", "k": "cheddar"}, {"t": "Lime wedges", "k": "lime"}], "html": "<header><h1>The Ultimate Smoky Double-Bean Chilli<\/h1><p class=\"meta\">Serves 6-8 · 1h<\/p><p class=\"tags\"><span class=\"tag\">vegetarian<\/span><span class=\"tag\">beans<\/span><span class=\"tag\">one-pot<\/span><span class=\"tag\">dinner<\/span><\/p><p class=\"lede\">A meat-free chilli of black and red kidney beans slowly simmered with ancho and chipotle chillies, warm spices and dark chocolate in a rich tomato base.<\/p><\/header>\n<img class=\"hero\" src=\"img/the-ultimate-smoky-double-bean-chilli-1600.jpg\" srcset=\"img/the-ultimate-smoky-double-bean-chilli-800.jpg 800w, img/the-ultimate-smoky-double-bean-chilli-1600.jpg 1600w\" sizes=\"(max-width: 500px) calc(100vw - 40px), (max-width: 940px) 92vw, (max-width: 1200px) calc(940px - 8vw), 844px\" decoding=\"async\" alt=\"The Ultimate Smoky Double-Bean Chilli\">\n\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>1 dried ancho chilli (optional)<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>3 tbsp olive oil<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 large onions, roughly chopped<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 red peppers, diced<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>4 garlic cloves, finely grated<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 tsp ground cumin<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 tsp smoked paprika<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tsp ground cinnamon<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>½-1 tsp chilli powder, or to taste<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 heaped tbsp chipotle chilli paste<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 tbsp tomato purée<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>400g chopped tomatoes<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>250ml vegetable or beef stock<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tbsp Worcestershire sauce<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>20g dark chocolate (75-90%)<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 x 570g jar of Queen Black Beans, with their bean stock<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 x 700g jar of Queen Red Beans, with their bean stock<\/span><\/label><\/li><\/ul><h3>To serve<\/h3><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>Cooked rice<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Sour cream or yoghurt<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Sliced avocado<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Pickled red onions<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Fresh coriander, chopped<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Grated cheddar or crumbled feta<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>Lime wedges<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><ol class=\"method\" start=\"1\"><li>Soak the <strong>1 dried ancho chilli<\/strong> in hot water to soften.<\/li><li>Heat the <strong>3 tbsp olive oil<\/strong> in a large heavy-bottomed pan over a medium heat.<\/li><li>Add the <strong>2 large onions<\/strong> and <strong>2 red peppers<\/strong> and cook for 8-10 minutes, until soft and translucent — give them time.<\/li><li>Add the <strong>4 garlic cloves<\/strong> and cook for another minute, until fragrant.<\/li><li>Stir in the <strong>2 tsp ground cumin<\/strong>, <strong>2 tsp smoked paprika<\/strong>, <strong>1 tsp ground cinnamon<\/strong>, <strong>½-1 tsp chilli powder<\/strong> and <strong>1 heaped tbsp chipotle chilli paste<\/strong>.<\/li><li>Cook for 1-2 minutes to toast the spices, adding a splash more oil if needed.<\/li><li>Lift the <strong>ancho chilli<\/strong> out of the water, roughly chop it and add it to the pan with the <strong>2 tbsp tomato purée<\/strong>.<\/li><li>Cook for 2-3 minutes, stirring frequently, until the purée deepens in colour. Add a splash of water if it starts to stick.<\/li><li>Stir in the <strong>400g chopped tomatoes<\/strong>, <strong>250ml stock<\/strong>, <strong>1 tbsp Worcestershire sauce<\/strong> and <strong>20g dark chocolate<\/strong>.<\/li><li>Tip in the <strong>570g jar of black beans<\/strong> and the <strong>700g jar of red kidney beans<\/strong>, both with their bean stock, and stir well to combine.<\/li><li>Bring to a gentle simmer, then reduce the heat to low.<\/li><li>Cook uncovered for 40-50 minutes, stirring occasionally, until the chilli has thickened and the flavours have melded.<\/li><li>If you are serving with <strong>rice<\/strong>, get it on to cook while the chilli simmers.<\/li><li>Check the chilli for seasoning once it is rich and thick.<\/li><li>Divide the <strong>rice<\/strong> between bowls and spoon the chilli over the top.<\/li><li>Top with <strong>sour cream or yoghurt<\/strong>, <strong>sliced avocado<\/strong>, <strong>pickled red onions<\/strong>, <strong>fresh coriander<\/strong> and <strong>grated cheddar or crumbled feta<\/strong>, then finish with a squeeze of <strong>lime<\/strong>.<\/li><\/ol><\/section>\n<\/div>\n<section class=\"notes\"><h2>Notes<\/h2><p>The ancho chilli is optional, but it adds a real depth of smoky heat.<\/p><p>Better the next day — it only improves as it sits, so it is a good one to make ahead.<\/p><p>Crunchy tortilla chips are great for dunking.<\/p><p>Most Worcestershire sauce contains anchovies; use a vegetarian version to keep it meat-free, and swap the topping dairy for plant-based alternatives to make it vegan.<\/p><\/section>\n<p class=\"source\">Source: <a href=\"https://boldbeanco.com/blogs/beanspo-recipes/the-ultimate-smoky-bean-chilli\" rel=\"noreferrer\">https://boldbeanco.com/blogs/beanspo-recipes/the-ultimate-smoky-bean-chilli<\/a><\/p><p class=\"source\"><a href=\"the-ultimate-smoky-double-bean-chilli.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "toms-salmon-wellington", "name": "Tom's Salmon Wellington", "title": "tom's salmon wellington", "tags": ["recipe", "pescatarian", "fish", "pastry", "dinner"], "terms": ["cream cheese", "green beans", "onion", "potato", "puff pastry", "salmon", "spinach", "white wine"], "image": true, "serves": "4", "time": "", "items": [{"t": "6 salmon fillets or 2 sides of salmon", "k": "salmon"}, {"t": "2 rolls of puff pastry", "k": "puff pastry"}, {"t": "2 white onions, diced", "k": "onion"}, {"t": "2 tubs of Philadelphia cream cheese", "k": "cream cheese"}, {"t": "1 large glass of white wine", "k": "white wine"}, {"t": "spinach", "k": "spinach"}, {"t": "various veg to serve; suggested green beans, and roast potatoes", "k": "green beans"}], "html": "<header><h1>Tom&#x27;s Salmon Wellington<\/h1><p class=\"meta\">Serves 4<\/p><p class=\"tags\"><span class=\"tag\">pescatarian<\/span><span class=\"tag\">fish<\/span><span class=\"tag\">pastry<\/span><span class=\"tag\">dinner<\/span><\/p><\/header>\n<img class=\"hero\" src=\"img/toms-salmon-wellington-1600.jpg\" srcset=\"img/toms-salmon-wellington-800.jpg 800w, img/toms-salmon-wellington-1600.jpg 1600w\" sizes=\"(max-width: 500px) calc(100vw - 40px), (max-width: 940px) 92vw, (max-width: 1200px) calc(940px - 8vw), 844px\" decoding=\"async\" alt=\"Tom&#x27;s Salmon Wellington\">\n<p class=\"before\"><strong>Before you start<\/strong> heat the oven to 180°C.<\/p>\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>6 salmon fillets or 2 sides of salmon<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 rolls of puff pastry<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 white onions, diced<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 tubs of Philadelphia cream cheese<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 large glass of white wine<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>spinach<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>various veg to serve; suggested green beans, and roast potatoes<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><ol class=\"method\" start=\"1\"><li>Simmer <strong>butter<\/strong> in a pan and add the <strong>2 diced white onions<\/strong>.<\/li><li>Add the <strong>1 large glass of white wine<\/strong> in and cook it off.<\/li><li>Add the <strong>2 tubs of cream cheese<\/strong> and mix together.<\/li><li>Add the <strong>spinach<\/strong> and season to taste.<\/li><li>Roll out the <strong>2 rolls of puff pastry<\/strong> (it might need 5 mins out of the fridge to warm slightly) so it is in a landscape orientation.<\/li><li>Put a strip of the cream cheese sauce down the middle of the pastry from left to right (i.e. lengthways), with a small margin at either end.<\/li><li>Sit 2 or 3 <strong>fillets of salmon<\/strong> along the strip, end to end and add another layer of sauce on top of them.<\/li><li>Roll up the pastry into a wellie log. One suggested way is to fold each corner of the pastry towards the middle of the pastry (over the salmon) before folding the remaining top and bottom flaps over.<\/li><li>Cook for 30ish mins at 180°C.<\/li><\/ol><\/section>\n<\/div>\n\n<p class=\"source\"><a href=\"toms-salmon-wellington.html\">Open the full page &rarr;<\/a><\/p>"}, {"slug": "tomato-couscous-with-harissa", "name": "Tomato Couscous with Harissa", "title": "tomato couscous with harissa", "tags": ["recipe", "vegan", "couscous", "dinner"], "terms": ["couscous", "cumin", "garlic", "ground coriander", "harissa", "mint", "onion", "parsley", "stock", "tomato"], "image": true, "serves": "3-4", "time": "", "items": [{"t": "750g assorted tomatoes", "k": "tomato"}, {"t": "3 garlic cloves, peeled and crushed", "k": "garlic"}, {"t": "1 medium red onion", "k": "onion"}, {"t": "2 tsp cumin seeds, lightly crushed", "k": "cumin"}, {"t": "2 tsp coriander seeds, coarsely crushed", "k": "ground coriander"}, {"t": "1 tbsp harissa paste", "k": "harissa"}, {"t": "500ml vegetable stock", "k": "stock"}, {"t": "200g quick-cooking couscous", "k": "couscous"}, {"t": "10g mint leaves", "k": "mint"}, {"t": "15g parsley leaves", "k": "parsley"}], "html": "<header><h1>Tomato Couscous with Harissa<\/h1><p class=\"meta\">Serves 3-4<\/p><p class=\"tags\"><span class=\"tag\">vegan<\/span><span class=\"tag\">couscous<\/span><span class=\"tag\">dinner<\/span><\/p><\/header>\n<img class=\"hero\" src=\"img/tomato-couscous-with-harissa-1600.jpg\" srcset=\"img/tomato-couscous-with-harissa-800.jpg 800w, img/tomato-couscous-with-harissa-1600.jpg 1600w\" sizes=\"(max-width: 500px) calc(100vw - 40px), (max-width: 940px) 92vw, (max-width: 1200px) calc(940px - 8vw), 844px\" decoding=\"async\" alt=\"Tomato Couscous with Harissa\">\n<p class=\"before\"><strong>Before you start<\/strong> heat the oven to 180°C fan/gas 6.<\/p>\n<div class=\"columns\">\n<section class=\"ing\"><h2>Ingredients<\/h2><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>750g assorted tomatoes<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>3 garlic cloves, peeled and crushed<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>3 tbsp olive oil<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 medium red onion<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 tsp cumin seeds, lightly crushed<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>2 tsp coriander seeds, coarsely crushed<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>1 tbsp harissa paste<\/span><\/label><\/li><\/ul><h3>For the couscous<\/h3><ul class=\"ingredients\"><li><label><input type=\"checkbox\"><span>500ml vegetable stock<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>200g quick-cooking couscous<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>10g mint leaves<\/span><\/label><\/li><li><label><input type=\"checkbox\"><span>15g parsley leaves<\/span><\/label><\/li><\/ul><\/section>\n<section class=\"meth\"><h2>Method<\/h2><ol class=\"method\" start=\"1\"><li>Cut the larger <strong>750g tomatoes<\/strong> in half and place in a roasting tin, tucking in the smaller ones. Add the <strong>3 garlic cloves<\/strong> and <strong>3 tbsp olive oil<\/strong>. Peel and slice the <strong>1 medium red onion<\/strong> and add it to the tomatoes with a seasoning of <strong>salt and black pepper<\/strong>.<\/li><li>Scatter the crushed <strong>2 tsp cumin<\/strong> and <strong>2 tsp coriander seeds<\/strong> over the tomatoes and onions. Roast at 180°C fan/gas 6 for 35-40 minutes until the tomatoes are soft and the skins lightly browned.<\/li><li>Bring the <strong>500ml vegetable stock<\/strong> to the boil. Place the <strong>200g couscous<\/strong> in a heat-proof bowl, then pour the boiling stock over, cover and leave for 15 minutes. Remove the leaves from the <strong>10g mint<\/strong> and <strong>15g parsley<\/strong> and roughly chop.<\/li><li>Use a fork to lightly crush the tomatoes so the juices bleed into the pan, then stir in the <strong>1 tbsp harissa paste<\/strong>. Run a fork through the couscous to separate the grains, then stir in the chopped herbs. Serve the roast tomatoes and their juices on top of the couscous.<\/li><\/ol><\/section>\n<\/div>\n<section class=\"notes\"><h2>Notes<\/h2><p>Harissa pastes can vary slightly in heat so I suggest starting with a tablespoon then going on from there, to suit your taste. Making this with as many varieties of tomato as I can get hold of, the vibrant scarlets and oranges bring much cheer to a grey winter day. The couscous, though softly cosseting when soaked with rust-red juices could be swapped for rice if you prefer.<\/p><\/section>\n<p class=\"source\"><a href=\"tomato-couscous-with-harissa.html\">Open the full page &rarr;<\/a><\/p>"}];
